insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('forms_bootcamp', 'M0', 'Forms Bootcamp', 'Conjugate all four subjunctive tenses, active & passive', 'Master all four subjunctive tenses in active and passive voice. You''ll conjugate every form from scratch and learn to distinguish subjunctive from indicative on sight. This is the foundation for every other module.', '["Present Active Subjunctive","Present Passive Subjunctive","Imperfect Active Subjunctive","Imperfect Passive Subjunctive","Perfect Active Subjunctive","Perfect Passive Subjunctive","Pluperfect Active Subjunctive","Pluperfect Passive Subjunctive","Indicative vs. Subjunctive recognition"]'::jsonb, 0) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f001', 'forms_bootcamp', 0, 'typein', 'CONJUGATE', 'Give the <strong>1st person singular present active subjunctive</strong> of <span class=''latin-word''>amare</span> (to love).', 'Present active subjunctive: change the characteristic vowel. 1st conj. ā → e.', '["amem"]'::jsonb, null, null, 'The present active subjunctive of 1st conjugation verbs replaces the characteristic -ā- with -ē-: amō → amem, ames, amet...') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f002', 'forms_bootcamp', 1, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural present active subjunctive</strong> of <span class=''latin-word''>monere</span> (to warn).', 'Present active subjunctive: 2nd conj. ē → eā. 3pl ending = -nt.', '["moneant"]'::jsonb, null, null, '2nd conjugation: characteristic -ē- shifts → eā-. 3pl: moneant.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f003', 'forms_bootcamp', 2, 'typein', 'CONJUGATE', 'Give the <strong>2nd person singular present active subjunctive</strong> of <span class=''latin-word''>ducere</span> (to lead).', '3rd conjugation: add -ā- between stem and ending. 2sg = -s.', '["ducas"]'::jsonb, null, null, '3rd conjugation present subjunctive: dūc- + ā + s = dūcās.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f004', 'forms_bootcamp', 3, 'typein', 'CONJUGATE', 'Give the <strong>1st person plural present active subjunctive</strong> of <span class=''latin-word''>audire</span> (to hear).', '4th conjugation: add -iā- after the stem vowel. 1pl = -mus.', '["audiamus"]'::jsonb, null, null, '4th conjugation: aud- + iā + mus = audiāmus.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f005', 'forms_bootcamp', 4, 'typein', 'CONJUGATE', 'Give the <strong>3rd person singular present active subjunctive</strong> of <span class=''latin-word''>esse</span> (to be).', 'esse is irregular in the present subjunctive: sim, sis, sit...', '["sit"]'::jsonb, null, null, 'esse: sim, sīs, sit, sīmus, sītis, sint. Memorize these — they appear constantly.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f006', 'forms_bootcamp', 5, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural present active subjunctive</strong> of <span class=''latin-word''>esse</span>.', 'The 3pl of esse''s present subjunctive is irregular.', '["sint"]'::jsonb, null, null, 'sint (not ''seant'' — esse is fully irregular in the present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f007', 'forms_bootcamp', 6, 'typein', 'CONJUGATE', 'Give the <strong>2nd person plural present passive subjunctive</strong> of <span class=''latin-word''>amare</span>.', 'Build the present active subjunctive base (amē-), then swap active endings for passive.', '["amemini"]'::jsonb, null, null, 'amēminī — 2pl passive ending -minī is added to the present subjunctive stem amē-.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f008', 'forms_bootcamp', 7, 'typein', 'CONJUGATE', 'Give the <strong>3rd person singular present passive subjunctive</strong> of <span class=''latin-word''>ducere</span>.', '3rd conj. present subjunctive stem is dūcā-. 3sg passive = -tur.', '["ducatur"]'::jsonb, null, null, 'dūcātur. 3sg passive ending -tur applied to dūcā- stem.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f010', 'forms_bootcamp', 8, 'typein', 'CONJUGATE', 'Give the <strong>1st person singular imperfect active subjunctive</strong> of <span class=''latin-word''>amare</span>.', 'Imperfect active subjunctive = present active infinitive + personal endings. 1sg = -m.', '["amarem"]'::jsonb, null, null, 'Rule: take the present active infinitive (amāre) and add -m, -s, -t, -mus, -tis, -nt. → amārem.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f011', 'forms_bootcamp', 9, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural imperfect active subjunctive</strong> of <span class=''latin-word''>monere</span>.', 'Infinitive = monēre. Add -nt for 3pl.', '["monerent"]'::jsonb, null, null, 'monēre + nt → monērent.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f012', 'forms_bootcamp', 10, 'typein', 'CONJUGATE', 'Give the <strong>2nd person singular imperfect active subjunctive</strong> of <span class=''latin-word''>ducere</span>.', 'Infinitive of dūcō is dūcere. 2sg = -s.', '["duceres"]'::jsonb, null, null, 'dūcere + s → dūcerēs.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f013', 'forms_bootcamp', 11, 'typein', 'CONJUGATE', 'Give the <strong>1st person plural imperfect active subjunctive</strong> of <span class=''latin-word''>esse</span>.', 'Infinitive of esse = esse. 1pl = -mus.', '["essemus"]'::jsonb, null, null, 'esse + mus → essēmus.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f014', 'forms_bootcamp', 12, 'typein', 'CONJUGATE', 'Give the <strong>3rd person singular imperfect passive subjunctive</strong> of <span class=''latin-word''>amare</span>.', 'Imperfect passive subjunctive: use the infinitive stem + passive ending. 3sg passive = -tur.', '["amaretur"]'::jsonb, null, null, 'amāre- + tur = amārētur. Imperfect passive: infinitive + passive personal endings.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f015', 'forms_bootcamp', 13, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural imperfect passive subjunctive</strong> of <span class=''latin-word''>monere</span>.', 'monēre + passive 3pl ending -ntur.', '["monerentur"]'::jsonb, null, null, 'monēre + ntur → monērentur.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f020', 'forms_bootcamp', 14, 'typein', 'CONJUGATE', 'Give the <strong>1st person singular perfect active subjunctive</strong> of <span class=''latin-word''>amare</span>. (Perf. stem: amāv-)', 'Perfect active subjunctive: perfect stem + -erim, -erīs, -erit...', '["amaverim"]'::jsonb, null, null, 'Perfect active subjunctive = perfect stem + -erim/-erīs/-erit/-erīmus/-erītis/-erint. amāv + erim = amāverim.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f021', 'forms_bootcamp', 15, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural perfect active subjunctive</strong> of <span class=''latin-word''>amare</span>. (Perf. stem: amāv-)', 'Perfect active subjunctive 3pl ending = -erint.', '["amaverint"]'::jsonb, null, null, 'amāv + erint = amāverint.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f022', 'forms_bootcamp', 16, 'typein', 'CONJUGATE', 'Give the <strong>2nd person singular perfect active subjunctive</strong> of <span class=''latin-word''>ducere</span>. (Perf. stem: dūx-)', 'Perfect active subjunctive 2sg = -erīs.', '["duxeris"]'::jsonb, null, null, 'dūx + erīs = dūxerīs.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f023', 'forms_bootcamp', 17, 'typein', 'CONJUGATE', 'The perfect passive subjunctive is formed with the <strong>perfect passive participle</strong> + what?', 'Think: which subjunctive form of esse do you combine it with?', '["sim","sis","sit","simus","sitis","sint","present subjunctive of esse","present subjunctive"]'::jsonb, null, null, 'Perfect passive subjunctive = PPP + present subjunctive of esse (sim/sīs/sit...). E.g., amātus sim = ''I may have been loved.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f024', 'forms_bootcamp', 18, 'typein', 'CONJUGATE', 'Give the <strong>3rd person singular perfect passive subjunctive</strong> of <span class=''latin-word''>amare</span>. (PPP: amātus)', 'PPP (singular, agrees with subject) + 3sg present subjunctive of esse.', '["amatus sit"]'::jsonb, null, null, 'amātus sit (masc. sg.) — PPP + sit. Gender of PPP must agree with subject in actual use.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f030', 'forms_bootcamp', 19, 'typein', 'CONJUGATE', 'Give the <strong>1st person singular pluperfect active subjunctive</strong> of <span class=''latin-word''>amare</span>. (Perf. stem: amāv-)', 'Pluperfect active subjunctive: perfect stem + -issem, -issēs, -isset...', '["amavissem"]'::jsonb, null, null, 'Pluperfect active subjunctive = perfect stem + -issem/-issēs/-isset/-issēmus/-issētis/-issent. amāv + issem = amāvissem.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f031', 'forms_bootcamp', 20, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural pluperfect active subjunctive</strong> of <span class=''latin-word''>ducere</span>. (Perf. stem: dūx-)', 'Pluperfect active subjunctive 3pl = -issent.', '["duxissent"]'::jsonb, null, null, 'dūx + issent = dūxissent.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f032', 'forms_bootcamp', 21, 'typein', 'CONJUGATE', 'Give the <strong>2nd person singular pluperfect active subjunctive</strong> of <span class=''latin-word''>monere</span>. (Perf. stem: monu-)', 'Pluperfect active subjunctive 2sg = -issēs.', '["monuisses"]'::jsonb, null, null, 'monu + issēs = monuissēs.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f033', 'forms_bootcamp', 22, 'typein', 'CONJUGATE', 'The pluperfect passive subjunctive is formed with the <strong>perfect passive participle</strong> + what?', 'Same logic as perfect passive subjunctive, but use which tense of esse?', '["essem","esses","esset","essemus","essetis","essent","imperfect subjunctive of esse","imperfect subjunctive"]'::jsonb, null, null, 'Pluperfect passive subjunctive = PPP + imperfect subjunctive of esse (essem/essēs/esset...). E.g., amātus essem = ''I had been loved (subj.)''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f034', 'forms_bootcamp', 23, 'typein', 'CONJUGATE', 'Give the <strong>3rd person singular pluperfect passive subjunctive</strong> of <span class=''latin-word''>amare</span>. (PPP: amātus)', 'PPP + 3sg imperfect subjunctive of esse.', '["amatus esset"]'::jsonb, null, null, 'amātus esset — PPP + esset.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f035', 'forms_bootcamp', 24, 'typein', 'CONJUGATE', 'Give the <strong>1st person plural pluperfect active subjunctive</strong> of <span class=''latin-word''>audire</span>. (Perf. stem: audīv-)', 'Pluperfect active subjunctive 1pl = -issēmus.', '["audivissemus"]'::jsonb, null, null, 'audīv + issēmus = audīvissēmus.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f040', 'forms_bootcamp', 25, 'mc', 'IDENTIFY', 'Identify the tense and mood of: <span class=''latin-word''>amāret</span>', 'Look at the ending and the infinitive stem pattern.', null, '["Present active subjunctive","Imperfect active subjunctive","Imperfect active indicative","Perfect active subjunctive"]'::jsonb, 'Imperfect active subjunctive', 'amāret = infinitive amāre + t (3sg). This is imperfect active subjunctive. Compare indicative amābat — the -ba- infix is the giveaway for indicative.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f041', 'forms_bootcamp', 26, 'mc', 'IDENTIFY', 'Identify the tense and mood of <span class=''latin-word''>dūxerint</span> in this sentence:<br><strong>Quaerō quō servī equōs dūxerint.</strong>', 'Quaerō quō... introduces an indirect question. What mood does an indirect question need?', null, '["Pluperfect active subjunctive","Future perfect indicative","Perfect active subjunctive","Perfect active indicative"]'::jsonb, 'Perfect active subjunctive', 'dūx- (perfect stem) + -erint. On its own, dūxerint could be perfect subjunctive or future perfect indicative; the sentence decides. Here quō after quaerō begins an indirect question, which always takes the subjunctive, so dūxerint is perfect active subjunctive (primary sequence, time before): ''I am asking where the slaves have led the horses.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f042', 'forms_bootcamp', 27, 'mc', 'IDENTIFY', 'Identify the tense and mood of: <span class=''latin-word''>monuissētis</span>', '-issē- is the tell-tale infix for one tense.', null, '["Perfect active subjunctive","Pluperfect active indicative","Pluperfect active subjunctive","Imperfect active subjunctive"]'::jsonb, 'Pluperfect active subjunctive', 'monu (perf. stem) + issētis = pluperfect active subjunctive 2pl.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f043', 'forms_bootcamp', 28, 'mc', 'IDENTIFY', 'Identify the tense and mood of: <span class=''latin-word''>amēmus</span>', 'The vowel change from -ā- in the stem is the hint.', null, '["Present active indicative","Imperfect active subjunctive","Present active subjunctive","Future active indicative"]'::jsonb, 'Present active subjunctive', 'amēmus: the characteristic vowel -ā- of 1st conj. shifts to -ē- in the present subjunctive. 1pl = -mus.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f044', 'forms_bootcamp', 29, 'mc', 'IDENTIFY', 'Identify the tense and mood of: <span class=''latin-word''>amātus esset</span>', 'This is a two-word periphrastic form.', null, '["Perfect passive indicative","Perfect passive subjunctive","Pluperfect passive subjunctive","Pluperfect passive indicative"]'::jsonb, 'Pluperfect passive subjunctive', 'amātus (PPP) + esset (imperfect subjunctive of esse) = pluperfect passive subjunctive. If it were esset → pluperfect; if sit → perfect passive subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f045', 'forms_bootcamp', 30, 'mc', 'IDENTIFY', 'Identify the tense and mood of: <span class=''latin-word''>amātus sit</span>', 'PPP + which form of esse?', null, '["Pluperfect passive subjunctive","Perfect passive indicative","Present passive subjunctive","Perfect passive subjunctive"]'::jsonb, 'Perfect passive subjunctive', 'amātus (PPP) + sit (3sg present subjunctive of esse) = perfect passive subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f050', 'forms_bootcamp', 31, 'mc', 'DISTINGUISH', 'Which form is <em>indicative</em>, not subjunctive?
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f051', 'forms_bootcamp', 32, 'mc', 'DISTINGUISH', 'Which form is <em>subjunctive</em>?
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f052', 'forms_bootcamp', 33, 'mc', 'DISTINGUISH', 'Which is the correct imperfect active subjunctive of <span class=''latin-word''>esse</span>?', 'Imperfect subjunctive = present infinitive + endings. What is esse''s infinitive?', null, '["erat","fuerit","sit","esset"]'::jsonb, 'esset', 'esse + t = esset. erat = indicative imperfect (3sg). fuerit = perfect subjunctive. sit = present subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f060', 'forms_bootcamp', 34, 'typein', 'PRINCIPAL PARTS', 'Complete the paradigm: The four <strong>principal parts</strong> of <span class=''latin-word''>amare</span> are: amō, amāre, amāvī, _____', 'The 4th principal part is the perfect passive participle (PPP).', '["amatum","amatus"]'::jsonb, null, null, 'amātum (supine/4PP) or amātus (PPP, masc. nom. sg.). The PPP amātus/a/um is built on this stem and is required to form passive perfect and pluperfect subjunctives.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f061', 'forms_bootcamp', 35, 'typein', 'CONJUGATE', 'Give the <strong>3rd person singular present active subjunctive</strong> of <span class=''latin-word''>capere</span> (3rd -io conj., perf. cēpī).', '3rd -iō verbs follow the 4th conjugation pattern in the present subjunctive.', '["capiat"]'::jsonb, null, null, 'cap- + iā + t = capiat. 3rd -iō verbs (like 4th) insert -iā- in the present subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f062', 'forms_bootcamp', 36, 'typein', 'CONJUGATE', 'Give the <strong>1st person singular imperfect active subjunctive</strong> of <span class=''latin-word''>capere</span>.', 'Imperfect subjunctive = present active infinitive + endings. What is capere''s infinitive?', '["caperem"]'::jsonb, null, null, 'capere + m = caperem. Note: the infinitive is capere, NOT *capire.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f063', 'forms_bootcamp', 37, 'typein', 'CONJUGATE', 'Give the <strong>3rd person plural present active subjunctive</strong> of <span class=''latin-word''>posse</span> (to be able).', 'posse is irregular. Its present subjunctive is: possim, possis, possit, possimus, possitis, _____', '["possint"]'::jsonb, null, null, 'possint — 3pl present subjunctive of posse. Note the double -s- (pos + sim paradigm).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f064', 'forms_bootcamp', 38, 'typein', 'CONJUGATE', 'Give the <strong>1st person singular imperfect active subjunctive</strong> of <span class=''latin-word''>posse</span>.', 'Infinitive of posse = posse. Apply the normal imperfect subjunctive rule.', '["possem"]'::jsonb, null, null, 'posse + m = possem. Imperfect subjunctive of posse: possem, possēs, posset, possēmus, possētis, possent.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f065', 'forms_bootcamp', 39, 'mc', 'IDENTIFY', 'What tense and mood is <span class=''latin-word''>portārentur</span>?', 'The -re- + passive ending pattern signals which tense?', null, '["Present passive subjunctive","Imperfect passive indicative","Imperfect passive subjunctive","Pluperfect passive subjunctive"]'::jsonb, 'Imperfect passive subjunctive', 'portāre (infinitive) + ntur = portārentur. Imperfect passive subjunctive. The passive imperfect indicative would be portābantur.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('f066', 'forms_bootcamp', 40, 'mc', 'IDENTIFY', 'What tense and mood is <span class=''latin-word''>dūcāmur</span>?', 'The -ā- infix in a 3rd conjugation verb is telling.', null, '["Future passive indicative","Present passive subjunctive","Imperfect passive subjunctive","Present active subjunctive"]'::jsonb, 'Present passive subjunctive', 'dūcā + mur = present passive subjunctive 1pl. In 3rd conjugation, -ā- signals present subjunctive (compare future indicative dūcēmur with -ē-).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('sequence_of_tenses', 'M1', 'Sequence of Tenses', 'Primary vs. Secondary — the grammar backbone', 'The master framework for all dependent subjunctives. Learn to align the main verb''s sequence (Primary/Secondary) with the relative time of the subordinate clause.', '["Primary Sequence","Secondary Sequence","Relative Time"]'::jsonb, 1) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-101', 'sequence_of_tenses', 0, 'mc', 'SOT RULES', 'Which of the following is a <strong>Secondary (Historical)</strong> tense?', 'Secondary tenses deal with past action.', null, '["Present","Future","Imperfect","Future Perfect"]'::jsonb, 'Imperfect', 'Secondary tenses are Imperfect, Perfect, and Pluperfect. Primary tenses are Present, Future, and Future Perfect.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-102', 'sequence_of_tenses', 1, 'mc', 'SOT RULES', 'Which of the following is a <strong>Primary</strong> tense?', 'Primary tenses deal with present or future action.', null, '["Pluperfect","Imperfect","Perfect","Future Perfect"]'::jsonb, 'Future Perfect', 'Primary tenses are Present, Future, and Future Perfect.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-103', 'sequence_of_tenses', 2, 'mc', 'SOT RULES', 'In Primary Sequence, what subjunctive tense is used to show action happening at the <strong>SAME TIME</strong> as the main verb?', 'Primary + Same Time = ?', null, '["Imperfect Subjunctive","Perfect Subjunctive","Present Subjunctive","Pluperfect Subjunctive"]'::jsonb, 'Present Subjunctive', 'Primary sequence (Present/Fut main verb) uses the Present Subjunctive for simultaneous action.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-104', 'sequence_of_tenses', 3, 'mc', 'SOT RULES', 'In Secondary Sequence, what subjunctive tense is used to show action that happened <strong>BEFORE</strong> the main verb?', 'Secondary + Prior action = ?', null, '["Imperfect Subjunctive","Perfect Subjunctive","Present Subjunctive","Pluperfect Subjunctive"]'::jsonb, 'Pluperfect Subjunctive', 'Secondary sequence (Past main verb) uses the Pluperfect Subjunctive to show an action had already happened.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-105', 'sequence_of_tenses', 4, 'mc', 'SOT RULES', 'In Secondary Sequence, what subjunctive tense is used to show action happening at the <strong>SAME TIME</strong> as the main verb?', 'Secondary + Same Time = ?', null, '["Imperfect Subjunctive","Perfect Subjunctive","Present Subjunctive","Pluperfect Subjunctive"]'::jsonb, 'Imperfect Subjunctive', 'Secondary sequence uses the Imperfect Subjunctive for simultaneous (or subsequent) action.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-106', 'sequence_of_tenses', 5, 'mc', 'SOT RULES', 'In Primary Sequence, what subjunctive tense is used to show action that happened <strong>BEFORE</strong> the main verb?', 'Primary + Prior action = ?', null, '["Imperfect Subjunctive","Perfect Subjunctive","Present Subjunctive","Pluperfect Subjunctive"]'::jsonb, 'Perfect Subjunctive', 'Primary sequence uses the Perfect Subjunctive to show an action happened prior to the present/future main verb.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-201', 'sequence_of_tenses', 6, 'mc', 'MAIN VERB', 'Determine the sequence of the main verb: <strong>Rogat</strong> quid fēcerīs.', 'rogat = he asks.', null, '["Primary","Secondary"]'::jsonb, 'Primary', 'Rogat is present tense, which makes it Primary Sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-202', 'sequence_of_tenses', 7, 'mc', 'MAIN VERB', 'Determine the sequence of the main verb: <strong>Rogāvit</strong> quid facerēs.', 'rogāvit = he asked.', null, '["Primary","Secondary"]'::jsonb, 'Secondary', 'Rogāvit is perfect tense, which makes it Secondary Sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-203', 'sequence_of_tenses', 8, 'mc', 'MAIN VERB', 'Determine the sequence of the main verb: <strong>Audiēbat</strong> tē loquentem.', 'audiēbat = he was hearing.', null, '["Primary","Secondary"]'::jsonb, 'Secondary', 'Audiēbat is imperfect tense, which makes it Secondary Sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-204', 'sequence_of_tenses', 9, 'mc', 'MAIN VERB', 'Determine the sequence of the main verb: <strong>Dīcet</strong> sē ventūrum esse.', 'dīcet = he will say.', null, '["Primary","Secondary"]'::jsonb, 'Primary', 'Dīcet is future tense, which makes it Primary Sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-205', 'sequence_of_tenses', 10, 'mc', 'MAIN VERB', 'Determine the sequence of the main verb: <strong>Cucurrerant</strong> ut hostem effugerent.', 'cucurrerant = they had run.', null, '["Primary","Secondary"]'::jsonb, 'Secondary', 'Cucurrerant is pluperfect tense, which makes it Secondary Sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-301', 'sequence_of_tenses', 11, 'mc', 'APPLY SOT', 'Rogat quid <strong>faciant</strong>. (He asks what they are doing.)<br>Why is <em>faciant</em> in the present subjunctive?', 'Look at the main verb ''rogat''.', null, '["Secondary sequence, simultaneous action","Primary sequence, prior action","Primary sequence, simultaneous action","Secondary sequence, prior action"]'::jsonb, 'Primary sequence, simultaneous action', 'Rogat (present = primary sequence). Faciant (present subj = same time). He asks (now) what they are doing (now).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-302', 'sequence_of_tenses', 12, 'mc', 'APPLY SOT', 'Rogābat quid <strong>fēcissent</strong>. (He was asking what they had done.)<br>Why is <em>fēcissent</em> in the pluperfect subjunctive?', 'Look at the main verb ''rogābat''.', null, '["Secondary sequence, simultaneous action","Primary sequence, prior action","Secondary sequence, prior action","Primary sequence, simultaneous action"]'::jsonb, 'Secondary sequence, prior action', 'Rogābat (imperfect = secondary sequence). Fēcissent (pluperfect subj = prior time). He was asking (past) what they had ALREADY done (prior to the asking).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-303', 'sequence_of_tenses', 13, 'mc', 'APPLY SOT', 'Nesciō cūr <strong>vēnerit</strong>. (I do not know why he came.)<br>Why is <em>vēnerit</em> in the perfect subjunctive?', 'Nesciō = present tense.', null, '["Secondary sequence, prior action","Primary sequence, prior action","Primary sequence, simultaneous action","Secondary sequence, simultaneous action"]'::jsonb, 'Primary sequence, prior action', 'Nesciō (present = primary sequence). He ALREADY came, so the action is prior. Primary + prior = perfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-304', 'sequence_of_tenses', 14, 'mc', 'APPLY SOT', 'Mīlitēs pugnāvērunt ut <strong>vincerent</strong>. (The soldiers fought so that they might win.)<br>Why is <em>vincerent</em> in the imperfect subjunctive?', 'pugnāvērunt = perfect tense.', null, '["Primary sequence, simultaneous/subsequent action","Secondary sequence, prior action","Secondary sequence, simultaneous/subsequent action","Primary sequence, prior action"]'::jsonb, 'Secondary sequence, simultaneous/subsequent action', 'Pugnāvērunt (perfect = secondary sequence). Purpose clauses always use simultaneous/subsequent time. Secondary + simultaneous = imperfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-401', 'sequence_of_tenses', 15, 'mc', 'CHOOSE TENSE', 'Dīcit quid heri _______. (He says what you DID yesterday).', 'Dīcit = present. Action is prior.', null, '["faciās","fēcerīs","facerēs","fēcissēs"]'::jsonb, 'fēcerīs', 'Primary sequence + prior action = Perfect subjunctive (fēcerīs).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-402', 'sequence_of_tenses', 16, 'mc', 'CHOOSE TENSE', 'Dīxit quid eō tempore _______. (He said what you WERE DOING at that time).', 'Dīxit = perfect. Action is simultaneous.', null, '["faciās","fēcerīs","facerēs","fēcissēs"]'::jsonb, 'facerēs', 'Secondary sequence + simultaneous action = Imperfect subjunctive (facerēs).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-403', 'sequence_of_tenses', 17, 'mc', 'CHOOSE TENSE', 'Dīxit quid prīdiē _______. (He said what you HAD DONE the day before).', 'Dīxit = perfect. Action is prior.', null, '["faciās","fēcerīs","facerēs","fēcissēs"]'::jsonb, 'fēcissēs', 'Secondary sequence + prior action = Pluperfect subjunctive (fēcissēs).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-404', 'sequence_of_tenses', 18, 'mc', 'CHOOSE TENSE', 'Dīcit quid nunc _______. (He says what you ARE DOING now).', 'Dīcit = present. Action is simultaneous.', null, '["faciās","fēcerīs","facerēs","fēcissēs"]'::jsonb, 'faciās', 'Primary sequence + simultaneous action = Present subjunctive (faciās).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-501', 'sequence_of_tenses', 19, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Rogat quid tū ______ (facere). <br><em>He asks what you are doing (now).</em>', 'Primary + simultaneous = present subjunctive. 2nd person singular.', '["facias"]'::jsonb, null, null, 'faciās. (Present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-502', 'sequence_of_tenses', 20, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Rogat quid tū heri ______ (facere). <br><em>He asks what you did (yesterday).</em>', 'Primary + prior = perfect subjunctive. 2nd person singular.', '["feceris"]'::jsonb, null, null, 'fēcerīs. (Perfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-503', 'sequence_of_tenses', 21, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Rogābat quid tū ______ (facere). <br><em>He was asking what you were doing.</em>', 'Secondary + simultaneous = imperfect subjunctive. 2nd person singular.', '["faceres"]'::jsonb, null, null, 'facerēs. (Imperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-504', 'sequence_of_tenses', 22, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Rogābat quid tū prīdiē ______ (facere). <br><em>He was asking what you had done.</em>', 'Secondary + prior = pluperfect subjunctive. 2nd person singular.', '["fecisses"]'::jsonb, null, null, 'fēcissēs. (Pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-505', 'sequence_of_tenses', 23, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Nescīmus cūr hostēs ______ (fugere). <br><em>We do not know why the enemies are fleeing.</em>', 'Nescīmus = present. Action = simultaneous. 3rd plural present subjunctive of fugere.', '["fugiant"]'::jsonb, null, null, 'fugiant. (Primary + simultaneous).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-506', 'sequence_of_tenses', 24, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Nesciēbāmus cūr hostēs ______ (fugere). <br><em>We did not know why the enemies were fleeing.</em>', 'Nesciēbāmus = imperfect. Action = simultaneous. 3rd plural imperfect subjunctive of fugere.', '["fugerent"]'::jsonb, null, null, 'fugerent. (Secondary + simultaneous).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-507', 'sequence_of_tenses', 25, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Sciō quārē mīlitēs ______ (vincere). <br><em>I know why the soldiers won.</em>', 'Sciō = present. Action = prior. 3rd plural perfect subjunctive of vincere.', '["vicerint"]'::jsonb, null, null, 'vīcerint. (Primary + prior).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-508', 'sequence_of_tenses', 26, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Scīvī quārē mīlitēs ______ (vincere). <br><em>I knew why the soldiers had won.</em>', 'Scīvī = perfect. Action = prior. 3rd plural pluperfect subjunctive of vincere.', '["vicissent"]'::jsonb, null, null, 'vīcissent. (Secondary + prior).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-509', 'sequence_of_tenses', 27, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Mīlitēs missī sunt ut oppidum ______ (dēfendere). <br><em>The soldiers were sent to defend the town.</em>', 'missī sunt = perfect passive (Secondary). Purpose requires simultaneous/subsequent. 3rd plural imperfect active subjunctive.', '["defenderent"]'::jsonb, null, null, 'dēfenderent. (Secondary sequence -> Imperfect subjunctive for purpose clauses).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-510', 'sequence_of_tenses', 28, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>Imperātor monet mīlitēs nē ______ (discēdere). <br><em>The general warns the soldiers not to leave.</em>', 'monet = present (Primary). Indirect Command requires simultaneous. 3rd plural present active subjunctive.', '["discedant"]'::jsonb, null, null, 'discēdant. (Primary sequence -> Present subjunctive for indirect commands).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-601', 'sequence_of_tenses', 29, 'mc', 'EXAM TRAP', 'Nescio cūr urbs <strong>capta sit</strong>.<br>What is the tense and sequence here?', 'Nescio is present. capta sit is a two-word passive.', null, '["Perfect subjunctive, primary sequence","Pluperfect subjunctive, secondary sequence","Present subjunctive, primary sequence","Imperfect subjunctive, secondary sequence"]'::jsonb, 'Perfect subjunctive, primary sequence', 'Nescio (present) = primary. Capta sit = perfect passive subjunctive (action happened prior). ''I do not know why the city was captured.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-602', 'sequence_of_tenses', 30, 'mc', 'EXAM TRAP', 'Nesciēbam cūr urbs <strong>capta esset</strong>.<br>What is the tense and sequence here?', 'Nesciēbam is imperfect. capta esset is a two-word passive.', null, '["Perfect subjunctive, primary sequence","Pluperfect subjunctive, secondary sequence","Present subjunctive, primary sequence","Imperfect subjunctive, secondary sequence"]'::jsonb, 'Pluperfect subjunctive, secondary sequence', 'Nesciēbam (imperfect) = secondary. Capta esset = pluperfect passive subjunctive (action happened prior). ''I did not know why the city had been captured.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-603', 'sequence_of_tenses', 31, 'typein', 'FORM', 'Translate the verb: <br>He asked why the men <strong>had spoken</strong>. (loquī - deponent) <br>Rogāvit cūr virī ______.', 'Rogāvit = secondary. Action = prior. Need 3rd plural pluperfect subjunctive of a deponent verb (PPP + esse).', '["locuti essent"]'::jsonb, null, null, 'locūtī essent. (Secondary + prior = Pluperfect subjunctive. Because it''s deponent, it looks passive: locūtī + essent).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-604', 'sequence_of_tenses', 32, 'typein', 'FORM', 'Translate the verb: <br>He asks why the men <strong>are speaking</strong>. (loquī - deponent) <br>Rogat cūr virī ______.', 'Rogat = primary. Action = simultaneous. Need 3rd plural present subjunctive of a deponent verb.', '["loquantur"]'::jsonb, null, null, 'loquantur. (Primary + simultaneous = Present subjunctive. Deponent takes passive ending: loqu- + a + ntur).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m1-605', 'sequence_of_tenses', 33, 'mc', 'EXAM TRAP', 'If a main verb is a <strong>Historical Present</strong> (a present tense verb used to narrate past events vividly), what sequence does the subordinate clause usually take?', 'Even though it looks present, it''s narrating the past.', null, '["Primary","Secondary","It takes the indicative","Both are equally common with no preference"]'::jsonb, 'Secondary', 'A historical present can take either sequence, but secondary sequence (imperfect or pluperfect subjunctive) is very common, because the events are really past. Primary sequence also appears, so check the tense of the subjunctive to see which one the writer chose.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('independent_uses', 'M2', 'Independent Subjunctive', 'Hortatory, Jussive, Optative, Deliberative', 'Subjunctives that stand alone in main clauses. Master the Hortatory, Jussive, Optative, and Deliberative uses.', '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 2) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-101', 'independent_uses', 0, 'mc', 'IDENTIFY', '<strong>Eāmus</strong> ad castra statim!<br>Identify the use of the subjunctive.', '1st person plural, encouraging action.', null, '["Jussive","Hortatory","Optative","Deliberative"]'::jsonb, 'Hortatory', 'Hortatory subjunctives are 1st person plural (''Let us...''). Eamus = Let us go.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-102', 'independent_uses', 1, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nē in urbe maneāmus.</strong>', 'maneāmus is 1st person plural. nē makes it negative.', null, '["Let them not stay in the city.","We are not staying in the city.","Let us not stay in the city.","If only we were not in the city."]'::jsonb, 'Let us not stay in the city.', 'Hortatory negative is formed with ''nē''. Maneāmus = let us stay. Nē maneāmus = let us not stay.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-103', 'independent_uses', 2, 'typein', 'FORM', 'Fill in the blank for the Hortatory subjunctive: ''Let us love Rome!''<br>______ Romam!', '1st person plural present active subjunctive of amāre.', '["amemus"]'::jsonb, null, null, 'amēmus (Let us love).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-104', 'independent_uses', 3, 'typein', 'FORM', 'Fill in the blank for the negative Hortatory: ''Let us not run!''<br>______ curramus!', 'What negative word is used for Hortatory subjunctives?', '["ne"]'::jsonb, null, null, 'nē is used for negative Hortatory and Jussive subjunctives. (nōn is only for Deliberative).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-105', 'independent_uses', 4, 'mc', 'IDENTIFY', 'Moriamur et in media arma ruamus. (Vergil)<br>What type of subjunctive are <em>moriamur</em> and <em>ruamus</em>?', '1st person plural.', null, '["Optative","Deliberative","Jussive","Hortatory"]'::jsonb, 'Hortatory', '''Let us die and rush into the middle of the weapons.'' 1st person plural commands.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-106', 'independent_uses', 5, 'typein', 'FORM', 'Give the correct Latin for: ''Let us drink!'' (bibere)', '1st person plural present active subjunctive (3rd conjugation).', '["bibamus"]'::jsonb, null, null, 'bibāmus. (3rd conjugation characteristic vowel is ''a'' in present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-107', 'independent_uses', 6, 'mc', 'TRANSLATE', 'Translate: <strong>Nē dēspērēmus!</strong>', 'dēspērāre = to despair.', null, '["Let us not despair!","They should not despair!","If only we did not despair!","Why shouldn''t we despair?"]'::jsonb, 'Let us not despair!', '1st person plural present subjunctive + nē = negative Hortatory.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-108', 'independent_uses', 7, 'typein', 'FORM', 'Give the correct Latin for: ''Let us leave!'' (discēdere)', '1st person plural present active subjunctive.', '["discedamus"]'::jsonb, null, null, 'discēdāmus. (From discēdere, 3rd conjugation).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-201', 'independent_uses', 8, 'mc', 'IDENTIFY', '<strong>Veniant</strong> omnēs mīlitēs!<br>Identify the use of the subjunctive.', '3rd person plural.', null, '["Jussive","Hortatory","Optative","Deliberative"]'::jsonb, 'Jussive', 'Jussive subjunctives act as 3rd person commands (''Let them...''). Veniant = Let them come.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-202', 'independent_uses', 9, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nē hostēs vincant.</strong>', 'vincant = 3rd plural present subjunctive.', null, '["Let us not conquer the enemies.","Let the enemies not conquer.","The enemies are not conquering.","Why should the enemies conquer?"]'::jsonb, 'Let the enemies not conquer.', 'Negative Jussive. ''Let the enemies not conquer.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-203', 'independent_uses', 10, 'typein', 'FORM', 'Fill in the blank for the Jussive subjunctive: ''Let the king speak!''<br>Rex ______!', '3rd person singular present active subjunctive of dīcere (3rd conj).', '["dicat"]'::jsonb, null, null, 'dīcere -> dīcat (Let him speak).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-204', 'independent_uses', 11, 'typein', 'FORM', 'Fill in the blank for the Jussive subjunctive: ''Let the boys be brave!''<br>Pueri fortes ______!', '3rd person plural present subjunctive of esse.', '["sint"]'::jsonb, null, null, 'sint (Let them be).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-205', 'independent_uses', 12, 'mc', 'IDENTIFY', '<strong>Dicat</strong> quid sentiat.<br>What use is <em>dicat</em>?', '3rd person singular main verb.', null, '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 'Jussive', '''Let him say [what he feels].'' (Note: sentiat is an indirect question, but dicat is independent Jussive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-206', 'independent_uses', 13, 'typein', 'FORM', 'Give the correct Latin for: ''Let the girl read!'' (legere)', '3rd person singular present active subjunctive.', '["legat"]'::jsonb, null, null, 'legat (Jussive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-207', 'independent_uses', 14, 'mc', 'TRANSLATE', 'Translate: <strong>Nē hoc credant.</strong>', 'crēdant = 3rd plural.', null, '["Let us not believe this.","Let them not believe this.","If only they didn''t believe this.","They shouldn''t believe this, should they?"]'::jsonb, 'Let them not believe this.', 'Negative Jussive command. ''Let them not...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-208', 'independent_uses', 15, 'typein', 'FORM', 'Give the correct Latin for: ''Let the general order!'' (imperare)', '1st conjugation, 3rd singular present active subjunctive.', '["imperet"]'::jsonb, null, null, 'imperet. (Characteristic vowel ''a'' shifts to ''e'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-209', 'independent_uses', 16, 'mc', 'IDENTIFY', 'Arma <strong>capiantur</strong> statim!<br>Identify the use of the bolded verb.', '3rd person plural, passive.', null, '["Jussive","Hortatory","Optative","Deliberative"]'::jsonb, 'Jussive', 'Jussive command in the passive voice. ''Let the weapons be taken up immediately!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-301', 'independent_uses', 17, 'mc', 'RULE', 'What tense of the subjunctive is used in an Optative clause to express a wish that is <strong>possible in the future</strong>?', 'The most ''current'' subjunctive tense.', null, '["Present","Imperfect","Perfect","Pluperfect"]'::jsonb, 'Present', 'Present subjunctive is used for future, possible wishes. ''May he survive!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-302', 'independent_uses', 18, 'mc', 'RULE', 'What tense of the subjunctive is used in an Optative clause to express a wish that is <strong>impossible in the present</strong>?', 'Same as the Present Contrary-to-Fact conditional.', null, '["Present","Imperfect","Perfect","Pluperfect"]'::jsonb, 'Imperfect', 'Imperfect subjunctive = impossible present wish. ''If only he were here now (but he isn''t)!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-303', 'independent_uses', 19, 'mc', 'RULE', 'What tense of the subjunctive is used in an Optative clause to express a wish that is <strong>impossible in the past</strong>?', 'Same as the Past Contrary-to-Fact conditional.', null, '["Present","Imperfect","Perfect","Pluperfect"]'::jsonb, 'Pluperfect', 'Pluperfect subjunctive = impossible past wish. ''If only he had not died!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-304', 'independent_uses', 20, 'typein', 'TRIGGER WORD', 'What Latin particle (starting with ''u'') almost always introduces an Optative subjunctive?', 'Means ''if only'' or ''would that''.', '["utinam"]'::jsonb, null, null, 'Utinam is the explicit trigger word for wishes.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-305', 'independent_uses', 21, 'mc', 'TRANSLATE', '<strong>Utinam Romae essem!</strong><br>How is this translated?', 'essem = imperfect subjunctive. This means the wish is impossible right now.', null, '["If only I had been in Rome!","May I be in Rome!","If only I were in Rome!","Let me be in Rome!"]'::jsonb, 'If only I were in Rome!', 'Imperfect subjunctive = present unfulfilled wish. ''If only I were in Rome [but I am currently not].''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-306', 'independent_uses', 22, 'mc', 'TRANSLATE', '<strong>Utinam nē vēnisset!</strong><br>How is this translated?', 'vēnisset = pluperfect subjunctive. This means the wish is impossible in the past.', null, '["If only he would not come!","Let him not come!","If only he had not come!","If only he were not coming!"]'::jsonb, 'If only he had not come!', 'Pluperfect subjunctive = past unfulfilled wish. ''If only he had not come!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-307', 'independent_uses', 23, 'mc', 'IDENTIFY', '<strong>Utinam dī vōbīs pācem dent!</strong><br>What type of wish is this?', 'dent = present subjunctive.', null, '["Future possible wish","Present impossible wish","Past impossible wish","Jussive command"]'::jsonb, 'Future possible wish', 'Present subjunctive = future possible wish. ''May the gods grant you peace!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-308', 'independent_uses', 24, 'typein', 'FORM', 'Translate the verb: ''If only you <strong>had warned</strong> me!''<br>Utinam me ______!', '2nd person singular pluperfect active subjunctive of monēre.', '["monuisses"]'::jsonb, null, null, 'monuisses. Pluperfect because it''s an impossible wish in the past.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-309', 'independent_uses', 25, 'mc', 'NEGATIVE', 'Which word is used to negate an Optative subjunctive?', 'Same as Hortatory and Jussive.', null, '["nōn","nē","nūllus","numquam"]'::jsonb, 'nē', 'Utinam nē (or sometimes just nē) is used to negate a wish.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-310', 'independent_uses', 26, 'mc', 'TRANSLATE', '<strong>Utinam vīveret!</strong><br>How is this translated?', 'vīveret = imperfect subjunctive.', null, '["May he live!","If only he were alive!","If only he had lived!","Let him live!"]'::jsonb, 'If only he were alive!', 'Imperfect subjunctive = impossible present wish. ''If only he were alive (now) [but he is dead].''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-311', 'independent_uses', 27, 'mc', 'TRANSLATE', '<strong>Utinam vincāmus!</strong><br>How is this translated?', 'vincāmus = present subjunctive.', null, '["If only we were winning!","May we win!","If only we had won!","We are going to win!"]'::jsonb, 'May we win!', 'Present subjunctive = future possible wish. ''May we win!''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-312', 'independent_uses', 28, 'typein', 'FORM', 'Give the correct Latin for: ''If only they had fled!'' (fugere)', '3rd person plural pluperfect active subjunctive.', '["fugissent"]'::jsonb, null, null, 'fūgissent. (Pluperfect = past impossible wish).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-313', 'independent_uses', 29, 'typein', 'FORM', 'Give the correct Latin for: ''May the king live!'' (vivere)', '3rd person singular present active subjunctive.', '["vivat"]'::jsonb, null, null, 'vīvat. (Present = future possible wish).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-314', 'independent_uses', 30, 'mc', 'IDENTIFY', 'Which of these correctly expresses: ''If only she were speaking!''', 'Present impossible wish.', null, '["Utinam dīcat!","Utinam dīceret!","Utinam dīxisset!","Utinam nē dīcat!"]'::jsonb, 'Utinam dīceret!', 'Imperfect subjunctive (dīceret) is used for a present impossible wish.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-315', 'independent_uses', 31, 'mc', 'IDENTIFY', 'Which of these correctly expresses: ''If only we had not lost!''', 'Past impossible wish, negative.', null, '["Utinam nē āmīsimus!","Utinam nē āmittāmus!","Utinam nē āmīsissēmus!","Utinam nē āmitterēmus!"]'::jsonb, 'Utinam nē āmīsissēmus!', 'A wish is negated with nē, not nōn, and a wish about the past that can no longer come true takes the pluperfect subjunctive: āmīsissēmus. Āmittāmus (present) is a wish for the future, and āmitterēmus (imperfect) is a wish about the present.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-401', 'independent_uses', 32, 'mc', 'IDENTIFY', '<strong>Quid faciam?</strong><br>Identify the use of the subjunctive.', 'A question asked in doubt, weighing an action.', null, '["Jussive","Hortatory","Optative","Deliberative"]'::jsonb, 'Deliberative', 'Deliberative subjunctives are rhetorical questions weighing a course of action. ''What am I to do?''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-402', 'independent_uses', 33, 'mc', 'TRANSLATE', 'How do you translate: <strong>Quid dicerem?</strong>', 'dīcerem = imperfect subjunctive (past tense doubt).', null, '["What am I to say?","What was I to say?","Let me say something.","If only I had spoken!"]'::jsonb, 'What was I to say?', 'Imperfect deliberative expresses past doubt. ''What was I to say?'' or ''What should I have said?''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-403', 'independent_uses', 34, 'mc', 'NEGATIVE', 'Which word is used to negate a <strong>Deliberative</strong> subjunctive?', 'This is the ONLY independent subjunctive that uses this negative!', null, '["nē","nōn","nē nōn","ut nōn"]'::jsonb, 'nōn', 'Deliberative questions use NŌN. (e.g., Cur nōn eāmus? = Why shouldn''t we go?). Hortatory, Jussive, and Optative all use NĒ.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-404', 'independent_uses', 35, 'typein', 'FORM', 'Fill in the blank for the Deliberative: ''Where are we to remain?''<br>Ubi ______?', '1st person plural present active subjunctive of manēre.', '["maneamus"]'::jsonb, null, null, 'maneāmus (Where are we to stay?)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-405', 'independent_uses', 36, 'mc', 'IDENTIFY', 'Cur <strong>nōn pugnēmus?</strong><br>Identify the use of the subjunctive.', 'It''s a question, and it''s negated by nōn.', null, '["Deliberative","Hortatory","Optative","Jussive"]'::jsonb, 'Deliberative', '''Why should we not fight?'' A rhetorical question weighing a course of action.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-406', 'independent_uses', 37, 'typein', 'FORM', 'Give the correct Latin for: ''What am I to think?'' (putare)', '1st person singular present active subjunctive.', '["putem"]'::jsonb, null, null, 'putem. (1st conjugation present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-407', 'independent_uses', 38, 'mc', 'TRANSLATE', 'Translate: <strong>Quō eam?</strong>', 'quō = to where. eam = 1st sg present subjunctive of īre.', null, '["Where was I going?","Where am I to go?","Let me go there.","If only I were going!"]'::jsonb, 'Where am I to go?', 'Present deliberative expressing current doubt. ''Where am I to go?'' or ''Where should I go?''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-408', 'independent_uses', 39, 'mc', 'TRANSLATE', 'Translate: <strong>Cūr in urbe remanērem?</strong>', 'remanērem = imperfect subjunctive.', null, '["Why should I stay in the city?","Why was I to stay in the city?","Let me not stay in the city.","Why didn''t I stay in the city?"]'::jsonb, 'Why was I to stay in the city?', 'Imperfect deliberative expresses past doubt. ''Why was I to stay...?''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-409', 'independent_uses', 40, 'typein', 'FORM', 'Give the correct Latin for: ''Why shouldn''t we leave?'' (discēdere)', 'Cūr nōn + 1st plural present active subjunctive.', '["discedamus"]'::jsonb, null, null, 'Cūr nōn discēdāmus? (Deliberatives use nōn for negation).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-410', 'independent_uses', 41, 'mc', 'IDENTIFY', 'Which of these is a Deliberative subjunctive?', 'Look for the question mark.', null, '["Utinam fugiam!","Nē fugiamus.","Fugiant statim.","Ubi fugiam?"]'::jsonb, 'Ubi fugiam?', 'Deliberatives are always framed as questions.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-501', 'independent_uses', 42, 'mc', 'MIXED', 'Which of these independent subjunctives uses <strong>NŌN</strong> instead of <strong>NĒ</strong> for its negative?', 'The one that is a question.', null, '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 'Deliberative', 'Deliberative uses nōn. The other three (Hortatory, Jussive, Optative) are all forms of commands/wishes and use nē.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-502', 'independent_uses', 43, 'mc', 'MIXED', 'Read the sentence: <strong>Nē discēdat.</strong><br>What type is it?', '3rd person.', null, '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 'Jussive', '3rd person negative command = Jussive (''Let him not depart'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-503', 'independent_uses', 44, 'mc', 'MIXED', 'Read the sentence: <strong>Utinam nē discessisset!</strong><br>What type is it?', 'Utinam = wish.', null, '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 'Optative', 'Utinam triggers the Optative. Pluperfect makes it an impossible past wish (''If only he had not departed'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-504', 'independent_uses', 45, 'mc', 'MIXED', 'Read the sentence: <strong>Nē discēdāmus.</strong><br>What type is it?', '1st person plural.', null, '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 'Hortatory', '1st person plural negative command = Hortatory (''Let us not depart'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-505', 'independent_uses', 46, 'mc', 'MIXED', 'Read the sentence: <strong>Cūr nōn discēdāmus?</strong><br>What type is it?', 'Question + nōn.', null, '["Hortatory","Jussive","Optative","Deliberative"]'::jsonb, 'Deliberative', 'Question weighing an action = Deliberative (''Why shouldn''t we depart?'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-506', 'independent_uses', 47, 'mc', 'RULE', 'A Present CTF (unfulfilled present) wish uses which tense in the Optative?', 'If only I *were* rich.', null, '["Present","Imperfect","Perfect","Pluperfect"]'::jsonb, 'Imperfect', 'Imperfect Subjunctive = Present Unfulfilled Wish.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-507', 'independent_uses', 48, 'mc', 'RULE', 'A Past CTF (unfulfilled past) wish uses which tense in the Optative?', 'If only I *had* won.', null, '["Present","Imperfect","Perfect","Pluperfect"]'::jsonb, 'Pluperfect', 'Pluperfect Subjunctive = Past Unfulfilled Wish.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-508', 'independent_uses', 49, 'mc', 'MIXED', 'Which of these translations correctly renders <strong>Utinam Caesar adesset!</strong>', 'adesset = imperfect subjunctive.', null, '["May Caesar be present!","If only Caesar were present!","If only Caesar had been present!","Let Caesar be present!"]'::jsonb, 'If only Caesar were present!', 'Imperfect subjunctive means it is a present impossible wish. ''If only Caesar were present [right now, but he is not].''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-601', 'independent_uses', 50, 'mc', 'EXAM TRAP', '<strong>Nē hoc fēcerīs!</strong><br>How is this best translated for a Latin 3 exam?', 'Perfect Subjunctive + nē in the 2nd person.', null, '["You might not do this.","Do not do this!","You didn''t do this.","May you not have done this."]'::jsonb, 'Do not do this!', 'This is the Prohibitive Subjunctive. While it looks like a perfect tense, it functions as a sharp, immediate negative command.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-602', 'independent_uses', 51, 'typein', 'PROHIBITION', 'Translate using the Perfect Subjunctive: ''Do not fear!'' (timēre; stem: timu-)', 'Use ''nē'' + 2nd person singular perfect active subjunctive.', '["ne timueris"]'::jsonb, null, null, 'nē timuerīs. Nē + perfect subjunctive is one standard way to forbid someone. The other is nōlī (or nōlīte) + infinitive: nōlī timēre.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-603', 'independent_uses', 52, 'mc', 'DELIBERATIVE', '<strong>Quid facerem?</strong><br>Translate this rhetorical question.', 'Imperfect subjunctive = past doubt.', null, '["What am I to do?","What was I to do?","What will I do?","What had I done?"]'::jsonb, 'What was I to do?', 'The imperfect subjunctive in a deliberative question refers to a dilemma in the past.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-604', 'independent_uses', 53, 'mc', 'NEGATION', 'Identify the sentence that is grammatically <strong>INCORRECT</strong>:', 'Check the negative words for independent uses.', null, '["Nē eāmus.","Utinam nē vēnisset.","Nē hoc fēceris.","Nē quid agam?"]'::jsonb, 'Nē quid agam?', 'Deliberative questions (Quid agam?) are negated by ''nōn'', not ''nē''. It should be ''Cūr nōn agam?''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m2-605', 'independent_uses', 54, 'typein', 'OPTATIVE', 'Translate into Latin: ''May the gods help us!'' (adiuvāre; 3pl present subjunctive: adiuvent)', 'Use the present subjunctive for a future possible wish. Gods = dī (nom. pl.).', '["di nos adiuvent","utinam di nos adiuvent","dei nos adiuvent","utinam dei nos adiuvent"]'::jsonb, null, null, 'Dī nōs adiuvent! The present subjunctive expresses a wish that can still come true. Utinam may be added: Utinam dī nōs adiuvent!') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('purpose_result_indirect', 'M3', 'Purpose · Result · Indirect Command', 'ut/nē discrimination drills', 'The big three ut-clauses. The TSJCL exam loves to test your ability to tell these apart. Look for trigger words!', '["Purpose Clauses","Result Clauses","Indirect Commands"]'::jsonb, 3) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-101', 'purpose_result_indirect', 0, 'mc', 'TRIGGER', 'Which of the following words in a main clause almost always triggers a <strong>Result</strong> clause?', 'Means ''so'' or ''to such a degree''.', null, '["tamen","tam","tum","tandem"]'::jsonb, 'tam', '''Tam'' (so) is a classic T-word trigger for Result clauses. (e.g., He was SO brave THAT...)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-102', 'purpose_result_indirect', 1, 'mc', 'TRIGGER', 'Which of these verbs triggers an <strong>Indirect Command</strong>?', 'Means ''to order''.', null, '["intellegō","imperō","inveniō","incipiō"]'::jsonb, 'imperō', 'Verbs of ordering, warning, begging, and asking (impero, moneo, oro, rogo, persuadeo) trigger Indirect Commands.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-103', 'purpose_result_indirect', 2, 'mc', 'TRIGGER', 'The words <strong>ita</strong>, <strong>sīc</strong>, and <strong>adeō</strong> trigger which type of clause?', 'They all mean ''so'' or ''in such a way''.', null, '["Purpose","Result","Indirect Command","Indirect Question"]'::jsonb, 'Result', 'These adverbial triggers set up the consequence/result of an action.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-104', 'purpose_result_indirect', 3, 'mc', 'TRIGGER', 'Which of these verbs triggers an <strong>Indirect Command</strong>?', 'Means ''to persuade''.', null, '["perveniō","putō","persuādeō","pellō"]'::jsonb, 'persuādeō', 'Persuadeo (to persuade) takes a dative object and an ut/nē + subjunctive clause.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-201', 'purpose_result_indirect', 4, 'mc', 'DISCRIMINATE', 'Mīlitēs cucurrērunt <strong>ut urbem caperent</strong>.<br>What type of clause is bolded?', 'Answers ''why'' they ran.', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Purpose', 'Purpose clause. There are no ''T-words'' or ordering verbs in the main clause. ''They ran in order to capture the city.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-202', 'purpose_result_indirect', 5, 'mc', 'DISCRIMINATE', 'Puer <strong>tam</strong> dēfessus erat <strong>ut statim dormīret</strong>.<br>What type of clause is bolded?', 'Look at the ''tam'' (so).', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Result', 'Result clause. The ''tam'' triggers the consequence: ''He was SO tired THAT he slept immediately.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-203', 'purpose_result_indirect', 6, 'mc', 'DISCRIMINATE', 'Māter fīlium <strong>monuit nē ad flūmen īret</strong>.<br>What type of clause is bolded?', 'monuit = she warned/advised.', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Indirect Command', 'Indirect Command. Triggered by a verb of warning (monuit).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-204', 'purpose_result_indirect', 7, 'mc', 'DISCRIMINATE', 'Gladiātor <strong>tantā</strong> vī pugnāvit <strong>ut hostem vinceret</strong>.<br>What type of clause is bolded?', 'tantus/a/um = so great / such a great.', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Result', 'Result clause. Triggered by ''tantā'' (with such great force that...).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-205', 'purpose_result_indirect', 8, 'mc', 'DISCRIMINATE', 'Tē <strong>ōrō ut mē iuvēs</strong>.<br>What type of clause is bolded?', 'ōrāre = to beg.', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Indirect Command', 'Indirect command. ''I beg you to help me.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-206', 'purpose_result_indirect', 9, 'mc', 'DISCRIMINATE', 'Lēgātī vēnērunt <strong>ut pācem peterent</strong>.<br>What type of clause is bolded?', 'Why did the envoys come?', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Purpose', 'Purpose clause. ''They came to seek peace.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-301', 'purpose_result_indirect', 10, 'mc', 'NEGATIVE', 'Which of these uses <strong>nē</strong> for its negative form?', 'Two of them do, but Result does NOT.', null, '["Result and Purpose","Purpose and Indirect Command","Result and Indirect Command","Only Result"]'::jsonb, 'Purpose and Indirect Command', 'Both Purpose (''in order that not'') and Indirect Commands (''ordered not to'') use NĒ. Result clauses use UT NŌN.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-302', 'purpose_result_indirect', 11, 'mc', 'NEGATIVE', 'What is the negative word used to introduce a <strong>Result</strong> clause?', 'Result clauses always keep the ''ut''.', null, '["nē","nōn","ut nōn","nē nōn"]'::jsonb, 'ut nōn', 'Result clauses are the exception! They use ''ut nōn'' (or ut nēmō, ut nihil) instead of nē.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-303', 'purpose_result_indirect', 12, 'mc', 'DISCRIMINATE', 'Ita mē gessī <strong>ut nēmō mē reprehenderet</strong>.<br>What type of clause is bolded?', 'ut nēmō = that no one. Also look at ''Ita''.', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Result', 'Result clause. ''I conducted myself in such a way (Ita) that NO ONE (ut nēmō) blamed me.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-304', 'purpose_result_indirect', 13, 'mc', 'DISCRIMINATE', 'Fūgimus <strong>nē pūnīrēmur</strong>.<br>What type of clause is bolded?', 'Why did we flee?', null, '["Result","Purpose","Indirect Command","Indirect Question"]'::jsonb, 'Purpose', 'Negative purpose. ''We fled so that we would not be punished (lest we be punished).''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-305', 'purpose_result_indirect', 14, 'typein', 'NEGATIVE', 'Fill in the correct negative word: <br>Mihi persuasit ______ hoc facerem. (He persuaded me <strong>not</strong> to do this.)', 'Negative Indirect Command.', '["ne"]'::jsonb, null, null, 'nē. Indirect commands use nē to negate.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-401', 'purpose_result_indirect', 15, 'mc', 'RELATIVE PURPOSE', 'Mīsit nūntiōs <strong>quī rēgī haec dīcerent</strong>.<br>How should the bolded clause be translated?', 'qui = in order that they...', null, '["who were saying these things","to say these things to the king","because they said these things","what they said to the king"]'::jsonb, 'to say these things to the king', 'Relative clause of purpose. A relative pronoun (quī) replaces ''ut'' when there is a clear antecedent. ''He sent messengers to say...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-402', 'purpose_result_indirect', 16, 'typein', 'RELATIVE PURPOSE', 'Fill in the blank to create a Relative Purpose clause: <br>Arma cēpit ______ sē dēfenderet. (He took up arms <strong>to</strong> defend himself).', 'Use the relative pronoun (masc, nom, sg) referring back to the implied subject, instead of ''ut''.', '["qui"]'::jsonb, null, null, 'quī. ''He took up arms who might defend himself'' = ''to defend himself.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-501', 'purpose_result_indirect', 17, 'mc', 'SEQUENCE', 'Rogat ut <strong>veniāmus</strong>.<br>Why is the subjunctive in the present tense?', 'Look at ''Rogat''.', null, '["Secondary sequence, simultaneous action","Primary sequence, simultaneous/subsequent action","Primary sequence, prior action","Secondary sequence, prior action"]'::jsonb, 'Primary sequence, simultaneous/subsequent action', 'Rogat is present, so this is primary sequence. Rogat ut is an indirect command, which points forward from the main verb and uses the ''same time'' column: present subjunctive after a primary verb, imperfect after a secondary one. Purpose clauses work the same way. (Result clauses usually do too, though after a past main verb they sometimes use the perfect subjunctive.)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-502', 'purpose_result_indirect', 18, 'mc', 'SEQUENCE', 'Rogāvit ut <strong>venīrēmus</strong>.<br>Why is the subjunctive in the imperfect tense?', 'Look at ''Rogāvit''.', null, '["Secondary sequence, simultaneous/subsequent action","Primary sequence, simultaneous action","Secondary sequence, prior action","Primary sequence, prior action"]'::jsonb, 'Secondary sequence, simultaneous/subsequent action', 'Rogāvit (perfect = secondary). Secondary main verb -> Imperfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-503', 'purpose_result_indirect', 19, 'typein', 'FORM', 'Conjugate the verb to fit the Sequence of Tenses:<br>Venit ut pācem ______ (petere). <br><em>He comes so that he may seek peace.</em>', 'Venit (present). Needs 3rd person singular present subjunctive.', '["petat"]'::jsonb, null, null, 'petat. (Primary sequence).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-504', 'purpose_result_indirect', 20, 'typein', 'FORM', 'Conjugate the verb to fit the Sequence of Tenses:<br>Vēnit ut pācem ______ (petere). <br><em>He came so that he might seek peace.</em>', 'Vēnit (perfect). Needs 3rd person singular imperfect subjunctive.', '["peteret"]'::jsonb, null, null, 'peteret. (Secondary sequence).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-601', 'purpose_result_indirect', 21, 'typein', 'TRANSLATE', 'Type the correct Latin verb: <br>We fight so that we <strong>may be</strong> free.<br>Pugnāmus ut līberī ______ (esse).', '1st person plural present subjunctive of esse.', '["simus"]'::jsonb, null, null, 'sīmus.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-602', 'purpose_result_indirect', 22, 'typein', 'TRANSLATE', 'Type the correct Latin verb: <br>He ordered them <strong>to do</strong> this.<br>Eīs imperāvit ut hoc ______ (facere).', '3rd person plural imperfect subjunctive (secondary sequence).', '["facerent"]'::jsonb, null, null, 'facerent.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-603', 'purpose_result_indirect', 23, 'mc', 'TRANSLATE', 'How do you translate: <strong>Tam clārē dīcit ut omnēs audiant.</strong>', 'Tam = so. audiant = present subjunctive.', null, '["He spoke so clearly that everyone heard.","He speaks so clearly that everyone hears.","He speaks clearly in order that everyone may hear.","He speaks clearly to everyone listening."]'::jsonb, 'He speaks so clearly that everyone hears.', 'Result clause in primary sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-604', 'purpose_result_indirect', 24, 'mc', 'TRANSLATE', 'How do you translate: <strong>Mīlitem rogāvit nē sē pūnīret.</strong>', 'rogāvit = asked. pūnīret = imperfect subjunctive.', null, '["He asked the soldier to punish him.","He asked the soldier not to punish him.","The soldier asked not to be punished.","He punished the soldier so he wouldn''t ask."]'::jsonb, 'He asked the soldier not to punish him.', 'Negative Indirect Command. ''He asked... that he not punish him.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-605', 'purpose_result_indirect', 25, 'typein', 'FORM', 'Type the correct Latin verb: <br>The storm was so great that the ships <strong>were destroyed</strong>.<br>Tanta tempestās erat ut nāvēs ______ (dēlēre).', '3rd person plural imperfect passive subjunctive (2nd conj).', '["delerentur"]'::jsonb, null, null, 'dēlērentur.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-701', 'purpose_result_indirect', 26, 'mc', 'DISCRIMINATE', 'Vēnimus <strong>ut tē iuvārēmus.</strong>', 'No ''so'' word (tam, ita) and no ''ordering'' verb in the main clause.', null, '["Purpose Clause","Result Clause","Indirect Command","Noun Clause"]'::jsonb, 'Purpose Clause', 'This expresses the intent of the coming: ''We came in order to help you.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-702', 'purpose_result_indirect', 27, 'mc', 'DISCRIMINATE', 'Accidit <strong>ut lūna plēna esset.</strong>', 'Accidit (it happens) is an impersonal verb.', null, '["Purpose Clause","Substantive Clause of Result","Indirect Command","Relative Clause"]'::jsonb, 'Substantive Clause of Result', 'Verbs like ''accidit'' (it happens) or ''efficit'' (he brings it about) take result clauses as their direct objects or subjects.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-703', 'purpose_result_indirect', 28, 'typein', 'NEGATIVE', 'Fill in the correct negative: <br>Tam fessus erat ______ dormīret. (He was so tired that he did <strong>not</strong> sleep).', 'Result clauses are the ONLY ones in this group that use ''non''.', '["ut non"]'::jsonb, null, null, 'Result clauses use ''ut nōn'' for negation. Purpose and Indirect Commands would use ''nē''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-704', 'purpose_result_indirect', 29, 'mc', 'TRIGGER', 'Which of these adverbs triggers a <strong>Result</strong> clause?', 'Means ''to such an extent''.', null, '["tamen","adeō","anteā","apud"]'::jsonb, 'adeō', 'Adeō (to such an extent), ita (so/in such a way), and tam (so) are the big result triggers.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-705', 'purpose_result_indirect', 30, 'typein', 'FORM', 'Translate the verb: <br>He ordered the soldiers <strong>to not flee</strong>.<br>Mīlitibus imperāvit ______.', 'Indirect command + negative. 3rd person plural imperfect active subjunctive (secondary sequence).', '["ne fugerent"]'::jsonb, null, null, 'nē fugerent. Imperō takes the Dative + nē + subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-706', 'purpose_result_indirect', 31, 'mc', 'EXAM TRAP', 'How do you translate <strong>nē</strong> in a Purpose Clause?', 'Expresses a negative intention.', null, '["that","lest / in order that... not","that... not","whether"]'::jsonb, 'lest / in order that... not', 'Nē in a purpose clause is ''lest'' or ''so that... not''. (Don''t confuse it with ''that'' in a fear clause!).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-707', 'purpose_result_indirect', 32, 'typein', 'RELATIVE PURPOSE', 'Rewrite using a Relative Purpose Clause: <br>Mīsit nūntiōs <strong>ut pācem peterent</strong>.', 'Replace ''ut'' with the nominative plural masculine relative pronoun.', '["qui pacem peterent"]'::jsonb, null, null, 'quī pācem peterent. Relative pronouns can replace ''ut'' when there is a clear antecedent (nūntiōs).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m3-708', 'purpose_result_indirect', 33, 'mc', 'SOT', 'Pugnant ut <strong>vincant</strong>. <br>If you change ''Pugnant'' to ''Pugnābant'', what does ''vincant'' become?', 'Shift from Primary to Secondary sequence.', null, '["vīcerint","vincerent","vīcissent","vincerentur"]'::jsonb, 'vincerent', 'Secondary sequence (past tense) requires the imperfect subjunctive for simultaneous/subsequent action.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('cum_clauses', 'M4', 'Cum Clauses', 'Circumstantial, Causal, Concessive, Inversum', 'Cum can mean ''with'' (ablative), but with a subjunctive, it means when, since, or although. Know the markers.', '["Circumstantial","Causal","Concessive"]'::jsonb, 4) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-101', 'cum_clauses', 0, 'mc', 'EXAM TRAP', 'Read the sentence: <strong>Cum amīcīs</strong> ad forum ambulābam.<br>How should <em>cum</em> be translated here?', 'Look at the case of ''amīcīs''. Is there a subjunctive verb?', null, '["When","Since","Although","With"]'::jsonb, 'With', 'Here, ''cum'' is a preposition taking the ablative case (amīcīs). There is no subjunctive verb. It means ''with friends''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-102', 'cum_clauses', 1, 'mc', 'EXAM TRAP', 'Read the sentence: <strong>Cum amīcī adessent</strong>, laetī erāmus.<br>How should <em>cum</em> be translated here?', 'adessent = imperfect subjunctive.', null, '["Since / When","With","Although","In order to"]'::jsonb, 'Since / When', 'Here, ''cum'' is a conjunction taking a subjunctive verb (adessent). It means ''Since the friends were present'' or ''When the friends were present''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-103', 'cum_clauses', 2, 'mc', 'IDENTIFY', 'Which of these sentences uses <em>cum</em> as a <strong>conjunction</strong>?', 'Look for the sentence with a subjunctive verb.', null, '["Cum magnā laude pugnāvit.","Mīles cum rēge dīxit.","Cum Caesar in Galliam vēnisset, vīcit.","Cum tē in urbe manēbō."]'::jsonb, 'Cum Caesar in Galliam vēnisset, vīcit.', '''vēnisset'' is pluperfect subjunctive, making ''cum'' a conjunction (When Caesar had come into Gaul...). The others use ablative nouns (laude, rēge, tē).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-201', 'cum_clauses', 3, 'mc', 'TRIGGER WORD', 'What word in the main clause almost always indicates that the <em>cum</em> clause is <strong>Concessive</strong> (Although)?', 'Means ''nevertheless''.', null, '["tandem","tamen","tam","tot"]'::jsonb, 'tamen', 'If you see ''tamen'' (nevertheless) in the main clause, the ''cum'' clause MUST be concessive (Although... nevertheless...).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-202', 'cum_clauses', 4, 'mc', 'IDENTIFY', '<strong>Cum</strong> fortiter pugnārent, tamen superātī sunt.<br>What type of cum clause is this?', 'Look for ''tamen''.', null, '["Circumstantial","Causal","Concessive","Temporal"]'::jsonb, 'Concessive', 'Concessive. ''ALTHOUGH they fought bravely, nevertheless they were conquered.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-203', 'cum_clauses', 5, 'mc', 'IDENTIFY', '<strong>Cum</strong> flūmen altum esset, trānsīre nōn potuimus.<br>What type of cum clause is this?', 'The depth of the river is the REASON they couldn''t cross.', null, '["Circumstantial","Causal","Concessive","Temporal"]'::jsonb, 'Causal', 'Causal. ''SINCE the river was deep, we could not cross.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-204', 'cum_clauses', 6, 'mc', 'IDENTIFY', '<strong>Cum</strong> Caesar Rōmam vēnisset, in senātum īvit.<br>What type of cum clause is this?', 'This sets the historical scene.', null, '["Circumstantial","Causal","Concessive","Temporal"]'::jsonb, 'Circumstantial', 'Circumstantial. ''WHEN Caesar had come to Rome, he went into the senate.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-205', 'cum_clauses', 7, 'mc', 'TRANSLATE', 'How do you translate: <strong>Cum hoc scīrem, tacuī.</strong>', 'scīrem = imperfect subjunctive. tacuī = I was silent.', null, '["With this knowledge, I was silent.","Since I knew this, I was silent.","Although I knew this, nevertheless I spoke.","When I know this, I will be silent."]'::jsonb, 'Since I knew this, I was silent.', 'Causal. ''Since I knew this...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-206', 'cum_clauses', 8, 'mc', 'TRANSLATE', 'How do you translate: <strong>Cum hoc scīrem, tamen dīxī.</strong>', 'Notice the ''tamen''.', null, '["When I knew this, I spoke.","Since I knew this, I spoke.","Although I knew this, nevertheless I spoke.","I spoke with this knowledge."]'::jsonb, 'Although I knew this, nevertheless I spoke.', 'Concessive. ''Although I knew this...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-301', 'cum_clauses', 9, 'mc', 'SEQUENCE', 'Cum dux <strong>interfectus esset</strong>, mīlitēs fūgērunt.<br>Why is the subjunctive pluperfect?', 'fūgērunt is perfect tense (secondary).', null, '["Primary sequence, prior action","Secondary sequence, prior action","Secondary sequence, simultaneous action","Primary sequence, simultaneous action"]'::jsonb, 'Secondary sequence, prior action', 'Secondary sequence (fūgērunt). The leader was killed BEFORE they fled -> prior action -> Pluperfect Subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-302', 'cum_clauses', 10, 'mc', 'SEQUENCE', 'Cum <strong>aeger sit</strong>, domī manet.<br>Why is the subjunctive present?', 'manet is present tense (primary).', null, '["Secondary sequence, simultaneous action","Primary sequence, prior action","Primary sequence, simultaneous action","Secondary sequence, prior action"]'::jsonb, 'Primary sequence, simultaneous action', 'Primary sequence (manet). He is sick AT THE SAME TIME that he stays home -> simultaneous -> Present Subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-303', 'cum_clauses', 11, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br><em>Since he is working</em>, he does not hear you.<br>Cum ______ (labōrāre), tē nōn audit.', 'audit = primary. Simultaneous action = 3rd singular present active subjunctive.', '["laboret"]'::jsonb, null, null, 'labōret. (Present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-304', 'cum_clauses', 12, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br><em>Since he was working</em>, he did not hear you.<br>Cum ______ (labōrāre), tē nōn audīvit.', 'audīvit = secondary. Simultaneous action = 3rd singular imperfect active subjunctive.', '["laboraret"]'::jsonb, null, null, 'labōrāret. (Imperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-305', 'cum_clauses', 13, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br><em>When they had arrived</em>, we rejoiced.<br>Cum ______ (pervenīre), laetātī sumus.', 'laetātī sumus = secondary. Prior action = 3rd plural pluperfect active subjunctive of pervenīre (perf stem: pervēn-).', '["pervenissent"]'::jsonb, null, null, 'pervēnissent. (Pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-306', 'cum_clauses', 14, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br><em>Since the city had been captured</em>, we fled.<br>Cum urbs ______ (capere), fūgimus.', 'fūgimus = secondary. Prior passive action = 3rd singular pluperfect passive subjunctive of capere (PPP = capta).', '["capta esset"]'::jsonb, null, null, 'capta esset. (Pluperfect passive subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-401', 'cum_clauses', 15, 'mc', 'MIXED', '<strong>Cum auxilium petant</strong>, eīs nōn respondēmus.<br>Translate the bolded clause.', 'petant = present subjunctive.', null, '["When they had sought help","Although/Since they are seeking help","With them seeking help","In order to seek help"]'::jsonb, 'Although/Since they are seeking help', 'Primary sequence, simultaneous action. ''Although/Since they are seeking help, we do not answer them.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-402', 'cum_clauses', 16, 'typein', 'MIXED', 'Give the correct Latin for the bolded verb: <br>Although we <strong>are</strong> brave, nevertheless we flee.<br>Cum fortēs ______ (esse), tamen fugimus.', 'fugimus = present (primary). Simultaneous = 1st plural present subjunctive of esse.', '["simus"]'::jsonb, null, null, 'sīmus. (Present subjunctive of esse).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-403', 'cum_clauses', 17, 'typein', 'MIXED', 'Give the correct Latin for the bolded verb: <br>When he <strong>had seen</strong> the enemy, he shouted.<br>Cum hostem ______ (vidēre), clāmāvit.', 'clāmāvit = secondary. Prior = 3rd singular pluperfect active subjunctive of vidēre (perf stem: vīd-).', '["vidisset"]'::jsonb, null, null, 'vīdisset. (Pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-404', 'cum_clauses', 18, 'mc', 'MIXED', 'Cum cīvēs perterritī essent, mīlitēs urbem dēfendēbant.<br>How should <em>cum</em> be translated?', 'The citizens being terrified is the reason the soldiers defended the city.', null, '["Since / Because","Although","With","In order that"]'::jsonb, 'Since / Because', 'Causal cum clause. ''Since the citizens were terrified...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-405', 'cum_clauses', 19, 'mc', 'MIXED', 'What mood is used in a <em>Cum Temporal</em> clause that refers to a purely factual present or future event?', 'If it''s just stating pure time (''At the exact time when...'').', null, '["Indicative","Subjunctive","Infinitive","Imperative"]'::jsonb, 'Indicative', 'While circumstantial, causal, and concessive cum clauses use the Subjunctive, a purely temporal cum clause (especially referring to present/future) uses the Indicative.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-406', 'cum_clauses', 20, 'typein', 'FORM', 'Translate the bolded verb: <br>Since the money <strong>has been lost</strong>, we are sad.<br>Cum pecunia ______ (āmittere), tristes sumus.', 'sumus = primary. Prior passive action = 3rd singular perfect passive subjunctive of āmittere (PPP = āmissa).', '["amissa sit"]'::jsonb, null, null, 'āmissa sit. (Perfect passive subjunctive, primary sequence).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-407', 'cum_clauses', 21, 'typein', 'FORM', 'Translate the bolded verb: <br>Although they <strong>had fought</strong> well, they were killed.<br>Cum bene ______ (pugnāre), interfectī sunt.', 'interfectī sunt = secondary. Prior action = 3rd plural pluperfect active subjunctive of pugnāre.', '["pugnavissent"]'::jsonb, null, null, 'pugnāvissent. (Pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-408', 'cum_clauses', 22, 'mc', 'EXAM TRAP', 'Cum in forō <strong>ambulārem</strong>, amīcum vīdī.<br>What type of cum clause is this?', 'Sets the scene of the action.', null, '["Circumstantial","Causal","Concessive","Temporal"]'::jsonb, 'Circumstantial', 'Circumstantial. Uses the imperfect subjunctive to set the background scene. ''When/While I was walking in the forum...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-409', 'cum_clauses', 23, 'mc', 'EXAM TRAP', 'Cum tē <strong>vidēbō</strong>, fābulam nārrābō.<br>What type of cum clause is this?', 'vidēbō is future indicative.', null, '["Temporal","Circumstantial","Causal","Concessive"]'::jsonb, 'Temporal', 'Temporal. Because it refers to a purely future time, it uses the indicative (vidēbō), not the subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-410', 'cum_clauses', 24, 'typein', 'FORM', 'Translate the bolded verb: <br>When he <strong>heard</strong> this, he departed.<br>Cum hoc ______ (audīre), discessit.', 'discessit = secondary. Prior action = 3rd singular pluperfect active subjunctive of audīre.', '["audivisset","audisset"]'::jsonb, null, null, 'audīvisset (or the syncopated audisset). Pluperfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-501', 'cum_clauses', 25, 'mc', 'CUM INVERSUM', 'Iam lūcēbat, <strong>cum subitō vīdī</strong> hostem.', 'The verb ''vīdī'' is indicative. This ''flips'' the importance.', null, '["Since it was day, I saw the enemy.","When it was day, I saw the enemy.","It was already day, when suddenly I saw the enemy.","Although it was day, I saw the enemy."]'::jsonb, 'It was already day, when suddenly I saw the enemy.', 'Cum Inversum: the ''cum'' clause uses the indicative to show a sudden, main action interrupting a background state.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-502', 'cum_clauses', 26, 'mc', 'IDENTIFY', 'Which sentence contains a <strong>Causal</strong> cum clause?', 'Look for a cause-and-effect relationship.', null, '["Cum amīcīs ambulat.","Cum fessī sīmus, domī manēbimus.","Cum veniet, eum vidēbō.","Vesperāscēbat, cum cecidit."]'::jsonb, 'Cum fessī sīmus, domī manēbimus.', 'Cum fessī sīmus, domī manēbimus: ''Since we are tired, we will stay at home.'' Being tired is the reason for staying home. A circumstantial cum clause describes past background, so this cum clause is causal or concessive, and the meaning (a reason, not an obstacle) shows it is causal. Cum amīcīs is the preposition ''with'', Cum veniet has the indicative (temporal ''when''), and Vesperāscēbat, cum cecidit is inverse cum with the indicative.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-503', 'cum_clauses', 27, 'typein', 'CONCESSIVE', 'Complete the sentence with the correct subjunctive of <strong>esse</strong>: <br>Cum pauper ______, tamen fēlīx est. (Although he is poor...)', 'Primary sequence (est). Needs 3rd person singular present subjunctive.', '["sit"]'::jsonb, null, null, 'sit. The presence of ''tamen'' (nevertheless) proves this is a Concessive cum clause.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-504', 'cum_clauses', 28, 'mc', 'EXAM TRAP', 'In a <strong>Cum Circumstantial</strong> clause, which tense shows an action happening at the <em>same time</em> as a past main verb?', 'Secondary sequence + simultaneous time.', null, '["Present Subjunctive","Perfect Subjunctive","Imperfect Subjunctive","Pluperfect Subjunctive"]'::jsonb, 'Imperfect Subjunctive', 'Imperfect Subjunctive is used for background actions happening while the main past action occurs.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m4-505', 'cum_clauses', 29, 'typein', 'FORM', 'Translate the verb: ''When the signal <strong>had been given</strong>...'' (signum dare; PPP: datum)', 'Secondary sequence, prior passive action. 3rd person singular pluperfect passive subjunctive.', '["signum datum esset","cum signum datum esset"]'::jsonb, null, null, 'signum datum esset. (Pluperfect passive = PPP + esset).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('indirect_question', 'M5', 'Indirect Question', 'Interrogative words + subjunctive in reported speech', 'Reported questions. Governed strictly by Sequence of Tenses.', '["Interrogatives","SOT Alignment"]'::jsonb, 5) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-101', 'indirect_question', 0, 'mc', 'TRIGGER', 'Which word means <strong>''why''</strong> and frequently introduces an Indirect Question?', 'Three letters, very common.', null, '["quandō","cūr","ubi","unde"]'::jsonb, 'cūr', '''cūr'' means ''why''. (quandō = when, ubi = where/when, unde = from where).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-102', 'indirect_question', 1, 'mc', 'TRIGGER', 'Which word means <strong>''from where''</strong>?', 'Often paired with verbs of motion.', null, '["quō","ubi","unde","quandō"]'::jsonb, 'unde', '''unde'' means ''from where''. (''quō'' means ''to where'', ''ubi'' means ''where'' or ''when'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-103', 'indirect_question', 2, 'mc', 'EXAM TRAP', 'In an Indirect Question, how is the word <strong>num</strong> translated?', 'It doesn''t expect a ''no'' answer here.', null, '["surely not","whether","now","never"]'::jsonb, 'whether', 'In direct questions, ''num'' expects a ''no'' answer. But in an INDIRECT question (e.g., Rogo num veniat), it simply means ''whether'' (I ask whether he is coming).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-104', 'indirect_question', 3, 'mc', 'TRIGGER', 'Which of the following phrases means <strong>''how great'' / ''how large''</strong>?', 'Relates to size or magnitude.', null, '["quālis","quot","quantus","quandō"]'::jsonb, 'quantus', '''quantus'' means ''how big/great''. (''quālis'' = what sort of, ''quot'' = how many).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-105', 'indirect_question', 4, 'mc', 'TRIGGER', 'Which of the following phrases means <strong>''what sort of'' / ''what kind''</strong>?', 'Think of the English word ''quality''.', null, '["quālis","quot","quantus","cūr"]'::jsonb, 'quālis', '''quālis'' asks about the nature or quality of something.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-201', 'indirect_question', 5, 'mc', 'IDENTIFY', 'Nescio <strong>ubi sit</strong>.<br>What type of clause is bolded?', 'ubi = where. ''I do not know where...''', null, '["Indirect Command","Indirect Question","Relative Clause","Purpose Clause"]'::jsonb, 'Indirect Question', 'Triggered by a mental action head verb (nescio) and an interrogative word (ubi).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-202', 'indirect_question', 6, 'mc', 'DISCRIMINATE', 'Virum vīdī <strong>quī pūgiōnem tenēbat.</strong><br>What type of clause is bolded?', 'Look at the mood of ''tenēbat'' (indicative) and what ''quī'' is doing.', null, '["Indirect Question","Relative Clause","Indirect Command","Purpose Clause"]'::jsonb, 'Relative Clause', 'This is a regular Relative Clause describing the man (indicative verb). ''I saw the man WHO was holding a dagger.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-203', 'indirect_question', 7, 'mc', 'DISCRIMINATE', 'Mē rogāvit <strong>quis pūgiōnem tenēret.</strong><br>What type of clause is bolded?', 'rogāvit = asked. tenēret = subjunctive.', null, '["Indirect Question","Relative Clause","Indirect Command","Result Clause"]'::jsonb, 'Indirect Question', 'Indirect Question. Triggered by a head verb (rogāvit) and an interrogative (quis), followed by a subjunctive (tenēret). ''He asked ME WHO was holding the dagger.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-204', 'indirect_question', 8, 'mc', 'IDENTIFY', 'Mīrābāmur <strong>num hostēs fūgissent</strong>.<br>What type of clause is bolded?', 'num = whether. mīrābāmur = we were wondering.', null, '["Fear Clause","Indirect Command","Indirect Question","Optative Wish"]'::jsonb, 'Indirect Question', '''We were wondering whether the enemies had fled.'' Miror (to wonder) is a head verb.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-301', 'indirect_question', 9, 'mc', 'SOT REVIEW', 'Rogat quid heri <strong>fēcerīs</strong>.<br>Why perfect subjunctive?', 'Main verb is present. Action is past.', null, '["Secondary sequence, prior action","Primary sequence, simultaneous","Primary sequence, prior action","Secondary sequence, simultaneous"]'::jsonb, 'Primary sequence, prior action', 'Rogat = primary. Fēcerīs = happened before the asking. Primary sequence + prior time = Perfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-302', 'indirect_question', 10, 'mc', 'SOT REVIEW', 'Rogāvit cūr <strong>lacrimārēs</strong>.<br>Why imperfect subjunctive?', 'Main verb is perfect. Action is happening at the same time as the asking.', null, '["Primary sequence, simultaneous action","Secondary sequence, simultaneous action","Secondary sequence, prior action","Primary sequence, prior action"]'::jsonb, 'Secondary sequence, simultaneous action', 'Rogāvit = secondary. You were crying AT THE SAME TIME he asked. Secondary + simultaneous = Imperfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-303', 'indirect_question', 11, 'mc', 'SOT REVIEW', 'Sciēbam quō <strong>īssent</strong>.<br>Why pluperfect subjunctive?', 'Main verb is imperfect. They went there BEFORE he knew about it.', null, '["Secondary sequence, prior action","Secondary sequence, simultaneous action","Primary sequence, prior action","Primary sequence, simultaneous action"]'::jsonb, 'Secondary sequence, prior action', 'Sciēbam = secondary. īssent (syncopated from īvissent) = prior action. ''I knew where they HAD gone.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-304', 'indirect_question', 12, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>I ask what you are saying.<br>Rogō quid ______ (dīcere).', 'Rogō = primary. Simultaneous = 2nd person singular present subjunctive.', '["dicas"]'::jsonb, null, null, 'dīcās. (Primary + simultaneous = present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-305', 'indirect_question', 13, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>I asked what you were saying.<br>Rogāvī quid ______ (dīcere).', 'Rogāvī = secondary. Simultaneous = 2nd person singular imperfect subjunctive.', '["diceres"]'::jsonb, null, null, 'dīcerēs. (Secondary + simultaneous = imperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-306', 'indirect_question', 14, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>He knows why they fled.<br>Scit cūr ______ (fugere).', 'Scit = primary. Prior = 3rd person plural perfect subjunctive of fugere (perf stem: fūg-).', '["fugerint"]'::jsonb, null, null, 'fūgerint. (Primary + prior = perfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-307', 'indirect_question', 15, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>He knew why they had fled.<br>Sciēbat cūr ______ (fugere).', 'Sciēbat = secondary. Prior = 3rd person plural pluperfect subjunctive of fugere.', '["fugissent"]'::jsonb, null, null, 'fūgissent. (Secondary + prior = pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-401', 'indirect_question', 16, 'mc', 'TRANSLATE', 'How do you translate: <strong>Dīc mihi quis sīs.</strong>', 'Imperative (Dīc) counts as primary sequence. sīs = present subjunctive.', null, '["Tell me who he is.","Tell me who you were.","Tell me who you are.","He told me who you are."]'::jsonb, 'Tell me who you are.', '''Dīc'' is the imperative ''Tell''. ''quis sīs'' = ''who you are''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-402', 'indirect_question', 17, 'mc', 'TRANSLATE', 'How do you translate: <strong>Intellexit quantō in perīculō essēmus.</strong>', 'Intellexit = he understood (secondary). essēmus = imperfect subjunctive.', null, '["He understands how great a danger we are in.","He understood how great a danger we had been in.","He understood how great a danger we were in.","We understand how much danger he was in."]'::jsonb, 'He understood how great a danger we were in.', 'quantō in perīculō = in how great a danger. essēmus (simultaneous in the past) = we were.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-403', 'indirect_question', 18, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nescīvērunt unde vēnisset.</strong>', 'vēnisset = pluperfect subjunctive (prior action).', null, '["They do not know where he is going.","They did not know from where he had come.","They did not know when he came.","He didn''t know where they had come from."]'::jsonb, 'They did not know from where he had come.', 'unde = from where. vēnisset = he had come.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-404', 'indirect_question', 19, 'mc', 'TRANSLATE', 'How do you translate: <strong>Rogat num hostēs victī sint.</strong>', 'victī sint = perfect passive subjunctive (primary sequence, prior action).', null, '["He asked whether the enemies had been conquered.","He asks whether the enemies are conquering.","He asks whether the enemies have been conquered.","He asks why the enemies were conquered."]'::jsonb, 'He asks whether the enemies have been conquered.', 'Rogat (present) + victī sint (perfect passive). ''He asks whether they HAVE BEEN conquered.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-501', 'indirect_question', 20, 'typein', 'FORM', 'Complete the Latin sentence: <br>Tell me what you <strong>have done</strong>.<br>Dīc mihi quid ______ (facere).', 'Dīc = primary. Prior action = 2nd person singular perfect active subjunctive.', '["feceris"]'::jsonb, null, null, 'fēcerīs. (Perfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-502', 'indirect_question', 21, 'typein', 'FORM', 'Complete the Latin sentence: <br>I was wondering where they <strong>were going</strong>.<br>Mīrābar quō ______ (īre).', 'Mīrābar = secondary. Simultaneous action = 3rd person plural imperfect active subjunctive of īre (stem is i-).', '["irent"]'::jsonb, null, null, 'īrent. (Imperfect subjunctive of īre is īre + endings = īrent).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-503', 'indirect_question', 22, 'typein', 'FORM', 'Complete the Latin sentence: <br>They ask how many soldiers <strong>are present</strong>.<br>Rogant quot mīlitēs ______ (adesse).', 'Rogant = primary. Simultaneous action = 3rd person plural present subjunctive of adesse (ad + esse).', '["adsint"]'::jsonb, null, null, 'adsint. (Present subjunctive of esse is sim/sis/sit/simus/sitis/sint).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-504', 'indirect_question', 23, 'typein', 'FORM', 'Complete the Latin sentence: <br>We didn''t know who <strong>had been killed</strong>.<br>Nescīvimus quis ______ (interficere).', 'Nescīvimus = secondary. Prior passive action = 3sg pluperfect passive subjunctive of interficere (PPP: interfectus).', '["interfectus esset"]'::jsonb, null, null, 'interfectus esset. (Pluperfect passive subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-505', 'indirect_question', 24, 'typein', 'FORM', 'Complete the Latin sentence: <br>I don''t know why she <strong>is laughing</strong>.<br>Nesciō cūr ______ (rīdēre).', 'Nesciō = primary. Simultaneous = 3rd singular present active subjunctive of rīdēre.', '["rideat"]'::jsonb, null, null, 'rīdeat. (2nd conjugation takes -eā- in the present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-601', 'indirect_question', 25, 'mc', 'VOCAB', 'Identify the difference: <strong>Ubi</strong> vs <strong>Quō</strong> vs <strong>Unde</strong>.', 'Think of state vs. motion.', null, '["Where (location) / To where / From where","When / Why / How","Who / What / Which","From where / Where / To where"]'::jsonb, 'Where (location) / To where / From where', 'Latin is very specific about motion. Ubi is ''at'' a place; Quō is ''to'' a place; Unde is ''from'' a place.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-602', 'indirect_question', 26, 'typein', 'SOT PRODUCTION', 'Translate the verb: ''He asked where we <strong>had been</strong>.'' (esse)', 'Rogāvit (secondary). Action happened BEFORE the asking (prior).', '["fuissemus"]'::jsonb, null, null, 'fuissēmus. Secondary sequence + prior action = Pluperfect Subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-603', 'indirect_question', 27, 'mc', 'EXAM TRAP', '<strong>Rogat quid facias.</strong> vs <strong>Rogat quid feceris.</strong>', 'Both are primary sequence (Rogat).', null, '["He asks what you do / He asks what you will do.","He asks what you are doing / He asks what you did.","He asked what you did / He asked what you had done.","He asks why you do it / He asks how you do it."]'::jsonb, 'He asks what you are doing / He asks what you did.', 'Present subjunctive (faciās) is simultaneous; Perfect subjunctive (fēcerīs) is prior.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-604', 'indirect_question', 28, 'typein', 'VOCAB', 'Type the Latin word for ''how many'' (often used with ''quot'' questions).', null, '["quot"]'::jsonb, null, null, 'Quot is an indeclinable adjective meaning ''how many''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-605', 'indirect_question', 29, 'mc', 'DOUBLE QUESTION', '<strong>Rogō utrum maneās an abeās.</strong>', 'utrum... an... is the formula for double questions.', null, '["I ask that you stay and not leave.","I ask whether you are staying or leaving.","I ask how you stay and why you leave.","I ask if you can stay or leave."]'::jsonb, 'I ask whether you are staying or leaving.', 'Utrum... an... means ''Whether... or...'' in indirect questions.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m5-606', 'indirect_question', 30, 'typein', 'FORM', 'Translate the verb: ''I don''t know who <strong>is coming</strong>.'' (venīre)', 'Nesciō (primary). Simultaneous action = 3rd person singular present active subjunctive.', '["veniat"]'::jsonb, null, null, 'veniat. (Present subjunctive for simultaneous time in primary sequence).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('fear_clauses', 'M6', 'Fear Clauses', 'timēre/verērī + nē / ut', 'Verbs of fearing (timeo, vereor, metuo) flip the standard ut/nē logic. This is guaranteed to be on the exam.', '["Positive Fear","Negative Fear"]'::jsonb, 6) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-101', 'fear_clauses', 0, 'mc', 'THE FLIP', 'After a verb of fearing, how is the conjunction <strong>nē</strong> translated?', 'It expresses a positive fear (you fear it WILL happen).', null, '["that... not","that / lest","whether","in order to"]'::jsonb, 'that / lest', 'With fear clauses, ''nē'' means ''that'' or ''lest''. Example: Timeō nē pluat = I fear THAT it will rain.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-102', 'fear_clauses', 1, 'mc', 'THE FLIP', 'After a verb of fearing, how is the conjunction <strong>ut</strong> translated?', 'It expresses a negative fear (you fear it WON''T happen).', null, '["that","in order to","that... not","lest"]'::jsonb, 'that... not', 'With fear clauses, ''ut'' (or ''nē nōn'') flips to mean ''that... not''. Example: Timeō ut pluat = I fear that it will NOT rain.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-103', 'fear_clauses', 2, 'mc', 'TRIGGER WORD', 'Which of the following is a common <strong>verb of fearing</strong>?', 'Deponent verb, 2nd conjugation.', null, '["volō","vereor","vetō","vertō"]'::jsonb, 'vereor', 'Vereor (to fear) is a deponent verb that triggers fear clauses. Timeō and metuō are the other common ones.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-104', 'fear_clauses', 3, 'mc', 'IDENTIFY', 'Which conjunction can be used interchangeably with <strong>ut</strong> in a fear clause?', 'A double negative.', null, '["ut nōn","nē nōn","num","quīn"]'::jsonb, 'nē nōn', 'In fear clauses, ''ut'' means ''that not''. You can also use ''nē nōn'' to mean the exact same thing.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-201', 'fear_clauses', 4, 'mc', 'TRANSLATE', 'How do you translate: <strong>Timeō nē hostēs veniant.</strong>', 'nē = that.', null, '["I fear that the enemies are not coming.","I fear that the enemies are coming.","I feared lest the enemies come.","They fear that the enemies are coming."]'::jsonb, 'I fear that the enemies are coming.', 'Timeō = I fear. nē = that. veniant = they are coming.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-202', 'fear_clauses', 5, 'mc', 'TRANSLATE', 'How do you translate: <strong>Metuēbam ut mīlitēs pugnārent.</strong>', 'Metuēbam = I was fearing. ut = that... not.', null, '["I was fearing that the soldiers were fighting.","I am fearing that the soldiers will not fight.","I was fearing that the soldiers would not fight.","I fear lest the soldiers fight."]'::jsonb, 'I was fearing that the soldiers would not fight.', 'ut flips to ''that not''. Imperfect subjunctive (pugnārent) shows simultaneous/subsequent action in secondary sequence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-203', 'fear_clauses', 6, 'mc', 'TRANSLATE', 'How do you translate: <strong>Verita est nē urbs capta esset.</strong>', 'Verita est = She feared. capta esset = pluperfect passive subjunctive.', null, '["She fears that the city is being captured.","She feared that the city had been captured.","She feared that the city had not been captured.","She feared to capture the city."]'::jsonb, 'She feared that the city had been captured.', 'nē = that. capta esset = had been captured (prior time in secondary sequence).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-204', 'fear_clauses', 7, 'mc', 'TRANSLATE', 'How do you translate: <strong>Timēmus nē nōn vincāmus.</strong>', 'nē nōn = that... not. vincāmus = present subjunctive.', null, '["We fear that we will win.","We fear lest we win.","We feared that we would not win.","We fear that we will not win."]'::jsonb, 'We fear that we will not win.', 'nē nōn is used just like ut in fear clauses.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-301', 'fear_clauses', 8, 'mc', 'SEQUENCE', 'Timeō nē amīcus <strong>ēgrediātur</strong>.<br>Why is the subjunctive present tense?', 'Look at Timeō.', null, '["Secondary sequence, simultaneous action","Primary sequence, simultaneous/subsequent action","Primary sequence, prior action","Secondary sequence, prior action"]'::jsonb, 'Primary sequence, simultaneous/subsequent action', 'Timeō (present = primary sequence). ēgrediātur (present subjunctive) shows the fear is happening at the same time or right after the fearing.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-302', 'fear_clauses', 9, 'mc', 'SEQUENCE', 'Metuēbat nē rēx <strong>interfectus esset</strong>.<br>Why is the subjunctive pluperfect?', 'Metuēbat = secondary sequence.', null, '["Secondary sequence, prior action","Primary sequence, prior action","Secondary sequence, simultaneous action","Primary sequence, simultaneous action"]'::jsonb, 'Secondary sequence, prior action', 'Metuēbat (imperfect = secondary). He feared that the king HAD ALREADY BEEN killed (prior action).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-401', 'fear_clauses', 10, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>I fear that he <strong>is falling</strong>.<br>Timeō nē ______ (cadere).', 'Primary + simultaneous = 3rd singular present active subjunctive.', '["cadat"]'::jsonb, null, null, 'cadat. (Present subjunctive of cadere).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-402', 'fear_clauses', 11, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>I was fearing that he <strong>was falling</strong>.<br>Timēbam nē ______ (cadere).', 'Secondary + simultaneous = 3rd singular imperfect active subjunctive.', '["caderet"]'::jsonb, null, null, 'caderet. (Imperfect subjunctive of cadere).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-403', 'fear_clauses', 12, 'typein', 'NEGATIVE', 'Fill in the blank with the correct conjunction: <br>He fears that the ships will <strong>not</strong> arrive.<br>Metuit ______ nāvēs perveniant.', 'Negative fear. Two-letter word.', '["ut"]'::jsonb, null, null, 'ut. (You could also use ''nē nōn'', but ''ut'' is standard).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-404', 'fear_clauses', 13, 'typein', 'NEGATIVE', 'Fill in the blank with the correct conjunction: <br>We feared that the war <strong>would</strong> happen.<br>Veritī sumus ______ bellum accideret.', 'Positive fear.', '["ne"]'::jsonb, null, null, 'nē. (We fear THAT it will happen).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-405', 'fear_clauses', 14, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>She fears that the money <strong>has been lost</strong>.<br>Verētur nē pecūnia ______ (āmittere).', 'Primary sequence. Prior passive action = 3rd singular perfect passive subjunctive (PPP = āmissa).', '["amissa sit"]'::jsonb, null, null, 'āmissa sit. (Perfect passive subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-406', 'fear_clauses', 15, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>We feared that they <strong>had spoken</strong>. (loquī - deponent)<br>Timuimus nē ______.', 'Secondary sequence. Prior action = 3rd plural pluperfect subjunctive of a deponent (PPP = locūtī).', '["locuti essent"]'::jsonb, null, null, 'locūtī essent. (Pluperfect subjunctive of a deponent verb).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-407', 'fear_clauses', 16, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>I fear that you <strong>are not listening</strong>.<br>Timeō ut ______ (audīre).', 'Primary sequence. Simultaneous action = 2nd singular present active subjunctive.', '["audias"]'::jsonb, null, null, 'audiās. (''ut'' handles the ''not'', so just conjugate audīre normally).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-408', 'fear_clauses', 17, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>They feared that the city <strong>was being attacked</strong>.<br>Metuēbant nē urbs ______ (oppugnāre).', 'Secondary sequence. Simultaneous PASSIVE action = 3rd singular imperfect passive subjunctive.', '["oppugnaretur"]'::jsonb, null, null, 'oppugnārētur. (Imperfect passive subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-409', 'fear_clauses', 18, 'mc', 'EXAM TRAP', 'Read the sentence: <strong>Mīlitēs castra mūniēbant nē ab hostibus caperentur.</strong><br>What type of clause is the nē clause?', 'Is there a verb or expression of fearing in the main clause?', null, '["Fear Clause","Indirect Question","Purpose Clause","Result Clause"]'::jsonb, 'Purpose Clause', 'Nē + subjunctive does not always mean a fear clause. There is no verb of fearing here: mūniēbant (''they were fortifying'') is an ordinary action, and the nē clause gives its aim. ''The soldiers were fortifying the camp so that it would not be captured by the enemy.'' A fear clause needs a word of fearing such as timeō, metuō or vereor, and a result clause would use ut nōn, not nē.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-410', 'fear_clauses', 19, 'typein', 'FORM', 'Type the correct Latin verb to fit the sequence: <br>I fear that they <strong>will capture</strong> the camp.<br>Timeō nē castra ______ (capere).', 'Primary sequence. Latin doesn''t have a future subjunctive, so it uses the present for subsequent action. 3rd plural present active subjunctive.', '["capiant"]'::jsonb, null, null, 'capiant. (Present subjunctive covers both simultaneous and subsequent action in primary sequence).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-601', 'fear_clauses', 20, 'mc', 'THE FLIP', '<strong>Timeō nē cadās.</strong>', 'In fear clauses, ''nē'' is what you DON''T want to happen.', null, '["I fear that you are falling.","I fear that you are not falling.","I fear lest you didn''t fall.","I am afraid to fall."]'::jsonb, 'I fear that you are falling.', 'Fear Clauses flip the usual logic: nē = that/lest; ut = that... not.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-602', 'fear_clauses', 21, 'mc', 'THE FLIP', '<strong>Timeō ut veniat.</strong>', 'In fear clauses, ''ut'' is the desired outcome you''re afraid won''t happen.', null, '["I fear that he is coming.","I fear that he is not coming.","I am afraid when he comes.","I fear for his coming."]'::jsonb, 'I fear that he is not coming.', 'Ut in a fear clause means ''that... not''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-603', 'fear_clauses', 22, 'typein', 'SYNONYM', 'What two-word phrase is a synonym for <strong>ut</strong> in a fear clause?', 'nē + ____', '["ne non"]'::jsonb, null, null, 'nē nōn. ''Timeō nē nōn veniat'' is the same as ''Timeō ut veniat''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-604', 'fear_clauses', 23, 'mc', 'SOT', '<strong>Veritus sum nē hostēs venīrent.</strong>', 'Veritus sum is perfect (secondary).', null, '["I fear that the enemies come.","I feared that the enemies were coming.","I feared that the enemies had come.","I was afraid of the enemies coming."]'::jsonb, 'I feared that the enemies were coming.', 'Secondary sequence + simultaneous action = Imperfect Subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-605', 'fear_clauses', 24, 'typein', 'FORM', 'Translate: ''We fear that the city <strong>has been</strong> captured.'' (capere; PPP: capta)', 'Primary sequence (Fear = Present). Prior passive action = Perfect Passive Subjunctive.', '["ne urbs capta sit"]'::jsonb, null, null, 'nē urbs capta sit. (Fear clauses use nē for ''that'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-606', 'fear_clauses', 25, 'mc', 'VOCAB', 'Which of these is NOT a verb of fearing?', 'One is a verb of ''forbidding''.', null, '["metuō","vereor","timeō","vetō"]'::jsonb, 'vetō', 'Vetō means ''I forbid''. The others all mean ''I fear''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m6-607', 'fear_clauses', 26, 'mc', 'EXAM TRAP', '<strong>Verēmur nē hostēs castra capiant.</strong> <br>How is ''capiant'' functioning here?', 'Latin lacks a future subjunctive.', null, '["Present subjunctive used for future time","Present subjunctive used for past time","Perfect subjunctive used for future time","It is an indicative verb"]'::jsonb, 'Present subjunctive used for future time', 'Since fears are usually about the future, the present subjunctive in primary sequence often carries a future meaning.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('conditionals', 'M7', 'Conditionals', 'All six types — Simple to Contrary-to-Fact', 'If/Then statements. Three types use the Indicative (Simple), but three types use the Subjunctive. Know the formulas.', '["Future Less Vivid","Present CTF","Past CTF"]'::jsonb, 7) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-101', 'conditionals', 0, 'mc', 'FORMULA', 'Which conditional uses the <strong>Present Subjunctive</strong> in both clauses?', 'Should... would...', null, '["Present Contrary to Fact","Future More Vivid","Future Less Vivid","Past Contrary to Fact"]'::jsonb, 'Future Less Vivid', 'Future Less Vivid (Should/Would) uses Present Subjunctive. Sī adsit, bene sit. (If he should be present, it would be well.)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-102', 'conditionals', 1, 'mc', 'FORMULA', 'Which conditional uses the <strong>Imperfect Subjunctive</strong> in both clauses?', 'Were... would...', null, '["Present Contrary to Fact","Future More Vivid","Future Less Vivid","Past Contrary to Fact"]'::jsonb, 'Present Contrary to Fact', 'Present CTF (Were/Would) uses Imperfect Subjunctive. Sī adesset, bene esset. (If he were present [but he''s not], it would be well.)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-103', 'conditionals', 2, 'mc', 'FORMULA', 'Which conditional uses the <strong>Pluperfect Subjunctive</strong> in both clauses?', 'Had... would have...', null, '["Present Contrary to Fact","Future More Vivid","Future Less Vivid","Past Contrary to Fact"]'::jsonb, 'Past Contrary to Fact', 'Past CTF (Had/Would have) uses Pluperfect Subjunctive. Sī adfuisset, bene fuisset. (If he had been present, it would have been well.)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-104', 'conditionals', 3, 'mc', 'FORMULA', 'Which conditional uses the <strong>Future Indicative</strong> (or Future Perfect) in the ''If'' clause and Future Indicative in the main clause?', 'Does/Will... will...', null, '["Present Contrary to Fact","Future More Vivid","Future Less Vivid","Simple Present"]'::jsonb, 'Future More Vivid', 'Future More Vivid (Does/Will... will) uses the Future or Future Perfect Indicative. Sī aderit, bene erit. (If he is present, it will be well.)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-105', 'conditionals', 4, 'mc', 'FORMULA', 'Which conditional uses the <strong>Present Indicative</strong> in both clauses?', 'Does... is...', null, '["Present Contrary to Fact","Future More Vivid","Future Less Vivid","Simple Present"]'::jsonb, 'Simple Present', 'Simple Present Conditionals state a simple fact using the present indicative. Sī adest, bene est. (If he is present, it is well.)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-201', 'conditionals', 5, 'mc', 'IDENTIFY', 'Identify the conditional: <strong>Sī hoc dīcat, erret.</strong>', 'dīcat / erret = present subjunctives.', null, '["Future Less Vivid","Present CTF","Future More Vivid","Past CTF"]'::jsonb, 'Future Less Vivid', 'Present subjunctive = Future Less Vivid. ''If he should say this, he would be wrong.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-202', 'conditionals', 6, 'mc', 'IDENTIFY', 'Identify the conditional: <strong>Sī hoc dīxisset, errāvisset.</strong>', 'dīxisset / errāvisset = pluperfect subjunctives.', null, '["Future Less Vivid","Present CTF","Future More Vivid","Past CTF"]'::jsonb, 'Past CTF', 'Pluperfect subjunctive = Past Contrary to Fact. ''If he had said this, he would have been wrong.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-203', 'conditionals', 7, 'mc', 'IDENTIFY', 'Identify the conditional: <strong>Sī hoc dīcet, errābit.</strong>', 'dīcet / errābit = future indicatives.', null, '["Future Less Vivid","Present CTF","Future More Vivid","Simple Fact Present"]'::jsonb, 'Future More Vivid', 'Future indicative = Future More Vivid. ''If he says (will say) this, he will be wrong.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-204', 'conditionals', 8, 'mc', 'IDENTIFY', 'Identify the conditional: <strong>Sī hoc dīceret, errāret.</strong>', 'dīceret / errāret = imperfect subjunctives.', null, '["Future Less Vivid","Present CTF","Past CTF","Simple Fact Past"]'::jsonb, 'Present CTF', 'Imperfect subjunctive = Present Contrary to Fact. ''If he were saying this, he would be wrong.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-205', 'conditionals', 9, 'mc', 'IDENTIFY', 'Identify the conditional: <strong>Sī pacem petunt, eīs damus.</strong>', 'petunt / damus = present indicatives.', null, '["Simple Present","Future Less Vivid","Present CTF","Future More Vivid"]'::jsonb, 'Simple Present', 'Present indicative = Simple Present (Fact). ''If they seek peace, we give it to them.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-301', 'conditionals', 10, 'mc', 'TRANSLATE', 'How do you translate: <strong>Sī mīlitēs pugnāvissent, vīcissēmus.</strong>', 'Past CTF (pluperfect subj).', null, '["If the soldiers fight, we will win.","If the soldiers should fight, we would win.","If the soldiers were fighting, we would be winning.","If the soldiers had fought, we would have won."]'::jsonb, 'If the soldiers had fought, we would have won.', 'Pluperfect subj = Past CTF. ''Had... would have...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-302', 'conditionals', 11, 'mc', 'TRANSLATE', 'How do you translate: <strong>Sī mīlitēs pugnent, vincāmus.</strong>', 'Future Less Vivid (present subj).', null, '["If the soldiers fight, we will win.","If the soldiers should fight, we would win.","If the soldiers were fighting, we would be winning.","If the soldiers had fought, we would have won."]'::jsonb, 'If the soldiers should fight, we would win.', 'Present subj = FLV. ''Should... would...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-303', 'conditionals', 12, 'mc', 'TRANSLATE', 'How do you translate: <strong>Sī mīlitēs pugnārent, vincerēmus.</strong>', 'Present CTF (imperfect subj).', null, '["If the soldiers fight, we will win.","If the soldiers should fight, we would win.","If the soldiers were fighting, we would be winning.","If the soldiers had fought, we would have won."]'::jsonb, 'If the soldiers were fighting, we would be winning.', 'Imperfect subj = Present CTF. ''Were... would...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-304', 'conditionals', 13, 'mc', 'TRANSLATE', 'How do you translate: <strong>Sī Caesar adest, tūtī sumus.</strong>', 'Simple Present (present ind).', null, '["If Caesar will be present, we will be safe.","If Caesar should be present, we would be safe.","If Caesar is present, we are safe.","If Caesar were present, we would be safe."]'::jsonb, 'If Caesar is present, we are safe.', 'Present indicative = Simple fact. ''If [fact], [fact].''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-305', 'conditionals', 14, 'mc', 'TRANSLATE', 'How do you translate: <strong>Sī dīligenter studuerit, exāmen trānsībit.</strong>', 'Future More Vivid. studuerit is future perfect indicative.', null, '["If he should study diligently, he would pass the exam.","If he studies diligently, he will pass the exam.","If he were studying diligently, he would pass the exam.","If he had studied diligently, he would have passed the exam."]'::jsonb, 'If he studies diligently, he will pass the exam.', 'Future More Vivid often uses the Future Perfect Indicative in the ''If'' clause to show the action must be completed before the main future action.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-401', 'conditionals', 15, 'typein', 'FORM', 'Complete the Future Less Vivid conditional: <br>If he <strong>should come</strong>, we would be happy.<br>Sī ______ (venīre), laetī sīmus.', 'Needs 3rd person singular present active subjunctive.', '["veniat"]'::jsonb, null, null, 'veniat. (FLV uses present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-402', 'conditionals', 16, 'typein', 'FORM', 'Complete the Present CTF conditional: <br>If he <strong>were coming</strong>, we would be happy.<br>Sī ______ (venīre), laetī essēmus.', 'Needs 3rd person singular imperfect active subjunctive.', '["veniret"]'::jsonb, null, null, 'venīret. (Present CTF uses imperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-403', 'conditionals', 17, 'typein', 'FORM', 'Complete the Past CTF conditional: <br>If he <strong>had come</strong>, we would have been happy.<br>Sī ______ (venīre), laetī fuissēmus.', 'Needs 3rd person singular pluperfect active subjunctive of venīre (perf stem: vēn-).', '["venisset"]'::jsonb, null, null, 'vēnisset. (Past CTF uses pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-404', 'conditionals', 18, 'typein', 'FORM', 'Complete the Future More Vivid conditional: <br>If he comes, we <strong>will be</strong> happy.<br>Sī veniet, laetī ______ (esse).', 'Needs 1st person plural future indicative of esse.', '["erimus"]'::jsonb, null, null, 'erimus. (FMV uses future indicative).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-405', 'conditionals', 19, 'typein', 'FORM', 'Complete the Future Less Vivid conditional: <br>If they should attack, we <strong>would defend</strong> the city.<br>Sī oppugnent, urbem ______ (dēfendere).', 'Needs 1st person plural present active subjunctive of dēfendere.', '["defendamus"]'::jsonb, null, null, 'dēfendāmus. (FLV uses present subjunctive in both clauses).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-406', 'conditionals', 20, 'typein', 'FORM', 'Complete the Past CTF conditional: <br>If the money had been lost, they <strong>would have wept</strong>.<br>Sī pecūnia āmissa esset, ______ (flēre).', 'Needs 3rd person plural pluperfect active subjunctive of flēre (perf stem: flēv-).', '["flevissent"]'::jsonb, null, null, 'flēvissent. (Past CTF uses pluperfect subjunctive in both clauses).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-407', 'conditionals', 21, 'typein', 'NEGATIVE', 'Fill in the blank with the correct negative: <br>If you do <strong>not</strong> study, you will fail.<br>Sī ______ studēbis, dēficiēs.', 'Conditionals (unlike purpose or fear clauses) just use the standard Latin word for ''not''.', '["non"]'::jsonb, null, null, 'nōn. (If clauses use nōn for negation, or ''nisi'' for ''if not/unless'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-408', 'conditionals', 22, 'typein', 'NEGATIVE', 'Fill in the blank with the word that means ''unless'' or ''if... not'':<br>______ currēs, capiēris.<br>Unless you run, you will be captured.', 'Four letters.', '["nisi"]'::jsonb, null, null, 'nisi = unless / if not.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-501', 'conditionals', 23, 'mc', 'EXAM TRAP', 'Identify this conditional: <strong>Sī heri studuissēs, hodiē exāmen trānsīrēs.</strong>', 'studuissēs = pluperfect. trānsīrēs = imperfect.', null, '["Past CTF","Present CTF","Mixed Contrary to Fact","Future Less Vivid"]'::jsonb, 'Mixed Contrary to Fact', 'This is a Mixed CTF. ''If you HAD studied yesterday (Past CTF), you WOULD BE passing the exam today (Present CTF).''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-502', 'conditionals', 24, 'mc', 'TRANSLATE', 'How do you translate the Mixed CTF: <strong>Sī Rōmānī Carthāginem nōn dēlēvissent, Carthāgō nunc flōrēret.</strong>', 'dēlēvissent = past. flōrēret = present.', null, '["If the Romans do not destroy Carthage, it will flourish now.","If the Romans had not destroyed Carthage, it would have flourished.","If the Romans had not destroyed Carthage, Carthage would be flourishing now.","If the Romans should not destroy Carthage, it would flourish."]'::jsonb, 'If the Romans had not destroyed Carthage, Carthage would be flourishing now.', 'Pluperfect subjunctive in the protasis (had not destroyed) + Imperfect subjunctive in the apodosis (would be flourishing now).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-503', 'conditionals', 25, 'typein', 'FORM', 'Complete the Mixed CTF conditional: <br>If he <strong>had not departed</strong> yesterday, he would be here today.<br>Sī heri nōn ______ (discēdere), hodiē adesset.', 'Needs 3rd person singular pluperfect active subjunctive of discēdere (perf stem: discess-).', '["discessisset"]'::jsonb, null, null, 'discessisset. (Past CTF half of the mixed conditional).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-504', 'conditionals', 26, 'typein', 'FORM', 'Complete the Mixed CTF conditional: <br>If he had not departed yesterday, he <strong>would be</strong> here today.<br>Sī heri nōn discessisset, hodiē ______ (adesse).', 'Needs 3rd person singular imperfect subjunctive of adesse.', '["adesset"]'::jsonb, null, null, 'adesset. (Present CTF half of the mixed conditional).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-505', 'conditionals', 27, 'mc', 'EXAM TRAP', 'Which of these pairs represents the correct tenses for a <strong>Future More Vivid</strong> conditional?', 'Indicatives only.', null, '["Present Subjunctive / Present Subjunctive","Future Indicative / Future Indicative","Imperfect Subjunctive / Imperfect Subjunctive","Present Indicative / Present Subjunctive"]'::jsonb, 'Future Indicative / Future Indicative', 'Future More Vivid uses Future (or Future Perfect) indicative in both halves.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-506', 'conditionals', 28, 'mc', 'EXAM TRAP', 'Translate: <strong>Nisi venīrēs, trīstis essem.</strong>', 'Nisi = if not / unless. venīrēs / essem = imperfect subjunctives.', null, '["Unless you come, I will be sad.","Unless you had come, I would have been sad.","Unless you should come, I would be sad.","Unless you were coming, I would be sad."]'::jsonb, 'Unless you were coming, I would be sad.', 'Imperfect subjunctives = Present CTF. ''If you were not coming (Unless you were coming)...''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-507', 'conditionals', 29, 'mc', 'RULE', 'What is the technical grammatical term for the <strong>''If''</strong> clause in a conditional sentence?', 'Starts with ''P''.', null, '["Apodosis","Protasis","Ablative Absolute","Periphrastic"]'::jsonb, 'Protasis', 'The ''If'' clause is the Protasis. The ''Then'' clause (the main conclusion) is the Apodosis.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-601', 'conditionals', 30, 'mc', 'SIMPLE PAST', 'Identify: <strong>Sī amāvit, vīcit.</strong>', 'Both verbs are perfect indicative.', null, '["Past Contrary to Fact","Simple Fact Past","Future Less Vivid","Mixed Conditional"]'::jsonb, 'Simple Fact Past', 'Indicatives = Simple Fact. Since they are perfect, it is a simple past condition.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-602', 'conditionals', 31, 'mc', 'MIXED CTF', '<strong>Sī heri studuissēs, hodiē sapiēns essēs.</strong>', 'studuissēs (pluperfect) + essēs (imperfect).', null, '["If you studied yesterday, you were wise today.","If you should study, you would be wise.","If you had studied yesterday, you would be wise today.","If you were studying, you would have been wise."]'::jsonb, 'If you had studied yesterday, you would be wise today.', 'Mixed CTF: Pluperfect (past condition) + Imperfect (present result).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m7-603', 'conditionals', 32, 'typein', 'FORM', 'Turn this into a <strong>Future Less Vivid</strong>: <br>Sī veniet (will come), gaudēbimus (will rejoice).', 'Change both future indicatives to present subjunctives.', '["si veniat gaudeamus"]'::jsonb, null, null, 'Sī veniat, gaudeāmus. (Should come... would rejoice).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('quin_clauses', 'M8', 'Quin Clauses', 'Doubting and preventing with quin', 'Doubting and Preventing. A staple of advanced grammar.', '["Doubting","Preventing"]'::jsonb, 8) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-101', 'quin_clauses', 0, 'mc', 'TRIGGER WORD', 'Which of these phrases is a classic trigger for a <strong>quīn</strong> clause?', 'Requires a negative + a word of doubting.', null, '["dubitō","nōn dubitō","rogō","sciō"]'::jsonb, 'nōn dubitō', 'A positive dubitō (''I doubt'') takes an indirect question, usually with num (''whether''). It must be negated (nōn dubitō, nēmō dubitat) or put in a question expecting ''no'' (quis dubitat?) to take quīn.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-102', 'quin_clauses', 1, 'mc', 'TRIGGER WORD', 'Which of these is a verb of <strong>preventing or hindering</strong>, which takes a quīn clause when it is negated?', 'Means ''to hinder/impede''.', null, '["imperō","impediō","incipiō","intellegō"]'::jsonb, 'impediō', 'Impediō (hinder, prevent) is a verb of preventing, like dēterreō, retineō and obstō. These verbs take quīn only when they are negated (nōn impedit, nihil obstat) or in a question expecting ''no''. When the verb is positive, Latin uses nē or quōminus instead.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-103', 'quin_clauses', 2, 'mc', 'TRANSLATION RULE', 'After a negated word of <strong>doubting</strong> (e.g., nōn dubitō), how is <em>quīn</em> translated?', 'I do not doubt _____ you are right.', null, '["who","from","that","lest"]'::jsonb, 'that', 'After ''nōn dubitō'', quīn simply means ''that''. (I do not doubt THAT...)') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-104', 'quin_clauses', 3, 'mc', 'TRANSLATION RULE', 'After a <strong>negated</strong> verb of preventing or hindering, how is <em>quīn</em> translated?', 'Nothing prevents me _____ doing this.', null, '["who","from","that","lest"]'::jsonb, 'from', 'After a negated verb of hindering, quīn (or quōminus) is translated ''from ...ing'': Nihil eum impedit quīn scrībat, ''Nothing prevents him from writing.'' A positive verb of hindering takes nē or quōminus instead, also translated ''from ...ing''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-201', 'quin_clauses', 4, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nōn dubitō quīn Rōma magna sit.</strong>', 'sit = present subjunctive (simultaneous).', null, '["I doubt that Rome is great.","I do not doubt that Rome is great.","I do not doubt that Rome was great.","Rome is great without a doubt."]'::jsonb, 'I do not doubt that Rome is great.', 'Nōn dubitō = I do not doubt. quīn = that. sit = is.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-202', 'quin_clauses', 5, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nēmō dubitābat quīn hostēs fūgissent.</strong>', 'Nēmō dubitābat = No one was doubting. fūgissent = pluperfect subjunctive.', null, '["No one doubts that the enemies have fled.","No one was doubting that the enemies were fleeing.","No one was doubting that the enemies had fled.","No one doubts from where the enemies fled."]'::jsonb, 'No one was doubting that the enemies had fled.', 'Secondary sequence (dubitābat) + prior action (fūgissent). ''No one was doubting that they HAD fled.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-203', 'quin_clauses', 6, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nihil nōs impedit quīn discēdāmus.</strong>', 'impedit = prevents. discēdāmus = we depart.', null, '["Nothing prevents us from departing.","Nothing doubts that we are departing.","We prevent nothing from departing.","He prevents us from departing."]'::jsonb, 'Nothing prevents us from departing.', 'Nihil impedit = Nothing prevents. quīn discēdāmus = from departing.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-204', 'quin_clauses', 7, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nihil mīlitēs dēterrēbit quīn pugnent.</strong>', 'dēterrēbit = will deter. pugnent = they fight. Does quīn''s built-in ''not'' show up in English?', null, '["Nothing will deter the soldiers from fighting.","Nothing deters the soldiers from fighting.","No one doubted that the soldiers would fight.","Nothing will deter the soldiers from not fighting."]'::jsonb, 'Nothing will deter the soldiers from fighting.', 'Nihil ... dēterrēbit is a negated verb of deterring, so the clause can begin with quīn, translated ''from ...ing'': ''Nothing will deter the soldiers from fighting.'' The ''not'' inside quīn is not translated, so ''from not fighting'' is wrong. Dēterrēbit is future, not present.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-301', 'quin_clauses', 8, 'mc', 'DISCRIMINATE', 'Identify the clause: <strong>Quis dubitat quīn dī immortālēs adsint?</strong>', 'Quis dubitat? = Who doubts? (This is a rhetorical question implying ''No one doubts'').', null, '["Indirect Question","Quin Clause","Purpose Clause","Result Clause"]'::jsonb, 'Quin Clause', 'A rhetorical question like ''Quis dubitat?'' acts as a negated doubting expression, triggering a quīn clause.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-302', 'quin_clauses', 9, 'mc', 'DISCRIMINATE', 'Identify the clause: <strong>Dubitō num hostēs veniant.</strong>', 'Positive doubting uses num or an.', null, '["Indirect Question","Quin Clause","Indirect Command","Fear Clause"]'::jsonb, 'Indirect Question', 'Because ''Dubitō'' is NOT negated here, it takes an Indirect Question with ''num'' or ''an'' (I doubt whether the enemies are coming).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-303', 'quin_clauses', 10, 'mc', 'EXAM TRAP', 'Which of the following phrases is frequently paired with a quīn clause?', 'Means ''it cannot be but that...''', null, '["Ita accidit ut","Fierī nōn potest quīn","Tantus erat ut","Imperāvit eīs ut"]'::jsonb, 'Fierī nōn potest quīn', 'Fierī nōn potest quīn (It is not possible that... not / It cannot be but that...) is a set idiom that always triggers a quīn clause.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-401', 'quin_clauses', 11, 'typein', 'FORM', 'Complete the quīn clause: <br>I do not doubt that he <strong>is working</strong>.<br>Nōn dubitō quīn ______ (labōrāre).', 'Primary sequence. Simultaneous action = 3rd person singular present active subjunctive.', '["laboret"]'::jsonb, null, null, 'labōret. (Present subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-402', 'quin_clauses', 12, 'typein', 'FORM', 'Complete the quīn clause: <br>I did not doubt that he <strong>was working</strong>.<br>Nōn dubitāvī quīn ______ (labōrāre).', 'Secondary sequence. Simultaneous action = 3rd person singular imperfect active subjunctive.', '["laboraret"]'::jsonb, null, null, 'labōrāret. (Imperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-403', 'quin_clauses', 13, 'typein', 'FORM', 'Complete the quīn clause: <br>I do not doubt that they <strong>have fled</strong>.<br>Nōn dubitō quīn ______ (fugere).', 'Primary sequence. Prior action = 3rd plural perfect active subjunctive of fugere (perf stem: fūg-).', '["fugerint"]'::jsonb, null, null, 'fūgerint. (Perfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-404', 'quin_clauses', 14, 'typein', 'FORM', 'Complete the quīn clause: <br>I did not doubt that they <strong>had fled</strong>.<br>Nōn dubitāvī quīn ______ (fugere).', 'Secondary sequence. Prior action = 3rd plural pluperfect active subjunctive of fugere.', '["fugissent"]'::jsonb, null, null, 'fūgissent. (Pluperfect subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-405', 'quin_clauses', 15, 'typein', 'FORM', 'Complete the quīn clause: <br>They do not deter him from <strong>speaking</strong>.<br>Nōn eum dēterrent quīn ______ (dīcere).', 'Primary sequence. Simultaneous action = 3rd singular present active subjunctive.', '["dicat"]'::jsonb, null, null, 'dīcat. Nōn dēterrent is a negated verb of deterring, so quīn is used. Dēterrent is present (primary sequence) and the action is at the same time, so the present subjunctive: dīcat.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-406', 'quin_clauses', 16, 'typein', 'FORM', 'Complete the quīn clause: <br>They did not deter him from <strong>speaking</strong>.<br>Nōn eum dēterruērunt quīn ______ (dīcere).', 'Secondary sequence (dēterruērunt = perfect). Simultaneous action = 3rd singular imperfect active subjunctive.', '["diceret"]'::jsonb, null, null, 'dīceret. Nōn dēterruērunt is a negated verb of deterring, so quīn is used. Dēterruērunt is perfect (secondary sequence) and the action is at the same time, so the imperfect subjunctive: dīceret.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-407', 'quin_clauses', 17, 'typein', 'NEGATIVE', 'Fill in the blank to trigger a quīn clause:<br>______ dubitat quīn hoc vērum sit? (<strong>Who</strong> doubts that this is true?)', 'The interrogative pronoun (Nom, Sg, Masc).', '["quis"]'::jsonb, null, null, 'Quis. Rhetorical questions act as negatives.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-408', 'quin_clauses', 18, 'typein', 'FORM', 'Complete the quīn clause: <br>No one doubted that the city <strong>had been captured</strong>.<br>Nēmō dubitābat quīn urbs ______ (capere).', 'Secondary sequence. Prior passive action = 3sg pluperfect passive subjunctive of capere (PPP: capta).', '["capta esset"]'::jsonb, null, null, 'capta esset. (Pluperfect passive subjunctive).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m8-409', 'quin_clauses', 19, 'typein', 'TRIGGER WORD', 'Translate the bolded word: <br>Nihil mē impedit <strong>quīn</strong> eam. <br>Nothing prevents me ______ going.', 'A four-letter English preposition.', '["from"]'::jsonb, null, null, 'After verbs of hindering, quīn means ''from''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('relative_subjunctive', 'M9', 'Relative Clause Subjunctive', 'Purpose, Result, Characteristic relative clauses', 'Sometimes relative clauses (who/which/that) use the subjunctive instead of the indicative. Know why.', '["Relative Purpose","Characteristic"]'::jsonb, 9) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-101', 'relative_subjunctive', 0, 'mc', 'RULE', 'When a relative pronoun (quī, quae, quod) takes the place of ''ut'' to express <strong>why</strong> an action was done, what is this called?', 'It expresses the intention of the antecedent.', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Relative Clause of Result","Simple Relative Clause"]'::jsonb, 'Relative Clause of Purpose', 'A Relative Clause of Purpose uses a relative pronoun instead of ''ut'' to refer back to a specific antecedent (e.g., He sent envoys WHO might seek peace).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-102', 'relative_subjunctive', 1, 'mc', 'RULE', 'Which type of clause describes the <strong>general sort, kind, or character</strong> of an indefinite antecedent?', 'Used when the antecedent isn''t a specific person you can point to.', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Relative Clause of Result","Simple Relative Clause"]'::jsonb, 'Relative Clause of Characteristic', 'Characteristic clauses use the subjunctive to say ''He is the SORT of man who would do this'', rather than just stating a flat fact.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-103', 'relative_subjunctive', 2, 'mc', 'TRIGGER WORD', 'The phrase <strong>Sunt quī...</strong> (There are those who...) almost always triggers which type of clause?', 'Describes the kind of people they are.', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Indirect Question","Fear Clause"]'::jsonb, 'Relative Clause of Characteristic', '''Sunt quī'' sets up an indefinite group, so the following verb will be in the subjunctive to describe their characteristics.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-104', 'relative_subjunctive', 3, 'mc', 'TRIGGER WORD', 'Which of these phrases is a classic trigger for a Relative Clause of Characteristic?', 'A negative indefinite antecedent.', null, '["Ita accidit ut","Nēmō est quī","Nōn dubitō quīn","Tantus erat ut"]'::jsonb, 'Nēmō est quī', '''Nēmō est quī...'' (There is no one who...) is a standard trigger for a characteristic clause.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-105', 'relative_subjunctive', 4, 'mc', 'EXAM TRAP', 'The adjectives <strong>dignus</strong> (worthy) and <strong>indignus</strong> (unworthy) are often followed by a relative pronoun and a subjunctive verb. What type of clause is this?', 'He is worthy WHO should do this.', null, '["Relative Clause of Purpose","Relative Clause of Result / Characteristic","Indirect Command","Indirect Question"]'::jsonb, 'Relative Clause of Result / Characteristic', 'Phrases like ''dignus est quī hoc faciat'' (He is worthy to do this) use a relative clause with the subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-201', 'relative_subjunctive', 5, 'mc', 'DISCRIMINATE', 'Identify the clause: Lēgātōs mīsit <strong>quī pācem peterent</strong>.', 'Why did he send them?', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Simple Relative Clause","Indirect Command"]'::jsonb, 'Relative Clause of Purpose', 'Purpose. ''quī'' = ''ut eī''. ''He sent envoys WHO were to seek peace.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-202', 'relative_subjunctive', 6, 'mc', 'DISCRIMINATE', 'Identify the clause: Quis est <strong>quī hoc nēsciat</strong>?', 'Quis est = Who is there? (Indefinite).', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Simple Relative Clause","Indirect Question"]'::jsonb, 'Relative Clause of Characteristic', 'Characteristic. ''Who is there WHO would not know this?'' Describes the sort of person.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-203', 'relative_subjunctive', 7, 'mc', 'DISCRIMINATE', 'Identify the clause: Virum vīdī <strong>quī in forō stābat</strong>.', 'Look at the mood of ''stābat'' (indicative).', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Simple Relative Clause","Relative Clause of Result"]'::jsonb, 'Simple Relative Clause', 'Simple Relative Clause. Because the verb (stābat) is in the indicative, it is just stating a hard fact about a specific man, not expressing purpose or characteristic.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-204', 'relative_subjunctive', 8, 'mc', 'DISCRIMINATE', 'Identify the clause: Sōlus erat <strong>quī mē iuvāret</strong>.', 'Sōlus erat = He was the only one. Describes his unique character.', null, '["Relative Clause of Characteristic","Relative Clause of Purpose","Quin Clause","Fear Clause"]'::jsonb, 'Relative Clause of Characteristic', 'Characteristic. Expressions like ''ūnus est quī'' or ''sōlus est quī'' trigger characteristic clauses.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-301', 'relative_subjunctive', 9, 'mc', 'TRANSLATE', 'How do you translate: <strong>Sunt quī putent terram esse plānam.</strong>', 'Sunt quī = There are those who...', null, '["They are the ones who think the earth is flat.","There are those who think the earth is flat.","If only they thought the earth was flat.","Are there people who think the earth is flat?"]'::jsonb, 'There are those who think the earth is flat.', 'Sunt quī + subjunctive = ''There are those who [verb]''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-302', 'relative_subjunctive', 10, 'mc', 'TRANSLATE', 'How do you translate: <strong>Nēmō est quī hoc nōn intellegat.</strong>', 'Double negative concept.', null, '["No one understood this.","There is no one who does not understand this.","Let no one understand this.","Why does no one understand this?"]'::jsonb, 'There is no one who does not understand this.', 'Nēmō est quī = There is no one who. intellegat = present subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-303', 'relative_subjunctive', 11, 'mc', 'TRANSLATE', 'How do you translate: <strong>Mīlitēs mīsit quī castra dēfenderent.</strong>', 'Relative Purpose.', null, '["He sent soldiers who were defending the camp.","He sent soldiers to defend the camp.","There are soldiers who defend the camp.","The soldiers he sent defended the camp."]'::jsonb, 'He sent soldiers to defend the camp.', 'Relative clause of purpose is best translated as an infinitive in English (''to defend'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-304', 'relative_subjunctive', 12, 'mc', 'TRANSLATE', 'How do you translate: <strong>Dignus est quī imperet.</strong>', 'dignus = worthy.', null, '["He rules worthily.","He is worthy to rule.","Let the worthy man rule.","There is a worthy man who rules."]'::jsonb, 'He is worthy to rule.', 'Dignus + relative clause is translated with an infinitive in English. ''He is worthy WHO should rule'' -> ''He is worthy to rule.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-401', 'relative_subjunctive', 13, 'mc', 'SEQUENCE', 'Nūntiōs <strong>mittit</strong> quī rēgī haec <strong>nūntient</strong>.<br>Why is the subjunctive present tense?', 'Mittit = present tense.', null, '["Secondary sequence, simultaneous action","Primary sequence, simultaneous/subsequent action","Primary sequence, prior action","Secondary sequence, prior action"]'::jsonb, 'Primary sequence, simultaneous/subsequent action', 'Mittit (primary) requires a present subjunctive (nūntient) for purpose clauses.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-402', 'relative_subjunctive', 14, 'mc', 'SEQUENCE', 'Nūntiōs <strong>mīsit</strong> quī rēgī haec <strong>nūntiārent</strong>.<br>Why is the subjunctive imperfect tense?', 'Mīsit = perfect tense.', null, '["Primary sequence, simultaneous action","Secondary sequence, prior action","Primary sequence, prior action","Secondary sequence, simultaneous/subsequent action"]'::jsonb, 'Secondary sequence, simultaneous/subsequent action', 'Mīsit (secondary) requires an imperfect subjunctive (nūntiārent) for purpose clauses.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-403', 'relative_subjunctive', 15, 'mc', 'EXAM TRAP', 'Erat nēmō quī hoc <strong>fēcisset</strong>.<br>What sequence and relative time is this?', 'Erat = secondary. fēcisset = pluperfect.', null, '["Secondary sequence, prior action","Secondary sequence, simultaneous action","Primary sequence, prior action","Primary sequence, simultaneous action"]'::jsonb, 'Secondary sequence, prior action', 'Erat (imperfect) = secondary. They ALREADY did the action -> prior time -> Pluperfect Subjunctive. ''There was no one who HAD done this.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-501', 'relative_subjunctive', 16, 'typein', 'FORM', 'Complete the clause: <br>He sends men to <strong>fight</strong>.<br>Virōs mittit quī ______ (pugnāre).', 'Primary sequence. 3rd person plural present active subjunctive.', '["pugnent"]'::jsonb, null, null, 'pugnent. (Relative Purpose).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-502', 'relative_subjunctive', 17, 'typein', 'FORM', 'Complete the clause: <br>He sent men to <strong>fight</strong>.<br>Virōs mīsit quī ______ (pugnāre).', 'Secondary sequence. 3rd person plural imperfect active subjunctive.', '["pugnarent"]'::jsonb, null, null, 'pugnārent. (Relative Purpose).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-503', 'relative_subjunctive', 18, 'typein', 'FORM', 'Complete the clause: <br>There are those who <strong>believe</strong> this.<br>Sunt quī hoc ______ (crēdere).', 'Primary sequence. 3rd person plural present active subjunctive.', '["credant"]'::jsonb, null, null, 'crēdant. (Relative Characteristic).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-504', 'relative_subjunctive', 19, 'typein', 'FORM', 'Complete the clause: <br>There was no one who <strong>knew</strong>.<br>Erat nēmō quī ______ (scīre).', 'Secondary sequence. 3rd person singular imperfect active subjunctive.', '["sciret"]'::jsonb, null, null, 'scīret. (Relative Characteristic).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-505', 'relative_subjunctive', 20, 'typein', 'FORM', 'Complete the clause: <br>She was the only one who <strong>was able</strong>.<br>Sōla erat quae ______ (posse).', 'Secondary sequence. 3rd person singular imperfect active subjunctive of posse.', '["posset"]'::jsonb, null, null, 'posset. (Relative Characteristic).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-506', 'relative_subjunctive', 21, 'typein', 'FORM', 'Complete the clause: <br>He chose a leader to <strong>rule</strong> the state.<br>Ducem dēlēgit quī rem pūblicam ______ (regere).', 'Secondary sequence (dēlēgit = perfect). 3rd person singular imperfect active subjunctive of regere.', '["regeret"]'::jsonb, null, null, 'regeret. (Relative Purpose).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-507', 'relative_subjunctive', 22, 'typein', 'FORM', 'Fill in the correct relative pronoun: <br>He sent an army to destroy the city.<br>Exercitum mīsit ______ urbem dēlēret.', 'Pronoun must match the antecedent (exercitum: masc, sg) in gender and number, but its case is determined by its role in its own clause (subject = nominative).', '["qui"]'::jsonb, null, null, 'quī. (Nominative, singular, masculine).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-508', 'relative_subjunctive', 23, 'typein', 'FORM', 'Complete the clause: <br>Who is there who <strong>would do</strong> such a thing?<br>Quis est quī tālia ______ (facere)?', 'Primary sequence. 3rd person singular present active subjunctive of facere.', '["faciat"]'::jsonb, null, null, 'faciat. (Relative Characteristic).') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-601', 'relative_subjunctive', 24, 'mc', 'CHARACTERISTIC', '<strong>Nēmō est quī hoc crēdat.</strong>', 'Describes the ''kind'' of people that exist (or don''t).', null, '["No one believes this.","There is no one who believes this [fact].","There is no one who [is the type to] believe this.","Someone believes this."]'::jsonb, 'There is no one who [is the type to] believe this.', 'The subjunctive (crēdat) makes this a ''characteristic'' clause—it defines the nature of the person.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-602', 'relative_subjunctive', 25, 'mc', 'DISCRIMINATE', 'Which sentence uses a <strong>Relative Clause of Purpose</strong>?', 'Look for a relative pronoun replacing ''ut''.', null, '["Glabriōnem mīsērunt quī fīnēs dēfenderet.","Glabriō est vir quī fīnēs dēfendit.","Is est quī fīnēs dēfendat.","Sunt quī fīnēs dēfendant."]'::jsonb, 'Glabriōnem mīsērunt quī fīnēs dēfenderet.', 'The first one: ''They sent Glabrio [WHO = in order that he] might defend the borders.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-603', 'relative_subjunctive', 26, 'typein', 'FORM', 'Complete the Characteristic clause: <br>He is the only one who <strong>is able</strong> to do this.<br>Sōlus est quī hoc ______ (posse).', 'Primary sequence. 3rd person singular present active subjunctive of posse.', '["possit"]'::jsonb, null, null, 'possit. ''Sōlus est quī'' is a major trigger for the characteristic subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-604', 'relative_subjunctive', 27, 'mc', 'DIGNUS', '<strong>Dignus est quī amētur.</strong>', 'Dignus + Relative Subjunctive.', null, '["He is loved worthily.","He is worthy to be loved.","He is the type of man who loves.","He was worthy because he was loved."]'::jsonb, 'He is worthy to be loved.', 'Dignus/Indignus (worthy/unworthy) take a relative clause with the subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-605', 'relative_subjunctive', 28, 'typein', 'SOT', 'Translate the verb: ''We chose a place where we <strong>might stay</strong>.'' (manēre)', 'Dēlēgimus (secondary). Simultaneous/Purpose = 1st person plural imperfect active subjunctive.', '["maneremus"]'::jsonb, null, null, 'manērēmus. Secondary sequence requires the imperfect subjunctive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m9-606', 'relative_subjunctive', 29, 'mc', 'EXAM TRAP', 'Identify the <strong>Indicative</strong> relative clause (simple fact):', 'One of these is just a statement of fact, not a characteristic or purpose.', null, '["Hic est mīles quī in bellō pugnāvit.","Mīles missus est quī pugnāret.","Sunt mīlitēs quī pugnent.","Dignus est mīles quī pugnet."]'::jsonb, 'Hic est mīles quī in bellō pugnāvit.', 'The first one is a simple fact: ''This is the soldier who fought.'' The others are purpose, characteristic, and result-oriented.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('participles_ablative_absolute', 'M10', 'Participles and the Ablative Absolute', 'Verbal adjectives and absolute phrases', 'Form the present, perfect and future participles, including those of deponent verbs, and translate each by its time relative to the main verb. Then spot the ablative absolute and translate it as a when, while, after or although clause.', '["Present Active Participle","Perfect Passive Participle","Future Active Participle","Participles of Deponent Verbs","Agreement and Relative Time","Ablative Absolute","Ablative Absolute without a Participle"]'::jsonb, 10) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-101', 'participles_ablative_absolute', 0, 'typein', 'FORM', 'Give the <strong>present active participle</strong> (nominative masculine singular) of <span class=''latin-word''>portō, portāre, portāvī, portātum</span>.', '1st conjugation: present stem portā- + -ns.', '["portans"]'::jsonb, null, null, 'Add -ns to the present stem: portāns, portantis, ''carrying''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-102', 'participles_ablative_absolute', 1, 'typein', 'FORM', 'Give the <strong>present active participle</strong> (nominative masculine singular) of <span class=''latin-word''>moneō, monēre, monuī, monitum</span>.', '2nd conjugation: present stem monē- + -ns.', '["monens"]'::jsonb, null, null, 'Add -ns to the present stem: monēns, monentis, ''warning''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-103', 'participles_ablative_absolute', 2, 'typein', 'FORM', 'Give the <strong>present active participle</strong> (nominative masculine singular) of <span class=''latin-word''>regō, regere, rēxī, rēctum</span>.', '3rd conjugation: the short e of the stem becomes long before -ns.', '["regens"]'::jsonb, null, null, '3rd conjugation verbs form the present participle with -ēns: regēns, regentis, ''ruling''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-104', 'participles_ablative_absolute', 3, 'typein', 'FORM', 'Give the <strong>present active participle</strong> (nominative masculine singular) of <span class=''latin-word''>capiō, capere, cēpī, captum</span>.', '3rd conjugation -iō verbs keep the i: capi- + -ēns.', '["capiens"]'::jsonb, null, null, '3rd -iō and 4th conjugation verbs form the present participle with -iēns: capiēns, capientis, ''taking''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-105', 'participles_ablative_absolute', 4, 'typein', 'FORM', 'Give the <strong>genitive singular</strong> of the present active participle of <span class=''latin-word''>audiō, audīre, audīvī, audītum</span>.', 'The nominative is audiēns. Present participles decline like 3rd declension adjectives.', '["audientis"]'::jsonb, null, null, 'The nominative -ns becomes -ntis in the genitive: audiēns, audientis, ''of the one hearing''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-106', 'participles_ablative_absolute', 5, 'typein', 'FORM', 'Give the <strong>genitive plural</strong> of the present active participle of <span class=''latin-word''>vocō, vocāre, vocāvī, vocātum</span>.', 'Present participles are i-stems in the genitive plural.', '["vocantium"]'::jsonb, null, null, 'Present participles take -ium in the genitive plural: vocantium, ''of those calling''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-107', 'participles_ablative_absolute', 6, 'typein', 'FORM', 'Give the <strong>perfect passive participle</strong> (nominative masculine singular) of <span class=''latin-word''>ferō, ferre, tulī, lātum</span>.', 'The perfect passive participle is built on the 4th principal part, however irregular it looks.', '["latus"]'::jsonb, null, null, 'Take the 4th principal part and use the -us ending: lātus, lāta, lātum, ''having been carried''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-108', 'participles_ablative_absolute', 7, 'typein', 'FORM', 'Give the <strong>future active participle</strong> (nominative masculine singular) of <span class=''latin-word''>sum, esse, fuī, futūrus</span>.', 'Sum has no 4th principal part ending in -um; its last part is already the future participle.', '["futurus"]'::jsonb, null, null, 'The future active participle of sum is futūrus, futūra, futūrum, ''about to be''. It is the source of the English word future.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-109', 'participles_ablative_absolute', 8, 'typein', 'FORM', 'Give the <strong>perfect participle</strong> (nominative masculine singular) of the deponent verb <span class=''latin-word''>sequor, sequī, secūtus sum</span>.', 'Drop sum from the last principal part.', '["secutus"]'::jsonb, null, null, 'A deponent''s perfect participle is its last principal part without sum: secūtus. It is active in meaning: ''having followed''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-201', 'participles_ablative_absolute', 9, 'mc', 'IDENTIFY', 'Name the tense and voice of the participle <strong>missus</strong> (from <span class=''latin-word''>mittō, mittere, mīsī, missum</span>).', 'Look at the 4th principal part.', null, '["Perfect passive","Present active","Future active","Perfect active"]'::jsonb, 'Perfect passive', 'missus is built on the 4th principal part missum, so it is the perfect passive participle: ''having been sent''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-202', 'participles_ablative_absolute', 10, 'mc', 'IDENTIFY', 'Name the tense and voice of the participle <strong>pugnātūrī</strong>.', 'Look for -ūr- before the ending.', null, '["Future active","Future passive","Perfect passive","Present active"]'::jsonb, 'Future active', 'The -ūrus, -a, -um ending marks the future active participle: pugnātūrī, ''about to fight''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-203', 'participles_ablative_absolute', 11, 'mc', 'IDENTIFY', 'Which participle shows an action that happened <strong>before</strong> the action of the main verb?', 'Think of ''having been ...ed''.', null, '["The perfect participle","The present participle","The future participle","All three, depending on the main verb"]'::jsonb, 'The perfect participle', 'The perfect participle shows time before the main verb. The present shows the same time, and the future shows time after.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-204', 'participles_ablative_absolute', 12, 'mc', 'IDENTIFY', 'Mīlitēs <strong>pugnantēs</strong> vulnerātī sunt.<br>When does the fighting happen, compared to the main verb?', 'pugnantēs is a present participle.', null, '["At the same time","Before it","After it","Participles show no time at all"]'::jsonb, 'At the same time', 'A present participle shows the same time as the main verb: ''The soldiers were wounded while they were fighting.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-205', 'participles_ablative_absolute', 13, 'mc', 'IDENTIFY', 'Name the tense and meaning of <strong>hortātus</strong> (from the deponent <span class=''latin-word''>hortor, hortārī, hortātus sum</span>).', 'Deponent verbs are passive in form but active in meaning.', null, '["Perfect, active in meaning","Perfect, passive in meaning","Present, active in meaning","Future, active in meaning"]'::jsonb, 'Perfect, active in meaning', 'hortātus is a perfect participle. Because hortor is deponent, it is active in meaning: ''having encouraged''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-301', 'participles_ablative_absolute', 14, 'mc', 'TRANSLATE', 'Cōnsul mīlitēs <strong>fugientēs</strong> vīdit.<br>Who was fleeing?', 'A participle agrees with its noun in case, number and gender.', null, '["The soldiers","The consul","The consul and the soldiers together","Someone not named in the sentence"]'::jsonb, 'The soldiers', 'fugientēs is plural, so it cannot go with cōnsul. It agrees with mīlitēs: ''The consul saw the soldiers fleeing.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-302', 'participles_ablative_absolute', 15, 'mc', 'TRANSLATE', 'Agricola in agrō <strong>labōrāns</strong> lupum vīdit.<br>Choose the best translation.', 'labōrāns is nominative singular. Which noun is nominative singular?', null, '["While working in the field, the farmer saw a wolf.","Having worked in the field, the farmer saw a wolf.","About to work in the field, the farmer saw a wolf.","The farmer saw a wolf that was working in the field."]'::jsonb, 'While working in the field, the farmer saw a wolf.', 'labōrāns agrees with agricola, and a present participle shows the same time as the main verb: ''While working in the field, the farmer saw a wolf.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-303', 'participles_ablative_absolute', 16, 'mc', 'TRANSLATE', 'Mīlitēs ā cōnsule <strong>laudātī</strong> fortiter pugnāvērunt.<br>Choose the best translation.', 'laudātī is a perfect passive participle. ā cōnsule tells you who did the praising.', null, '["Having been praised by the consul, the soldiers fought bravely.","Having praised the consul, the soldiers fought bravely.","While praising the consul, the soldiers fought bravely.","About to be praised by the consul, the soldiers fought bravely."]'::jsonb, 'Having been praised by the consul, the soldiers fought bravely.', 'A perfect passive participle means ''having been ...ed'': ''Having been praised by the consul, the soldiers fought bravely.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-304', 'participles_ablative_absolute', 17, 'mc', 'TRANSLATE', 'Hostēs oppidum <strong>oppugnātūrī</strong> castra posuērunt.<br>Choose the best translation.', 'The -ūr- marks a future participle.', null, '["About to attack the town, the enemy pitched camp.","Having attacked the town, the enemy pitched camp.","While attacking the town, the enemy pitched camp.","Having been attacked, the enemy pitched camp near the town."]'::jsonb, 'About to attack the town, the enemy pitched camp.', 'A future active participle means ''about to'' or ''going to'': ''About to attack the town, the enemy pitched camp.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-305', 'participles_ablative_absolute', 18, 'mc', 'TRANSLATE', 'Caesar mīlitēs <strong>hortātus</strong> proelium commīsit.<br>Choose the best translation.', 'hortor is deponent.', null, '["Having encouraged the soldiers, Caesar began the battle.","Having been encouraged by the soldiers, Caesar began the battle.","About to encourage the soldiers, Caesar began the battle.","Caesar began the battle with the encouraged soldiers."]'::jsonb, 'Having encouraged the soldiers, Caesar began the battle.', 'A deponent''s perfect participle is active, so hortātus means ''having encouraged'', and mīlitēs is its object: ''Having encouraged the soldiers, Caesar began the battle.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-401', 'participles_ablative_absolute', 19, 'mc', 'ABLATIVE ABSOLUTE', '<strong>Urbe captā</strong>, mīlitēs praedam rapuērunt.<br>How is the bolded phrase best translated?', 'captā is a perfect passive participle in the ablative.', null, '["After the city had been captured","While the city was capturing","Before the city was captured","In order to capture the city"]'::jsonb, 'After the city had been captured', 'A noun and participle in the ablative, loosely attached to the sentence, form an ablative absolute. The perfect participle shows time before the main verb: ''After the city had been captured, the soldiers seized the loot.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-402', 'participles_ablative_absolute', 20, 'mc', 'ABLATIVE ABSOLUTE', 'Rēge interfectō, cīvēs ex urbe fūgērunt.<br>Which words form the ablative absolute?', 'Look for a noun and a participle in the ablative with no preposition.', null, '["Rēge interfectō","ex urbe","cīvēs fūgērunt","cīvēs ex urbe"]'::jsonb, 'Rēge interfectō', 'rēge interfectō is a noun and a participle in the ablative with no preposition: ''After the king had been killed, the citizens fled from the city.'' ex urbe is a prepositional phrase.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-403', 'participles_ablative_absolute', 21, 'mc', 'ABLATIVE ABSOLUTE', '<strong>Mīlitibus fortiter pugnantibus</strong>, castra tamen capta sunt.<br>How is the bolded phrase best translated?', 'tamen means ''nevertheless''. What does that tell you about the link between the two ideas?', null, '["Although the soldiers were fighting bravely","Because the soldiers were fighting bravely","After the soldiers had fought bravely","So that the soldiers would fight bravely"]'::jsonb, 'Although the soldiers were fighting bravely', 'tamen shows a contrast, so translate the ablative absolute with ''although''. The present participle shows the same time: ''Although the soldiers were fighting bravely, the camp was nevertheless captured.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-404', 'participles_ablative_absolute', 22, 'mc', 'ABLATIVE ABSOLUTE', '<strong>Hīs rēbus cognitīs</strong>, Caesar ad castra contendit.<br>How is the bolded phrase best translated?', 'cognitīs is a perfect passive participle.', null, '["When these things had been learned","While these things were being learned","In order to learn these things","About to learn these things"]'::jsonb, 'When these things had been learned', 'The perfect participle shows time before the main verb: ''When these things had been learned, Caesar hurried to the camp.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-405', 'participles_ablative_absolute', 23, 'mc', 'ABLATIVE ABSOLUTE', '<strong>Cicerōne cōnsule</strong>, coniūrātiō Catilīnae patefacta est.<br>How is the bolded phrase best translated?', 'There is no participle. Latin has no present participle of sum, so supply ''being''.', null, '["When Cicero was consul","By Cicero the consul","With Cicero and the consul","Cicero, the consul,"]'::jsonb, 'When Cicero was consul', 'Two nouns in the ablative can form an ablative absolute without a participle: ''Cicero being consul'', or better ''When Cicero was consul, the conspiracy of Catiline was exposed.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-406', 'participles_ablative_absolute', 24, 'mc', 'ABLATIVE ABSOLUTE', 'Which phrase is an ablative absolute with no participle and no preposition?<br><em>With Caesar as leader</em>', 'Look for two nouns in the ablative standing on their own.', null, '["Caesare duce","cum Caesare duce","ā Caesare duce","Caesarī ducī"]'::jsonb, 'Caesare duce', 'Caesare duce is two nouns in the ablative with no preposition, so it is an ablative absolute: ''with Caesar as leader''. The phrases with cum and ā are ordinary prepositional phrases.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-407', 'participles_ablative_absolute', 25, 'typein', 'ABLATIVE ABSOLUTE', 'Put <strong>oppidum captum</strong> into the ablative absolute:<br>______, cīvēs in silvās fūgērunt.<br><em>After the town had been captured, the citizens fled into the woods.</em>', 'oppidum is 2nd declension neuter. Both words go into the ablative singular.', '["oppido capto","capto oppido"]'::jsonb, null, null, 'The noun and participle both go into the ablative: oppidō captō, ''after the town had been captured''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-408', 'participles_ablative_absolute', 26, 'typein', 'ABLATIVE ABSOLUTE', 'Put <strong>hostēs victī</strong> into the ablative absolute:<br>______, Rōmānī in castra rediērunt.<br><em>After the enemy had been defeated, the Romans returned to camp.</em>', 'Both words are plural. hostis is 3rd declension; victus is 1st/2nd declension.', '["hostibus victis","victis hostibus"]'::jsonb, null, null, 'The ablative plural of hostēs is hostibus and of victī is victīs: hostibus victīs, ''after the enemy had been defeated''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-409', 'participles_ablative_absolute', 27, 'typein', 'ABLATIVE ABSOLUTE', 'Put <strong>cōnsul dīcēns</strong> into the ablative absolute:<br>______, senātōrēs tacēbant.<br><em>While the consul was speaking, the senators were silent.</em>', 'Both words go into the ablative singular. Check the participle''s ending carefully.', '["consule dicente","dicente consule"]'::jsonb, null, null, 'cōnsul becomes cōnsule, and the present participle takes -e in an ablative absolute: cōnsule dīcente, ''while the consul was speaking''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-501', 'participles_ablative_absolute', 28, 'mc', 'EXAM TRAP', 'Choose the participle that completes the ablative absolute:<br>Rēge ______, cīvēs fēlīcēs erant.<br><em>While the king was ruling, the citizens were happy.</em>', 'Present participles have two ablative singular endings.', null, '["regente","regentī","rēctō","rēctūrō"]'::jsonb, 'regente', 'In an ablative absolute the present participle ends in -e: regente. The -ī ending is used when the participle acts as a plain adjective.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-502', 'participles_ablative_absolute', 29, 'mc', 'EXAM TRAP', 'Rule: Latin does not use an ablative absolute when its noun is also the subject or object of the main verb.<br>Which sentence follows this rule and means:<br><em>The soldiers destroyed the city they had captured.</em>', 'The city is the object of the main verb, so its participle must agree with it in the accusative.', null, '["Mīlitēs urbem captam dēlēvērunt.","Mīlitēs, urbe captā, urbem dēlēvērunt.","Mīlitēs urbem capientem dēlēvērunt.","Mīlitēs urbem captūram dēlēvērunt."]'::jsonb, 'Mīlitēs urbem captam dēlēvērunt.', 'urbs is the object of dēlēvērunt, so the participle agrees with it: urbem captam, ''the city having been captured''. ''The soldiers destroyed the city they had captured.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-503', 'participles_ablative_absolute', 30, 'mc', 'EXAM TRAP', 'Mīlitēs, cōnsulem <strong>secūtī</strong>, in castra rediērunt.<br>Choose the best translation.', 'sequor is deponent, and cōnsulem is accusative.', null, '["Having followed the consul, the soldiers returned to camp.","Having been followed by the consul, the soldiers returned to camp.","About to follow the consul, the soldiers returned to camp.","The soldiers returned to camp and the consul followed them."]'::jsonb, 'Having followed the consul, the soldiers returned to camp.', 'Deponent perfect participles are active, and cōnsulem is the object: ''Having followed the consul, the soldiers returned to camp.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-504', 'participles_ablative_absolute', 31, 'mc', 'EXAM TRAP', 'Mīlitēs <strong>dormientēs</strong> ab hostibus captī sunt.<br>Choose the best translation.', 'The present participle shows the same time as the main verb. What tense is captī sunt?', null, '["While they were sleeping, the soldiers were captured by the enemy.","While they are sleeping, the soldiers were captured by the enemy.","After they had slept, the soldiers were captured by the enemy.","About to sleep, the soldiers were captured by the enemy."]'::jsonb, 'While they were sleeping, the soldiers were captured by the enemy.', 'A present participle shows the same time as the main verb, so with a past main verb it becomes ''while they were ...ing'': ''While they were sleeping, the soldiers were captured by the enemy.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m10-505', 'participles_ablative_absolute', 32, 'mc', 'EXAM TRAP', 'In which sentence do the noun and participle in the ablative <strong>not</strong> form an ablative absolute?', 'An ablative absolute is never the object of a preposition.', null, '["Mīlitēs in urbe captā manēbant.","Urbe captā, mīlitēs discessērunt.","Duce occīsō, hostēs fūgērunt.","Signō datō, mīlitēs prōcessērunt."]'::jsonb, 'Mīlitēs in urbe captā manēbant.', 'In ''in urbe captā'' the phrase is governed by the preposition in, ''in the captured city'', so it is not absolute. The others stand apart from the rest of the sentence.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('indirect_statement', 'M11', 'Indirect Statement', 'Reporting what people say and think', 'Report what someone says, thinks, knows or perceives with an accusative subject and an infinitive. Choose the present, perfect or future infinitive by its time relative to the main verb, use sē and suus for the subject of the main verb, and use negō for ''say that ... not''.', '["Verbs of Saying, Thinking, Knowing and Perceiving","Accusative Subject + Infinitive","Present Infinitive: Same Time","Perfect Infinitive: Time Before","Future Infinitive: Time After","Reflexive sē and suus","negō: Say That ... Not"]'::jsonb, 11) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-101', 'indirect_statement', 0, 'mc', 'TRIGGER', 'Which verb introduces an <strong>indirect statement</strong> (accusative subject + infinitive)?', 'Indirect statement follows verbs of saying, thinking, knowing and perceiving.', null, '["putō","imperō","quaerō","ōrō"]'::jsonb, 'putō', 'putō means ''think'', so it takes an accusative and infinitive. imperō and ōrō introduce indirect commands, and quaerō introduces indirect questions.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-102', 'indirect_statement', 1, 'mc', 'TRIGGER', 'Which verb is followed by an <strong>indirect command</strong> (ut + subjunctive), not an indirect statement?', 'Three of these are verbs of knowing, perceiving or believing.', null, '["rogō","sciō","audiō","crēdō"]'::jsonb, 'rogō', 'rogō, ''ask'', takes ut + subjunctive for a request. sciō, audiō and crēdō report a fact or belief, so they take an accusative and infinitive.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-103', 'indirect_statement', 2, 'mc', 'TRIGGER', 'Which sentence contains an <strong>indirect statement</strong>?', 'An indirect statement reports a fact or belief with an accusative subject and an infinitive.', null, '["Mīlitēs vīdērunt hostēs appropinquāre.","Cōnsul mīlitibus imperāvit ut pugnārent.","Rēx quaesīvit cūr hostēs appropinquārent.","Mīlitēs fortiter pugnāvērunt ut urbem servārent."]'::jsonb, 'Mīlitēs vīdērunt hostēs appropinquāre.', 'vīdērunt is a verb of perceiving, followed by hostēs (accusative) and appropinquāre (infinitive): ''The soldiers saw that the enemy were approaching.'' The others are an indirect command, an indirect question and a purpose clause.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-104', 'indirect_statement', 3, 'mc', 'TRIGGER', 'Nūntius <strong>______</strong> hostēs adesse.<br>Which verb fits the blank?', 'hostēs adesse is an accusative and infinitive. Which verb reports a fact?', null, '["nūntiāvit","quaesīvit","ōrāvit","hortātus est"]'::jsonb, 'nūntiāvit', 'nūntiō, ''announce'', is a verb of saying, so it takes an accusative and infinitive: ''The messenger announced that the enemy were present.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-201', 'indirect_statement', 4, 'typein', 'FORM', 'Complete the indirect statement:<br>Nūntius dīxit hostēs urbem ______ (capere).<br><em>The messenger said that the enemy had captured the city.</em>', 'The capturing happened before the saying: perfect active infinitive.', '["cepisse"]'::jsonb, null, null, 'The perfect active infinitive is the perfect stem + -isse: cēpisse. It shows time before the main verb.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-202', 'indirect_statement', 5, 'typein', 'FORM', 'Complete the indirect statement:<br>Audīvimus captīvōs ad urbem ______ (dūcere).<br><em>We heard that the prisoners were being led to the city.</em>', 'Same time as the hearing, and the prisoners are being led: present passive infinitive.', '["duci"]'::jsonb, null, null, '3rd conjugation verbs form the present passive infinitive with -ī: dūcī, ''to be led''. It shows the same time as audīvimus.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-203', 'indirect_statement', 6, 'typein', 'FORM', 'Complete the indirect statement:<br>Sciō mē ab amīcīs ______ (amāre).<br><em>I know that I am loved by my friends.</em>', 'Same time as the knowing, and I am being loved: present passive infinitive.', '["amari"]'::jsonb, null, null, '1st conjugation verbs form the present passive infinitive with -ārī: amārī, ''to be loved''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-204', 'indirect_statement', 7, 'typein', 'FORM', 'Complete the indirect statement:<br>Lēgātī nūntiāvērunt urbem ______ (capere).<br><em>The envoys announced that the city had been captured.</em>', 'Perfect passive infinitive: perfect passive participle + esse. The participle agrees with urbem.', '["captam esse","captam"]'::jsonb, null, null, 'The perfect passive infinitive is the perfect passive participle + esse. It agrees with urbem, feminine accusative singular: captam esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-205', 'indirect_statement', 8, 'typein', 'FORM', 'Complete the indirect statement:<br>Putāmus cīvēs urbem ______ (relinquere).<br><em>We think that the citizens will leave the city.</em>', 'The 4th principal part is relictum. Future active infinitive: future active participle + esse, agreeing with cīvēs.', '["relicturos esse","relicturos"]'::jsonb, null, null, 'The future active infinitive is the future active participle + esse. It agrees with cīvēs, masculine accusative plural: relictūrōs esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-206', 'indirect_statement', 9, 'typein', 'FORM', 'Complete the indirect statement:<br>Scīmus hostēs nōs ______ (sequor).<br><em>We know that the enemy are following us.</em>', 'sequor is deponent: passive in form, active in meaning. The following happens at the same time as the knowing.', '["sequi"]'::jsonb, null, null, 'A deponent''s present infinitive is passive in form. sequor is 3rd conjugation, so it is sequī, ''to follow''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-207', 'indirect_statement', 10, 'typein', 'FORM', 'Complete the indirect statement:<br>Audīvī lēgātōs Rōmam ______ (proficīscor).<br><em>I heard that the envoys had set out for Rome.</em>', 'The principal parts are proficīscor, proficīscī, profectus sum. Perfect infinitive: participle + esse, agreeing with lēgātōs.', '["profectos esse","profectos"]'::jsonb, null, null, 'A deponent''s perfect infinitive is passive in form but active in meaning: profectōs esse, ''to have set out''. profectōs agrees with lēgātōs.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-208', 'indirect_statement', 11, 'typein', 'FORM', 'Complete the indirect statement:<br>Mārcus crēdit Iūliam crās ______ (discēdere).<br><em>Marcus believes that Julia will leave tomorrow.</em>', 'The 4th principal part is discessum. Future active infinitive, agreeing with Iūliam.', '["discessuram esse","discessuram"]'::jsonb, null, null, 'The future active infinitive is the future active participle + esse. It agrees with Iūliam, feminine accusative singular: discessūram esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-301', 'indirect_statement', 12, 'mc', 'TENSE', 'Dīcit mīlitēs fortiter <strong>______</strong>.<br><em>He says that the soldiers are fighting bravely.</em><br>Choose the infinitive.', 'The fighting happens at the same time as the saying.', null, '["pugnāre","pugnāvisse","pugnātūrōs esse","pugnārent"]'::jsonb, 'pugnāre', 'The present infinitive shows the same time as the main verb: ''He says that the soldiers are fighting bravely.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-302', 'indirect_statement', 13, 'mc', 'TENSE', 'Lēgātus nūntiāvit hostēs <strong>______</strong>.<br><em>The envoy announced that the enemy had fled.</em><br>Choose the infinitive.', 'The fleeing happened before the announcing.', null, '["fūgisse","fugere","fugitūrōs esse","fūgissent"]'::jsonb, 'fūgisse', 'The perfect infinitive shows time before the main verb. After a past verb, English says ''had fled''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-303', 'indirect_statement', 14, 'mc', 'TENSE', 'Cōnsul putābat hostēs castra mox <strong>______</strong>.<br><em>The consul thought that the enemy would soon attack the camp.</em><br>Choose the infinitive.', 'The attack comes after the thinking, and the enemy are the ones attacking.', null, '["oppugnātūrōs esse","oppugnāre","oppugnāvisse","oppugnātōs esse"]'::jsonb, 'oppugnātūrōs esse', 'The future active infinitive shows time after the main verb. After a past verb, English says ''would attack''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-304', 'indirect_statement', 15, 'mc', 'TENSE', 'Spērāmus nōs <strong>______</strong>.<br><em>We hope that we will win.</em><br>Choose the infinitive.', 'The winning is still to come.', null, '["victūrōs esse","victūrum esse","vīcisse","victōs esse"]'::jsonb, 'victūrōs esse', 'Verbs of hoping look ahead, so they take the future infinitive. The participle agrees with nōs, masculine accusative plural: victūrōs esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-305', 'indirect_statement', 16, 'mc', 'TENSE', 'Sciēbam hostēs urbem <strong>oppugnāre</strong>.<br>When was the attack happening?', 'The present infinitive is timed from the main verb, not from now.', null, '["At the time when I knew it","Before I knew it","After I knew it","Right now, as I speak"]'::jsonb, 'At the time when I knew it', 'The present infinitive shows the same time as the main verb. sciēbam is past, so: ''I knew that the enemy were attacking the city.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-306', 'indirect_statement', 17, 'typein', 'TENSE', 'Complete the indirect statement:<br>Dux spērābat mīlitēs urbem ______ (dēfendere).<br><em>The general hoped that the soldiers would defend the city.</em>', 'The 4th principal part is dēfēnsum. A hope looks ahead: future active infinitive, agreeing with mīlitēs.', '["defensuros esse","defensuros"]'::jsonb, null, null, 'Verbs of hoping take the future infinitive. The participle agrees with mīlitēs, masculine accusative plural: dēfēnsūrōs esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-401', 'indirect_statement', 18, 'mc', 'TRANSLATE', 'Translate: <strong>Puella putābat sē fēlīcem esse.</strong>', 'putābat is past; esse shows the same time as the thinking.', null, '["The girl thought that she was happy.","The girl thinks that she is happy.","The girl thought that she had been happy.","The girl thought that she would be happy."]'::jsonb, 'The girl thought that she was happy.', 'The present infinitive shows the same time as the main verb. After a past verb, English says ''was''. sē points back to the girl.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-402', 'indirect_statement', 19, 'mc', 'TRANSLATE', 'Translate: <strong>Dīcunt rēgem mortuum esse.</strong>', 'mortuum esse is the perfect infinitive of the deponent morior, and dīcunt is present.', null, '["They say that the king has died.","They say that the king is dying.","They said that the king had died.","They say that the king will die."]'::jsonb, 'They say that the king has died.', 'The perfect infinitive shows time before the main verb. dīcunt is present, so English says ''has died''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-403', 'indirect_statement', 20, 'mc', 'TRANSLATE', 'Translate: <strong>Mīles dīxit sē in proeliō fortiter pugnāvisse.</strong>', 'pugnāvisse is a perfect infinitive, and dīxit is past.', null, '["The soldier said that he had fought bravely in the battle.","The soldier said that he would fight bravely in the battle.","The soldier says that he has fought bravely in the battle.","The soldier said that another man had fought bravely in the battle."]'::jsonb, 'The soldier said that he had fought bravely in the battle.', 'The perfect infinitive shows time before the main verb. After a past verb, English says ''had fought''. sē points back to the soldier.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-404', 'indirect_statement', 21, 'mc', 'TRANSLATE', 'Translate: <strong>Cōnsul nūntiāvit sē crās Rōmam reditūrum esse.</strong>', 'reditūrum esse looks ahead in time, and nūntiāvit is past.', null, '["The consul announced that he would return to Rome tomorrow.","The consul announces that he will return to Rome tomorrow.","The consul announced that he had returned to Rome.","The consul announced that another man would return to Rome tomorrow."]'::jsonb, 'The consul announced that he would return to Rome tomorrow.', 'The future infinitive shows time after the main verb. After a past verb, English says ''would return''. sē points back to the consul.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-405', 'indirect_statement', 22, 'mc', 'TRANSLATE', 'Translate: <strong>Audīmus urbem ab hostibus oppugnārī.</strong>', 'oppugnārī is a present passive infinitive, and audīmus is present.', null, '["We hear that the city is being attacked by the enemy.","We heard that the city was being attacked by the enemy.","We hear that the city has been attacked by the enemy.","We hear that the city is attacking the enemy."]'::jsonb, 'We hear that the city is being attacked by the enemy.', 'The present passive infinitive shows the same time as the main verb: ''We hear that the city is being attacked by the enemy.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-501', 'indirect_statement', 23, 'mc', 'REFLEXIVE', 'Mārcus dīcit <strong>eum</strong> aegrum esse.<br>Who is sick?', 'Compare sē, which points back to the subject of dīcit.', null, '["Someone other than Marcus","Marcus himself","Marcus and his friend together","Nobody: eum is the object of dīcit"]'::jsonb, 'Someone other than Marcus', 'eum refers to someone else. If Marcus meant himself, the Latin would be: Mārcus dīcit sē aegrum esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-502', 'indirect_statement', 24, 'mc', 'REFLEXIVE', 'Cōnsul dīxit <strong>suam</strong> fīliam aegram esse.<br>Whose daughter was sick?', 'In an indirect statement, suus points back to the subject of the verb of saying.', null, '["The consul''s own daughter","Another man''s daughter","The daughter of the person the consul was talking to","The daughter of a man mentioned earlier"]'::jsonb, 'The consul''s own daughter', 'suam is reflexive and points back to the subject of dīxit: ''The consul said that his own daughter was sick.'' With eius, the daughter would belong to someone else.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-503', 'indirect_statement', 25, 'mc', 'REFLEXIVE', 'Lēgātī nūntiāvērunt <strong>______</strong> ā rēge captōs esse.<br><em>The envoys announced that they (other men, not the envoys) had been captured by the king.</em><br>Which word fills the blank?', 'Were the envoys captured, or other men? The subject of an infinitive is accusative and agrees with captōs.', null, '["eōs","sē","eum","eās"]'::jsonb, 'eōs', 'When the subject of the infinitive is not the subject of the main verb, Latin uses a form of is, ea, id: eōs. sē would mean that the envoys themselves had been captured.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-504', 'indirect_statement', 26, 'typein', 'REFLEXIVE', 'Complete with a pronoun:<br>Rēx putat ______ ab omnibus laudārī.<br><em>The king thinks that he (the king himself) is praised by everyone.</em>', 'The subject of the infinitive is the same person as the subject of putat.', '["se","sese"]'::jsonb, null, null, 'When the subject of the infinitive is the subject of the main verb, Latin uses the reflexive sē: ''The king thinks that he is praised by everyone.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-505', 'indirect_statement', 27, 'typein', 'REFLEXIVE', 'Complete with a possessive adjective:<br>Rēgīna dīxit ______ oppidum pulcherrimum esse.<br><em>The queen said that her own town was very beautiful.</em>', 'Use the reflexive possessive, and make it agree with oppidum.', '["suum"]'::jsonb, null, null, 'The town belongs to the subject of dīxit, so Latin uses the reflexive possessive suus. It agrees with oppidum: suum.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-601', 'indirect_statement', 28, 'mc', 'NEGATIVE', 'Translate: <strong>Explōrātōrēs negant hostēs prope esse.</strong>', 'negō does not mean ''say''. It carries its own ''not''.', null, '["The scouts say that the enemy are not near.","The scouts say that the enemy are near.","The scouts said that the enemy were not near.","The scouts ask whether the enemy are near."]'::jsonb, 'The scouts say that the enemy are not near.', 'negō means ''say that ... not'' or ''deny'': ''The scouts say that the enemy are not near.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-602', 'indirect_statement', 29, 'typein', 'NEGATIVE', 'Complete with one verb in the perfect tense:<br>______ sē ventūrum esse.<br><em>He said that he would not come.</em>', 'Latin avoids dīxit ... nōn here. Use the verb that means ''say that ... not''.', '["negavit"]'::jsonb, null, null, 'negō means ''say that ... not'' or ''deny'': Negāvit sē ventūrum esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-603', 'indirect_statement', 30, 'typein', 'NEGATIVE', 'Complete with one verb in the present tense:<br>Cōnsul ______ urbem in perīculō esse.<br><em>The consul says that the city is not in danger.</em>', 'Latin avoids dīcit ... nōn here. Use the verb that means ''say that ... not''.', '["negat"]'::jsonb, null, null, 'negō means ''say that ... not'' or ''deny'': Cōnsul negat urbem in perīculō esse.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-701', 'indirect_statement', 31, 'mc', 'EXAM TRAP', 'Choose the correct Latin for:<br><em>The envoys said that the king was coming.</em>', 'English ''that'' after a verb of saying has no Latin word of its own.', null, '["Lēgātī dīxērunt rēgem venīre.","Lēgātī dīxērunt ut rēx venīret.","Lēgātī dīxērunt quod rēx veniēbat.","Lēgātī dīxērunt rēgem vēnisse."]'::jsonb, 'Lēgātī dīxērunt rēgem venīre.', 'Indirect statement has no word for ''that'': the subject becomes accusative and the verb becomes an infinitive. ut would make it a command, in classical prose quod is not used after dīcō, and vēnisse would mean ''had come''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m11-702', 'indirect_statement', 32, 'mc', 'EXAM TRAP', 'A student writes <strong>Spērō cōnsulem urbem servāre</strong> for <em>I hope that the consul will save the city.</em><br>Which form should replace servāre so the Latin matches the English?', 'The saving is still to come, and the participle agrees with cōnsulem.', null, '["servātūrum esse","servātūrus esse","servāvisse","ut servet"]'::jsonb, 'servātūrum esse', 'A hope looks ahead, so verbs of hoping take the future infinitive. servātūrum agrees with cōnsulem: ''Spērō cōnsulem urbem servātūrum esse.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('gerund_gerundive', 'M12', 'Gerund and Gerundive', 'Verbal nouns, verbal adjectives and ''must''', 'Form and recognize the gerund, a verbal noun, and the gerundive, a verbal adjective. Use the gerundive in place of a gerund with an object, express purpose with ad or with causā and grātiā, and show obligation with gerundive + sum and a dative of agent.', '["Gerund: a Verbal Noun","Gerundive: a Verbal Adjective","Gerundive in Place of Gerund + Object","Passive Periphrastic (Obligation)","Dative of Agent","Impersonal Passive Periphrastic","Purpose: ad + Gerund or Gerundive","Purpose: causā or grātiā + Genitive"]'::jsonb, 12) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-101', 'gerund_gerundive', 0, 'typein', 'FORM', 'Complete with a gerund:<br>Captīvī occāsiōnem ______ (fugere) exspectābant.<br><em>The prisoners were waiting for a chance to escape.</em>', 'occāsiōnem needs a genitive: ''a chance of escaping''. -iō verbs keep their i.', '["fugiendi"]'::jsonb, null, null, 'The genitive gerund ends in -ndī. fugiō is a 3rd conjugation -iō verb, so the stem keeps its i: fugiendī. ''a chance to escape''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-102', 'gerund_gerundive', 1, 'typein', 'FORM', 'Complete with a gerund:<br>Aqua ūtilis est ______ (bibere).<br><em>Water is useful for drinking.</em>', 'ūtilis takes the dative.', '["bibendo"]'::jsonb, null, null, 'The dative gerund ends in -ndō. ūtilis takes the dative, so bibendō means ''for drinking''. ad bibendum is also common.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-103', 'gerund_gerundive', 2, 'typein', 'FORM', 'Complete with a gerund:<br>Hostēs ad ______ (resistere) parātī erant.<br><em>The enemy were ready to resist.</em>', 'ad takes the accusative.', '["resistendum"]'::jsonb, null, null, 'After ad the gerund is accusative and ends in -ndum: ad resistendum, ''ready to resist''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-104', 'gerund_gerundive', 3, 'typein', 'FORM', 'Complete with a gerund:<br>Discipulī ______ (audīre) multa discunt.<br><em>Pupils learn many things by listening.</em>', '''By listening'' shows the means. 4th conjugation verbs add -ie- before -nd-.', '["audiendo"]'::jsonb, null, null, 'The ablative gerund shows means and ends in -ndō. audiō is 4th conjugation, so the stem is audie-: audiendō, ''by listening''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-105', 'gerund_gerundive', 4, 'typein', 'FORM', 'Complete with a gerund:<br>Dux ______ (hortārī) perītus erat.<br><em>The general was skilled at encouraging.</em>', 'perītus takes the genitive. A deponent verb''s gerund is formed the same way as any other.', '["hortandi"]'::jsonb, null, null, 'perītus takes the genitive, so the gerund ends in -ndī. Deponent verbs have ordinary gerunds with active meaning: hortandī, ''skilled at encouraging''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-106', 'gerund_gerundive', 5, 'typein', 'FORM', 'Complete with a gerundive:<br>Cīvēs spem urbis ______ (dēfendere) āmīsērunt.<br><em>The citizens lost hope of defending the city.</em>', 'The gerundive agrees with urbis. What gender, number and case is urbis?', '["defendendae"]'::jsonb, null, null, 'Instead of a gerund with an object, Latin puts the noun in the gerund''s case and makes the gerundive agree with it. urbis is feminine genitive singular, so: urbis dēfendendae, ''of defending the city''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-201', 'gerund_gerundive', 6, 'mc', 'IDENTIFY', 'In the phrase <strong>ars bene dīcendī</strong>, what is dīcendī?', 'Is there a noun for it to agree with?', null, '["A gerund in the genitive","A gerundive agreeing with ars","A present participle","A present passive infinitive"]'::jsonb, 'A gerund in the genitive', 'dīcendī does not agree with ars (feminine nominative), so it is a gerund, a verbal noun, in the genitive: ''the art of speaking well''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-202', 'gerund_gerundive', 7, 'mc', 'IDENTIFY', 'Mīlitēs in mūrō <strong>aedificandō</strong> labōrābant.<br><em>The soldiers were working on building the wall.</em><br>What is aedificandō?', 'Look for a noun in the same gender, number and case.', null, '["A gerundive agreeing with mūrō","A gerund in the ablative","A present participle","A perfect passive participle"]'::jsonb, 'A gerundive agreeing with mūrō', 'aedificandō agrees with mūrō (masculine ablative singular), so it is a gerundive, a verbal adjective. A gerund with an object would need mūrum in the accusative.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-203', 'gerund_gerundive', 8, 'mc', 'IDENTIFY', 'Mīlitēs urbem <strong>oppugnantēs</strong> vīdimus.<br><em>We saw the soldiers attacking the city.</em><br>What is oppugnantēs?', 'Look at the letters just before the ending.', null, '["A present active participle agreeing with mīlitēs","A gerundive agreeing with mīlitēs","A gerund in the accusative","A present active infinitive"]'::jsonb, 'A present active participle agreeing with mīlitēs', 'oppugnantēs has -nt-, so it is a present active participle agreeing with mīlitēs: ''attacking''. Gerunds and gerundives have -nd-.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-204', 'gerund_gerundive', 9, 'mc', 'IDENTIFY', 'Mīlitēs dē <strong>discēdendō</strong> cōgitābant.<br><em>The soldiers were thinking about leaving.</em><br>What case is the gerund discēdendō?', 'Which case does dē take?', null, '["Ablative","Dative","Accusative","Genitive"]'::jsonb, 'Ablative', 'dē takes the ablative, so discēdendō is an ablative gerund: ''about leaving''. The ending -ndō is also dative, but the preposition settles it.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-205', 'gerund_gerundive', 10, 'mc', 'IDENTIFY', '<strong>Errāre</strong> hūmānum est.<br><em>To err is human.</em><br>Why is the subject an infinitive and not a gerund?', 'Think about the forms the gerund has.', null, '["The gerund has no nominative, so the infinitive serves as the subject.","The gerund is passive in meaning, so it cannot be the subject.","The gerund needs a preposition, so it cannot stand alone as the subject.","The gerund must agree with a noun, so it cannot stand alone here."]'::jsonb, 'The gerund has no nominative, so the infinitive serves as the subject.', 'The gerund has no nominative, so Latin uses the infinitive as a verbal noun subject: errāre, ''to err''. The gerund supplies the other cases: errandī, errandō, ad errandum.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-301', 'gerund_gerundive', 11, 'typein', 'PURPOSE', 'Complete with a gerundive:<br>Lēgātī vēnērunt ad pācem ______ (petere).<br><em>The envoys came to seek peace.</em>', 'After ad, the gerundive agrees with its noun. pācem is feminine accusative singular.', '["petendam"]'::jsonb, null, null, 'ad + noun + gerundive shows purpose. The gerundive takes the noun''s gender, number and case: pācem petendam.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-302', 'gerund_gerundive', 12, 'typein', 'PURPOSE', 'Complete with a gerund:<br>Mīlitēs ______ (frūmentārī) causā ē castrīs exiērunt.<br><em>The soldiers left the camp to gather grain.</em>', 'causā follows a genitive.', '["frumentandi"]'::jsonb, null, null, 'causā, ''for the sake of'', takes a genitive placed before it, so the gerund ends in -ndī: frūmentandī causā, ''to gather grain''. frūmentor is deponent, but its gerund is formed as usual.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-303', 'gerund_gerundive', 13, 'typein', 'PURPOSE', 'Complete with a gerundive:<br>Plēbs lībertātis ______ (recuperāre) causā arma cēpit.<br><em>The common people took up arms to recover their freedom.</em>', 'The gerundive agrees with lībertātis.', '["recuperandae"]'::jsonb, null, null, 'causā takes the genitive, and the gerundive agrees with lībertātis (feminine genitive singular): lībertātis recuperandae causā, ''to recover their freedom''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-304', 'gerund_gerundive', 14, 'mc', 'PURPOSE', 'Mīlitēs vēnērunt <strong>______</strong>.<br><em>The soldiers came to capture the city.</em><br>Which phrase fits the blank?', 'Think about how Latin handles a gerund that would take a direct object.', null, '["ad urbem capiendam","ad capiendum urbem","ad urbem capiendum","ad urbem capientem"]'::jsonb, 'ad urbem capiendam', 'After ad, Latin normally avoids a gerund with a direct object and prefers the gerundive. The noun takes the case and the gerundive agrees with it: ad urbem capiendam, ''to capture the city''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-305', 'gerund_gerundive', 15, 'mc', 'PURPOSE', 'Which phrase means <em>for the sake of making peace</em>?', 'Check the case of each word.', null, '["pācis faciendae causā","pācem faciendam causā","pācis faciendae causam","pāce faciendā causā"]'::jsonb, 'pācis faciendae causā', 'causā follows a genitive, and the gerundive agrees with pācis (feminine genitive singular): pācis faciendae causā, ''for the sake of making peace''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-306', 'gerund_gerundive', 16, 'mc', 'PURPOSE', 'Translate: <strong>Mīlitēs frūmentī comparandī grātiā in agrōs exiērunt.</strong>', 'Look at the case of frūmentī comparandī and the word after it.', null, '["The soldiers went out into the fields to get grain.","The soldiers went out into the fields after getting grain.","The soldiers went out into the fields thanks to the grain they had gathered.","The soldiers went out into the fields while grain was being gathered."]'::jsonb, 'The soldiers went out into the fields to get grain.', 'grātiā after a genitive means ''for the sake of'', just like causā. frūmentī comparandī grātiā shows purpose: ''The soldiers went out into the fields to get grain.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-307', 'gerund_gerundive', 17, 'mc', 'PURPOSE', 'Translate: <strong>Hostēs ad agrōs vāstandōs vēnērunt.</strong>', 'Look at how vāstandōs relates to agrōs.', null, '["The enemy came to ravage the fields.","The enemy came because the fields had been ravaged.","The enemy came to the fields they were ravaging.","The enemy came after ravaging the fields."]'::jsonb, 'The enemy came to ravage the fields.', 'ad agrōs vāstandōs is ad + accusative + gerundive, which shows purpose: ''The enemy came to ravage the fields.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-401', 'gerund_gerundive', 18, 'mc', 'OBLIGATION', 'Translate: <strong>Hostēs nōbīs vincendī sunt.</strong>', 'Gerundive + sum shows obligation. Who does the conquering?', null, '["The enemy must be conquered by us.","The enemy must conquer us.","The enemy were conquered by us.","We must be conquered by the enemy."]'::jsonb, 'The enemy must be conquered by us.', 'This is a passive periphrastic: the enemy are ''to be conquered''. nōbīs is a dative of agent, ''by us''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-402', 'gerund_gerundive', 19, 'mc', 'OBLIGATION', 'Translate: <strong>Pōns mīlitibus rescindendus erat.</strong>', 'The tense of sum gives the time of the obligation.', null, '["The bridge had to be broken down by the soldiers.","The bridge must be broken down by the soldiers.","The bridge will have to be broken down by the soldiers.","The bridge was being broken down by the soldiers."]'::jsonb, 'The bridge had to be broken down by the soldiers.', 'Gerundive + erat is a passive periphrastic in the past: ''had to be broken down''. mīlitibus is a dative of agent: ''The bridge had to be broken down by the soldiers.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-403', 'gerund_gerundive', 20, 'typein', 'OBLIGATION', 'Complete with a form of sum:<br>Castra mīlitibus crās mūnienda ______.<br><em>The camp will have to be fortified by the soldiers tomorrow.</em>', 'castra is plural in form. Which tense looks ahead?', '["erunt"]'::jsonb, null, null, 'castra is neuter plural, so the gerundive is mūnienda and sum is plural. ''Will have to'' needs the future: erunt.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-404', 'gerund_gerundive', 21, 'typein', 'OBLIGATION', 'Complete with a gerundive:<br>Haec epistula tibi ______ est (mittere).<br><em>This letter must be sent by you.</em>', 'The gerundive agrees with the subject, epistula.', '["mittenda"]'::jsonb, null, null, 'In a passive periphrastic the gerundive agrees with the subject. epistula is feminine nominative singular: mittenda est, ''must be sent''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-405', 'gerund_gerundive', 22, 'typein', 'OBLIGATION', 'Complete with a dative of agent:<br>Lēgēs ______ servandae sunt (cīvēs).<br><em>The laws must be kept by the citizens.</em>', 'With gerundive + sum, the person who must act goes in the dative.', '["civibus"]'::jsonb, null, null, 'With a passive periphrastic, ''by'' a person is a dative of agent, not ā/ab + ablative: cīvibus, ''by the citizens''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-406', 'gerund_gerundive', 23, 'mc', 'OBLIGATION', 'Translate: <strong>Nōbīs pugnandum est.</strong>', 'Look at the ending of pugnandum and the case of nōbīs.', null, '["We must fight.","We are about to fight.","We were fighting.","They must fight us."]'::jsonb, 'We must fight.', 'With a verb that has no direct object, the periphrastic is impersonal: ''it must be fought by us'', that is, ''We must fight.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-407', 'gerund_gerundive', 24, 'mc', 'OBLIGATION', 'Which sentence means <em>The soldiers had to hurry</em>?', 'Who does the hurrying, and when?', null, '["Mīlitibus festīnandum erat.","Mīlitēs festīnandī erant.","Mīlitibus festīnandum est.","Mīlitibus festīnātum erat."]'::jsonb, 'Mīlitibus festīnandum erat.', 'festīnō has no direct object, so Latin says ''it had to be hurried by the soldiers'': neuter festīnandum, dative mīlitibus, and erat for the past.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-408', 'gerund_gerundive', 25, 'mc', 'OBLIGATION', 'Cato ended his speeches with <strong>Carthāgō dēlenda est</strong>. What does it mean?', 'dēlenda is a gerundive.', null, '["Carthage must be destroyed.","Carthage has been destroyed.","Carthage is being destroyed.","Carthage must destroy."]'::jsonb, 'Carthage must be destroyed.', 'dēlenda is a gerundive agreeing with Carthāgō, and with est it shows obligation: ''Carthage must be destroyed.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-501', 'gerund_gerundive', 26, 'mc', 'TRANSLATE', 'Translate: <strong>ars scrībendī</strong>', 'Look at the -nd- form and its case.', null, '["the art of writing","the art that must be written","the written art","the art of the writer"]'::jsonb, 'the art of writing', 'scrībendī is a genitive gerund, a verbal noun: ''the art of writing''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-502', 'gerund_gerundive', 27, 'mc', 'TRANSLATE', 'Translate: <strong>Puerī cupidī videndī ad forum cucurrērunt.</strong>', 'cupidus takes a genitive.', null, '["The boys, eager to see, ran to the forum.","The boys ran to the forum to be seen.","The boys ran to the forum because they had seen it.","The boys, who had to be seen, ran to the forum."]'::jsonb, 'The boys, eager to see, ran to the forum.', 'cupidus takes the genitive, and videndī is a genitive gerund: ''eager to see''. ''The boys, eager to see, ran to the forum.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-503', 'gerund_gerundive', 28, 'mc', 'TRANSLATE', 'Translate: <strong>Legendō discimus.</strong>', 'legendō is ablative. What does the ablative often show?', null, '["We learn by reading.","We learn in order to read.","We must learn to read.","We learn what must be read."]'::jsonb, 'We learn by reading.', 'legendō is an ablative gerund showing means: ''We learn by reading.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-504', 'gerund_gerundive', 29, 'mc', 'TRANSLATE', 'Translate: <strong>Tempus est abeundī.</strong>', 'Look at the case of abeundī.', null, '["It is time to leave.","It is time to have left.","Time is leaving.","Time must leave."]'::jsonb, 'It is time to leave.', 'abeundī is the genitive gerund of abeō, depending on tempus: ''time of going away'', so ''It is time to leave.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-505', 'gerund_gerundive', 30, 'typein', 'TRANSLATE', 'Complete the set phrase with a gerund:<br>Cōnsul fīnem ______ (loquī) fēcit.<br><em>The consul stopped speaking.</em> (literally <em>made an end of speaking</em>)', 'fīnem needs a genitive.', '["loquendi"]'::jsonb, null, null, 'fīnem facere, ''to make an end'', takes a genitive. loquor is deponent, and its gerund is loquendī: ''made an end of speaking'', so ''stopped speaking''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-601', 'gerund_gerundive', 31, 'mc', 'EXAM TRAP', 'Which sentence means <em>The city is being attacked by the consul</em>?', 'Is this an ordinary passive or an obligation?', null, '["Urbs ā cōnsule oppugnātur.","Urbs cōnsulī oppugnātur.","Urbs cōnsulī oppugnanda est.","Urbs ā cōnsule oppugnanda est."]'::jsonb, 'Urbs ā cōnsule oppugnātur.', 'With an ordinary passive verb, the person who does the action is ā/ab + ablative: ā cōnsule. The dative of agent goes with gerundive + sum, which would mean ''must be attacked''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m12-602', 'gerund_gerundive', 32, 'mc', 'EXAM TRAP', 'Translate: <strong>Cōnsul librum legendum mihi dedit.</strong>', 'What does a gerundive mean on its own?', null, '["The consul gave me a book to read.","The consul gave me a book that was being read.","The consul gave me a book while reading.","The consul gave me the book he had read."]'::jsonb, 'The consul gave me a book to read.', 'legendum is a gerundive agreeing with librum. With dō it shows what is to be done: ''a book to be read'', so ''The consul gave me a book to read.'' A gerundive means ''to be ...ed'', never ''being ...ed''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.modules (id, badge, title, tagline, description, concepts, sort) values ('case_uses', 'M13', 'Noun Case Uses', 'Ablative, dative, genitive and accusative at work', 'Name the job a noun''s case is doing, and choose the right case for each job. Covers the main uses of the ablative (means, manner, accompaniment, time when and within which, agent, comparison, separation, cause and description), the dative (indirect object, special verbs, possession, purpose and reference), the genitive (partitive and description) and the accusative (extent of time and space, and place to which).', '["Ablative: Means, Manner, Accompaniment","Ablative: Time When and Time Within Which","Ablative: Agent, Comparison, Separation, Cause","Ablative of Description","Dative: Indirect Object and Special Verbs","Dative: Possession, Purpose and Reference","Genitive: Partitive and Description","Accusative: Extent and Place to Which"]'::jsonb, 13) on conflict (id) do update set badge = excluded.badge, title = excluded.title, tagline = excluded.tagline, description = excluded.description, concepts = excluded.concepts, sort = excluded.sort;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-101', 'case_uses', 0, 'mc', 'ABLATIVE', 'Mīlitēs hostēs <strong>gladiīs</strong> necāvērunt.<br>What use of the ablative is bolded?', 'Is it a person or a tool? Is there a preposition?', null, '["Means","Manner","Accompaniment","Agent"]'::jsonb, 'Means', 'A tool, with no preposition: ablative of means. ''The soldiers killed the enemy with swords.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-102', 'case_uses', 1, 'mc', 'ABLATIVE', 'Mīlitēs <strong>magnā cum virtūte</strong> pugnāvērunt.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Manner","Means","Accompaniment","Cause"]'::jsonb, 'Manner', 'A quality that shows how something was done, with cum: ablative of manner. ''The soldiers fought with great courage.'' Means never takes cum.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-103', 'case_uses', 2, 'mc', 'ABLATIVE', 'Lēgātus <strong>cum mīlitibus</strong> ad castra vēnit.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Accompaniment","Manner","Means","Agent"]'::jsonb, 'Accompaniment', 'cum + a person who goes along: ablative of accompaniment. ''The envoy came to the camp with the soldiers.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-104', 'case_uses', 3, 'mc', 'ABLATIVE', '<strong>Prīmā lūce</strong> Caesar castra mōvit.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Time when","Means","Manner","Cause"]'::jsonb, 'Time when', 'A point in time, with no preposition: ablative of time when. ''At dawn Caesar moved camp.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-105', 'case_uses', 4, 'mc', 'ABLATIVE', 'Hostēs <strong>tribus hōrīs</strong> oppidum cēpērunt.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Time within which","Means","Manner","Cause"]'::jsonb, 'Time within which', 'A stretch of time inside which something is done: ablative of time within which. ''The enemy took the town within three hours.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-106', 'case_uses', 5, 'mc', 'ABLATIVE', 'Hostēs <strong>ā Rōmānīs</strong> victī sunt.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Agent","Means","Separation","Cause"]'::jsonb, 'Agent', 'ā/ab + a person with a passive verb: ablative of agent. ''The enemy were defeated by the Romans.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-107', 'case_uses', 6, 'mc', 'ABLATIVE', 'Nihil est <strong>virtūte</strong> amābilius.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Comparison","Means","Manner","Cause"]'::jsonb, 'Comparison', 'After a comparative (amābilius), the ablative means ''than'': ablative of comparison. ''Nothing is more lovable than virtue.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-108', 'case_uses', 7, 'mc', 'ABLATIVE', 'Mīlitēs hostēs <strong>oppidō</strong> prohibuērunt.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Separation","Means","Cause","Agent"]'::jsonb, 'Separation', 'prohibeō, ''keep away'', takes an ablative of the thing kept away from: ablative of separation. ''The soldiers kept the enemy away from the town.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-109', 'case_uses', 8, 'mc', 'ABLATIVE', 'Cōnsul <strong>victōriā</strong> gaudēbat.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Cause","Time when","Separation","Comparison"]'::jsonb, 'Cause', 'Verbs of feeling such as gaudeō take an ablative of the reason for the feeling: ablative of cause. ''The consul was glad because of the victory.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-110', 'case_uses', 9, 'mc', 'ABLATIVE', 'Ille mīles erat <strong>ingentī corpore</strong>.<br>What use of the ablative is bolded?', 'Ask what the bolded phrase tells you about the action, and check for a preposition.', null, '["Description","Manner","Means","Cause"]'::jsonb, 'Description', 'A noun with an adjective that describes a person: ablative of description. ''That soldier was of huge build.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-201', 'case_uses', 10, 'mc', 'DATIVE', '<strong>Mihi</strong> est fīlia.<br>What use of the dative is bolded?', 'Dative + a form of sum.', null, '["Possession","Indirect object","Purpose","Agent"]'::jsonb, 'Possession', 'Dative with sum names the owner: ''I have a daughter'' (literally ''there is a daughter to me'').') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-202', 'case_uses', 11, 'mc', 'DATIVE', 'Caesar quīnque cohortēs castrīs <strong>praesidiō</strong> relīquit.<br>What use of the dative is bolded?', 'Ask what the bolded word tells you about the cohorts.', null, '["Purpose","Indirect object","With a special verb","Agent"]'::jsonb, 'Purpose', 'praesidiō names the job the cohorts are meant to do: dative of purpose. With castrīs it forms a double dative. ''Caesar left five cohorts as a guard for the camp.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-203', 'case_uses', 12, 'mc', 'DATIVE', 'Agricola <strong>līberīs</strong> agrum colit.<br>What use of the dative is bolded?', 'Ask how the bolded word is connected to the action.', null, '["Reference","Indirect object","With a special verb","Agent"]'::jsonb, 'Reference', 'No giving or telling and no sum: the dative names the people the action is done for. Dative of reference. ''The farmer works the land for his children.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-204', 'case_uses', 13, 'mc', 'DATIVE', 'Lēgātus <strong>cōnsulī</strong> epistulam trādidit.<br>What use of the dative is bolded?', 'Look at everything trādō has with it in the sentence.', null, '["Indirect object","With a special verb","Purpose","Agent"]'::jsonb, 'Indirect object', 'trādō, ''hand over'', takes an accusative (epistulam) and a dative of the person who receives it: indirect object. ''The envoy handed the letter to the consul.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-205', 'case_uses', 14, 'mc', 'DATIVE', 'Caesar <strong>hostibus</strong> pepercit.<br>What use of the dative is bolded?', 'Ask what job the bolded word does for pepercit.', null, '["With a special verb","Possession","Purpose","Agent"]'::jsonb, 'With a special verb', 'parcō, ''spare'', is one of the verbs that take the dative instead of an accusative: dative with a special verb. ''Caesar spared the enemy.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-301', 'case_uses', 15, 'mc', 'GENITIVE', 'Nēmō <strong>nostrum</strong> hoc fēcit.<br>What use of the genitive is bolded?', 'nostrum and nostrī are both genitives of nōs, but they have different jobs.', null, '["Partitive","Description","Possession","Objective"]'::jsonb, 'Partitive', 'nostrum names the whole group that nēmō is taken from: partitive genitive. ''None of us did this.'' The objective genitive would be nostrī.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-302', 'case_uses', 16, 'mc', 'GENITIVE', 'Erat in castrīs mīles <strong>summae audāciae</strong>.<br>What use of the genitive is bolded?', 'Ask what the bolded phrase tells you about the soldier.', null, '["Description","Partitive","Possession","Objective"]'::jsonb, 'Description', 'A noun with an adjective in the genitive that describes a person: genitive of description. ''There was in the camp a soldier of the greatest daring.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-401', 'case_uses', 17, 'mc', 'ACCUSATIVE', 'Mūrus <strong>decem pedēs</strong> altus erat.<br>What use of the accusative is bolded?', 'altus is an adjective, so it cannot take a direct object.', null, '["Extent of space","Extent of time","Place to which","Direct object"]'::jsonb, 'Extent of space', 'The accusative measures how far something stretches: accusative of extent of space. ''The wall was ten feet high.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-402', 'case_uses', 18, 'mc', 'ACCUSATIVE', 'Cōnsul <strong>Athēnās</strong> profectus est.<br>What use of the accusative is bolded?', 'profectus est is deponent, so it cannot take a direct object.', null, '["Place to which","Extent of space","Extent of time","Direct object"]'::jsonb, 'Place to which', 'Names of cities take the accusative with no preposition to show where someone goes: place to which. ''The consul set out for Athens.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-501', 'case_uses', 19, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Cōnsul ______ (amīcus) in forum vēnit.<br><em>The consul came into the forum with a friend.</em>', 'A person who goes along with someone.', '["cum amico"]'::jsonb, null, null, 'Ablative of accompaniment: cum + the ablative of a person. cum amīcō, ''with a friend''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-502', 'case_uses', 20, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Mīles hostem ______ (gladius) vulnerāvit.<br><em>The soldier wounded the enemy with a sword.</em>', 'A sword is a tool, not a person.', '["gladio"]'::jsonb, null, null, 'Ablative of means: a tool, in the ablative with no preposition. gladiō, ''with a sword''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-503', 'case_uses', 21, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Mīlitēs ______ (magnus clāmor) impetum fēcērunt.<br><em>The soldiers attacked with a great shout.</em>', 'This phrase tells how they attacked.', '["magno cum clamore","magno clamore","cum magno clamore"]'::jsonb, null, null, 'Ablative of manner. With an adjective, cum is optional and usually sits between the adjective and the noun: magnō cum clāmōre or magnō clāmōre, ''with a great shout''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-504', 'case_uses', 22, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Lēgātī ______ (rēx) missī sunt.<br><em>The envoys were sent by the king.</em>', 'The doer of a passive verb is a person.', '["a rege","ab rege"]'::jsonb, null, null, 'Ablative of agent: ā/ab + the ablative of a person with a passive verb. ā rēge, ''by the king''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-505', 'case_uses', 23, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Nēmō fortior est ______ (Caesar).<br><em>No one is braver than Caesar.</em>', 'After a comparative, use the ablative of comparison, or quam + the same case as the other noun.', '["caesare","quam caesar"]'::jsonb, null, null, 'Ablative of comparison: Caesare. Latin can also say quam Caesar, with Caesar in the same case as nēmō.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-506', 'case_uses', 24, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Hostēs ______ (metus) fūgērunt.<br><em>The enemy fled out of fear.</em>', 'The phrase gives the reason they fled. metus is 4th declension.', '["metu","propter metum"]'::jsonb, null, null, 'Ablative of cause: metū, ''out of fear''. propter metum, ''because of fear'', says the same thing.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-507', 'case_uses', 25, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Caesar ______ (paucī diēs) ad urbem pervēnit.<br><em>Caesar reached the city within a few days.</em>', 'Time within which uses the same case as time when.', '["paucis diebus","intra paucos dies"]'::jsonb, null, null, 'Ablative of time within which: paucīs diēbus, ''within a few days''. intrā paucōs diēs says the same thing.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-508', 'case_uses', 26, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Cōnsul ______ (ego) nōn crēdit.<br><em>The consul does not believe me.</em>', 'Think about which case crēdō takes.', '["mihi"]'::jsonb, null, null, 'crēdō, ''believe, trust'', takes the dative: mihi. ''The consul does not believe me.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-509', 'case_uses', 27, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Caesar legiōnem sociīs ______ (auxilium) mīsit.<br><em>Caesar sent a legion to help the allies.</em> (literally <em>as a help to the allies</em>)', 'The blank names the job the legion is sent to do.', '["auxilio"]'::jsonb, null, null, 'Dative of purpose: auxiliō, ''as a help''. With sociīs it forms a double dative: ''as a help to the allies''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-510', 'case_uses', 28, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Magna pars ______ (mīles) in castrīs mānsit.<br><em>A large part of the soldiers stayed in the camp.</em>', 'pars needs the whole it is a part of.', '["militum"]'::jsonb, null, null, 'Partitive genitive: mīlitum names the whole group that pars is taken from. ''A large part of the soldiers''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-511', 'case_uses', 29, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Mīlitēs ______ (trēs hōrae) pugnāvērunt.<br><em>The soldiers fought for three hours.</em>', 'How long did the fighting last?', '["tres horas","per tres horas"]'::jsonb, null, null, 'Accusative of extent of time: trēs hōrās, ''for three hours''. per trēs hōrās says the same thing.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-512', 'case_uses', 30, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Lēgātī ______ (Rōma) profectī sunt.<br><em>The envoys set out for Rome.</em>', 'Rōma is the name of a city.', '["romam"]'::jsonb, null, null, 'Place to which: names of cities take the accusative with no preposition. Rōmam, ''to Rome''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-513', 'case_uses', 31, 'typein', 'FORM', 'Complete with the right form, adding a preposition only if Latin needs one:<br>Post proelium mīlitēs ______ (domus) rediērunt.<br><em>After the battle the soldiers went back home.</em>', 'domus follows the same rule as names of cities.', '["domum"]'::jsonb, null, null, 'Place to which: domus, like a city name, takes the accusative with no preposition. domum, ''home''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-601', 'case_uses', 32, 'mc', 'EXAM TRAP', '<strong>Vir magnae virtūtis</strong> and <strong>vir magnā virtūte</strong> are both offered for <em>a man of great courage</em>. Which statement is true?', 'Check what the ablative of description needs.', null, '["Both are correct; a quality with an adjective can be either case.","Only the genitive is correct; magnā virtūte must mean ''by great courage''.","Only the ablative is correct; the genitive is only for size and number.","The ablative needs cum here, so it must be vir cum magnā virtūte."]'::jsonb, 'Both are correct; a quality with an adjective can be either case.', 'A quality described by a noun with an adjective can be genitive (magnae virtūtis) or ablative (magnā virtūte), and the ablative needs no cum. Both mean ''a man of great courage''.') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-602', 'case_uses', 33, 'mc', 'EXAM TRAP', 'Which sentence means <em>The soldier was wounded by the enemy with an arrow</em>?', 'One phrase is a person and one is a thing. Do they both take a preposition?', null, '["Mīles ab hoste sagittā vulnerātus est.","Mīles hoste ā sagittā vulnerātus est.","Mīles ab hoste ā sagittā vulnerātus est.","Mīles hoste sagittā vulnerātus est."]'::jsonb, 'Mīles ab hoste sagittā vulnerātus est.', 'The person who does a passive action is ā/ab + ablative (ab hoste). The thing used is a bare ablative of means (sagittā). ''The soldier was wounded by the enemy with an arrow.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
insert into public.questions (id, module_id, position, type, badge, prompt, hint, answers, choices, correct, explanation) values ('m13-603', 'case_uses', 34, 'mc', 'EXAM TRAP', 'Mīlitēs <strong>tōtam noctem</strong> vigilāvērunt.<br>Why is the bolded phrase accusative, not ablative?', 'Ask what question the phrase answers about vigilāvērunt.', null, '["It says how long the action lasted.","It says when the action happened.","It says where the soldiers went.","It is the direct object of vigilāvērunt."]'::jsonb, 'It says how long the action lasted.', 'The accusative shows how long an action lasts (extent of time). The ablative would show when it happened. ''The soldiers stayed awake all night.''') on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, type = excluded.type, badge = excluded.badge, prompt = excluded.prompt, hint = excluded.hint, answers = excluded.answers, choices = excluded.choices, correct = excluded.correct, explanation = excluded.explanation;
